# Updated: Secret Rotation + Replay Protection

Two changes on top of the existing scheme:

1. **Dual-secret verification** — accept either the current secret or the previous one (rotation overlap), trying both in constant time.
2. **Replay cache** — reject any event ID seen in the last 10 minutes.

## Express (Node.js)

```js
const crypto = require("crypto");

const MAX_AGE_SECONDS = 300;      // timestamp freshness: 5 minutes
const REPLAY_WINDOW_MS = 10 * 60 * 1000; // event ID dedup: 10 minutes

// --- Replay cache (in-memory; swap for Redis in multi-instance deployments) ---
const seenEvents = new Map(); // eventId -> expiresAt (ms)

function isReplay(eventId) {
  const now = Date.now();

  // Lazy eviction of expired entries
  for (const [id, expiresAt] of seenEvents) {
    if (expiresAt <= now) seenEvents.delete(id);
  }

  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + REPLAY_WINDOW_MS);
  return false;
}

function verifyWebhookSignature(req, res, next) {
  const currentSecret = process.env.WEBHOOK_SECRET;
  const previousSecret = process.env.WEBHOOK_PREVIOUS_SECRET; // optional during rotation
  if (!currentSecret) {
    return res.status(500).json({ error: "Server misconfigured" });
  }

  const rawBody = req.rawBody;
  if (!rawBody || !Buffer.isBuffer(rawBody)) {
    return res.status(400).json({ error: "Missing raw body" });
  }

  // Header: X-Signature: <timestamp>.<hex hmac>
  const header = req.get("x-signature") || "";
  const match = header.match(/^(\d{10})\.([a-f0-9]{64})$/i);
  if (!match) {
    return res.status(400).json({ error: "Malformed signature header" });
  }
  const [, timestamp, providedHex] = match;

  // --- Freshness: reject timestamps older than 5 minutes (and future skew) ---
  const age = Math.floor(Date.now() / 1000) - parseInt(timestamp, 10);
  if (age > MAX_AGE_SECONDS || age < -MAX_AGE_SECONDS) {
    return res.status(401).json({ error: "Timestamp outside allowed window" });
  }

  // --- Recompute HMAC over timestamp + "." + raw body, for BOTH secrets ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + ".", "ascii"),
    rawBody,
  ]);
  const provided = Buffer.from(providedHex, "hex");

  const candidates = [currentSecret];
  if (previousSecret) candidates.push(previousSecret);

  // Compute every digest first, then compare — so timing doesn't reveal
  // which secret matched (and we never short-circuit on the first).
  const digests = candidates.map((s) =>
    crypto.createHmac("sha256", s).update(signedPayload).digest()
  );

  const valid = digests.some((d) => crypto.timingSafeEqual(d, provided));
  if (!valid) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  // --- Replay check: reject repeated event IDs within 10 minutes ---
  // Event ID comes from a header (never trust the body before verification,
  // and the header is now authenticated by the signature above).
  const eventId = req.get("x-event-id") || "";
  if (!eventId || eventId.length > 128) {
    return res.status(400).json({ error: "Missing or invalid event ID" });
  }
  if (isReplay(eventId)) {
    return res.status(409).json({ error: "Duplicate event" });
  }

  next();
}

module.exports = verifyWebhookSignature;
```

## Python (FastAPI)

```python
import hashlib
import hmac
import os
import re
import time
import threading

from fastapi import FastAPI, Request, HTTPException

app = FastAPI()

MAX_AGE_SECONDS = 300
REPLAY_WINDOW_SECONDS = 600  # 10 minutes

CURRENT_SECRET = os.environ["WEBHOOK_SECRET"].encode()
PREVIOUS_SECRET = (
    os.environ["WEBHOOK_PREVIOUS_SECRET"].encode()
    if os.environ.get("WEBHOOK_PREVIOUS_SECRET")
    else None
)

HEADER_RE = re.compile(r"^(\d{10})\.([a-f0-9]{64})$", re.IGNORECASE)

# --- Replay cache (in-memory; use Redis for multi-instance) ---
_seen: dict[str, float] = {}
_lock = threading.Lock()

def is_replay(event_id: str) -> bool:
    now = time.time()
    with _lock:
        # Evict expired entries
        expired = [k for k, exp in _seen.items() if exp <= now]
        for k in expired:
            del _seen[k]
        if event_id in _seen:
            return True
        _seen[event_id] = now + REPLAY_WINDOW_SECONDS
        return False

@app.post("/webhook")
async def webhook(request: Request):
    raw_body = await request.body()
    header = request.headers.get("x-signature", "")

    m = HEADER_RE.match(header)
    if not m:
        raise HTTPException(status_code=400, detail="Malformed signature header")
    timestamp, provided_hex = m.groups()

    # Freshness
    age = int(time.time()) - int(timestamp)
    if age > MAX_AGE_SECONDS or age < -MAX_AGE_SECONDS:
        raise HTTPException(status_code=401, detail="Timestamp outside allowed window")

    # HMAC over timestamp + "." + raw body, against both secrets
    signed_payload = f"{timestamp}.".encode() + raw_body
    provided = bytes.fromhex(provided_hex)

    secrets = [CURRENT_SECRET] + ([PREVIOUS_SECRET] if PREVIOUS_SECRET else [])
    digests = [hmac.new(s, signed_payload, hashlib.sha256).digest() for s in secrets]

    # compare_digest is constant-time per comparison; evaluate all candidates
    valid = any(hmac.compare_digest(d, provided) for d in digests)
    if not valid:
        raise HTTPException(status_code=401, detail="Invalid signature")

    # Replay check — header is now authenticated
    event_id = request.headers.get("x-event-id", "")
    if not event_id or len(event_id) > 128:
        raise HTTPException(status_code=400, detail="Missing or invalid event ID")
    if is_replay(event_id):
        raise HTTPException(status_code=409, detail="Duplicate event")

    return {"status": "accepted"}
```

## Security notes on the new requirements

1. **Rotation overlap, not fallback-by-order** — both secrets are treated as equally valid during the overlap window. Never reveal which one matched (no different error messages, no logging of "matched previous secret"), and don't short-circuit comparisons in a way that leaks which candidate succeeded via timing.
2. **Compute all digests, then compare** — in the Node version digests are computed up front so the number of HMAC operations doesn't depend on which secret matched. (Minor: `some()` still short-circuits the *comparisons*; if you want fully uniform timing, replace with `digests.map(...).includes(true)` — usually overkill, but noted for completeness.)
3. **Replay check runs *after* signature verification** — critical ordering. If you deduped on event ID before authenticating, an attacker could poison the cache with a forged event ID, causing you to reject the *legitimate* delivery (a denial-of-service on real events). Verify first, dedup second.
4. **Event ID from a header, not the body** — the body isn't authenticated until the HMAC check passes, and parsing it before verification invites parser-based attacks. The header is covered by the signature check that just ran. If your provider only puts the ID in the body, parse it *after* verification and before `next()`.
5. **Replay window (10 min) > freshness window (5 min)** — this is the correct relationship: a captured request is timestamp-valid for at most ~5 minutes, and the dedup window outlives it, so a replayed event can never slip back in as "fresh." If you ever widen the freshness window, widen the replay window to match or exceed it.
6. **Cache eviction** — entries are lazily evicted on access; for high-volume endpoints, add periodic sweeping so the map doesn't grow unbounded between requests.
7. **Multi-instance deployments** — the in-memory `Map`/`dict` only dedups per process. Behind a load balancer, a replay can hit a different instance. Use Redis (or equivalent) with `SET key value NX EX 600` as the atomic check-and-set.
8. **Rotation hygiene** — once the overlap period ends (all in-flight events signed with the old secret have expired: freshness window + delivery retries), unset `WEBHOOK_PREVIOUS_SECRET` so the attack surface stays at one secret.

Want the Redis-backed version of the replay cache, or a note on how to sequence the rotation (deploy new secret as "previous" → flip → retire old)?

# Final: Webhook Signature Verification Middleware (TypeScript pseudocode)

Consolidates all accumulated requirements:

- HMAC-SHA256 over `timestamp + "." + rawBody`
- Raw body bytes, never the parsed body
- Reject timestamps older than 5 minutes (future skew also rejected) → **401**
- Accept either current or previous secret (rotation overlap)
- Constant-time digest comparison across both candidates
- Reject repeated event IDs within 10 minutes → **409**
- Bad signature → **401**; malformed input / missing data → **400**

```ts
// ---- Configuration ----
const MAX_AGE_SECONDS = 300;        // timestamp freshness window: 5 min
const REPLAY_WINDOW_MS = 600_000;   // event ID dedup window: 10 min
const SIGNATURE_HEADER = "x-signature";
const EVENT_ID_HEADER  = "x-event-id";

// Secrets from env/config — never hardcoded, never logged
const currentSecret:  string | undefined = env.WEBHOOK_SECRET;
const previousSecret: string | undefined = env.WEBHOOK_PREVIOUS_SECRET; // optional

// ---- Replay cache ----
// In-memory for single instance; use Redis SET NX EX 600 for multi-instance.
const seenEvents: Map<string, number> = new Map(); // eventId -> expiresAtMs

function isReplay(eventId: string): boolean {
  const now = Date.now();

  // Lazy eviction of expired entries
  for (const [id, expiresAt] of seenEvents) {
    if (expiresAt <= now) seenEvents.delete(id);
  }

  if (seenEvents.has(eventId)) return true;   // duplicate within window
  seenEvents.set(eventId, now + REPLAY_WINDOW_MS);
  return false;
}

// ---- Middleware ----
async function verifyWebhookSignature(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {

  // 0. Server configuration — fail closed
  if (!currentSecret) {
    return res.status(500).json({ error: "Server misconfigured" });
  }

  // 1. Raw body — must be the exact bytes captured before JSON parsing
  const rawBody: Buffer | undefined = req.rawBody;
  if (!rawBody || !Buffer.isBuffer(rawBody)) {
    return res.status(400).json({ error: "Missing raw body" });
  }

  // 2. Parse and strictly validate the signature header:
  //    "<10-digit unix timestamp>.<64-char lowercase hex hmac>"
  const header: string = req.get(SIGNATURE_HEADER) ?? "";
  const match = header.match(/^(\d{10})\.([a-f0-9]{64})$/i);
  if (!match) {
    return res.status(400).json({ error: "Malformed signature header" });
  }
  const [timestamp, providedHex] = match.slice(1);

  // 3. Freshness: reject stale (>5 min old) or far-future timestamps -> 401
  const ageSeconds = Math.floor(Date.now() / 1000) - parseInt(timestamp, 10);
  if (ageSeconds > MAX_AGE_SECONDS || ageSeconds < -MAX_AGE_SECONDS) {
    return res.status(401).json({ error: "Timestamp outside allowed window" });
  }

  // 4. Recompute HMAC over timestamp + "." + rawBody for BOTH secrets.
  //    Reuse the timestamp string verbatim — never reformat before hashing.
  const signedPayload: Buffer = Buffer.concat([
    Buffer.from(timestamp + ".", "ascii"),
    rawBody,
  ]);
  const provided: Buffer = Buffer.from(providedHex, "hex");

  const candidates: string[] = [currentSecret];
  if (previousSecret) candidates.push(previousSecret);

  // Compute all digests up front; do not short-circuit in a way that
  // reveals which secret matched.
  const digests: Buffer[] = candidates.map((secret) =>
    createHmac("sha256", secret).update(signedPayload).digest()
  );

  // 5. Constant-time comparison against each candidate
  const valid: boolean = digests.some((d) => timingSafeEqual(d, provided));
  if (!valid) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  // 6. Replay check — AFTER authentication, so an attacker can't poison
  //    the cache with forged event IDs. Header is now trusted.
  const eventId: string = req.get(EVENT_ID_HEADER) ?? "";
  if (!eventId || eventId.length > 128) {
    return res.status(400).json({ error: "Missing or invalid event ID" });
  }
  if (isReplay(eventId)) {
    return res.status(409).json({ error: "Duplicate event" });
  }

  next(); // req.body is now safe for handlers to use
}
```

## Raw-body capture (must run before the middleware)

```ts
app.use(
  json({
    verify: (req: Request, res: Response, buf: Buffer) => {
      req.rawBody = buf; // preserve exact bytes for HMAC
    },
  })
);

app.post("/webhook", verifyWebhookSignature, (req, res) => {
  res.status(202).end();
});
```

## Status code summary

| Condition | Status |
|---|---|
| Missing/malformed signature header, missing raw body, missing event ID | 400 |
| Stale or far-future timestamp | **401** |
| Bad signature (neither secret matches) | **401** |
| Repeated event ID within 10 minutes | **409** |
| Valid, fresh, non-replayed event | pass to handler |

## Invariants preserved (checklist)

- ✅ HMAC over **raw** body bytes, never re-serialized JSON
- ✅ Signed payload is exactly `timestamp + "." + rawBody`, timestamp reused verbatim
- ✅ 5-minute freshness window, future skew rejected
- ✅ Dual-secret rotation overlap; both digests computed before comparison; no signal about which secret matched
- ✅ `timingSafeEqual` / constant-time comparison throughout
- ✅ Replay dedup strictly **after** signature verification (cache-poisoning defense)
- ✅ Replay window (10 min) ≥ freshness window (5 min), so a replayed event can never re-enter as "fresh"
- ✅ Fail closed on missing secret, missing raw body, malformed header
- ✅ Secrets from environment only; never logged
- ⚠️ Production multi-instance: replace the in-memory `Map` with Redis `SET eventId 1 NX EX 600`
- ⚠️ Rotation hygiene: retire `WEBHOOK_PREVIOUS_SECRET` once freshness window + retry horizon has elapsed

# HMAC-SHA256 Webhook Signature Verification Middleware

Key points: you must hash the **raw, unparsed body** (JSON parsing/re-serialization changes bytes and breaks the signature), and compare digests with a **constant-time** comparison.

## Express example

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // never hardcode

// Capture the raw body BEFORE any JSON parsing
app.use('/webhooks', express.raw({ type: '*/*' }));

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // e.g. "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp');

  if (!signature || !timestamp) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Replay protection: reject stale timestamps (5 min window)
  const age = Math.abs(Date.now() - Number(timestamp) * 1000);
  if (!Number.isFinite(age) || age > 5 * 60 * 1000) {
    return res.status(401).json({ error: 'Stale or invalid timestamp' });
  }

  // Sign timestamp + body so the timestamp is covered by the HMAC
  const payload = `${timestamp}.${req.body.toString('utf8')}`;
  const expected = 'sha256=' + crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(payload, 'utf8')
    .digest('hex');

  // Constant-time comparison to prevent timing attacks
  const a = Buffer.from(signature);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Parse the body only after verification succeeds
  req.body = JSON.parse(req.body.toString('utf8'));
  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  // req.body is now verified and parsed
  console.log('Verified event:', req.body);
  res.sendStatus(200);
});
```

## Security checklist

- **Raw body only** — `express.raw()` must run before `express.json()` on this route; never hash a re-serialized object.
- **`crypto.timingSafeEqual`** — never use `===` on signatures; check lengths first (it throws on mismatch).
- **Secret from env/secret manager**, rotated periodically, never in source control.
- **Timestamp in the signed payload** — prevents replay of captured requests.
- **Fail closed** — any missing header, parse error, or mismatch → 401, no processing.
- **HTTPS only** — HMAC proves integrity/authenticity, not confidentiality.
- Optionally **log failures** (without logging the secret or full signature) for monitoring.

Adapt the header names and payload format (`timestamp.body` vs. body-only) to whatever your webhook provider documents — Stripe, GitHub, and Shopify each differ slightly.

Those requirements are already baked into the sketch — here's the middleware tightened to match that exact spec:

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const MAX_TIMESTAMP_AGE_MS = 5 * 60 * 1000; // 5 minutes

// Raw body must be captured before any JSON parsing
app.use('/webhooks', express.raw({ type: '*/*' }));

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp'); // unix seconds

  if (!signature || !timestamp) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Reject timestamps older than five minutes (and future-dated ones)
  const timestampMs = Number(timestamp) * 1000;
  if (!Number.isFinite(timestampMs)) {
    return res.status(401).json({ error: 'Invalid timestamp' });
  }
  const age = Date.now() - timestampMs;
  if (age < 0 || age > MAX_TIMESTAMP_AGE_MS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // Signed payload: timestamp + '.' + raw body
  const signedPayload = timestamp + '.' + req.body.toString('utf8');
  const expected =
    'sha256=' +
    crypto.createHmac('sha256', WEBHOOK_SECRET).update(signedPayload, 'utf8').digest('hex');

  // Constant-time comparison (lengths must match or timingSafeEqual throws)
  const receivedBuf = Buffer.from(signature, 'utf8');
  const expectedBuf = Buffer.from(expected, 'utf8');
  if (
    receivedBuf.length !== expectedBuf.length ||
    !crypto.timingSafeEqual(receivedBuf, expectedBuf)
  ) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Parse only after successful verification
  try {
    req.body = JSON.parse(req.body.toString('utf8'));
  } catch {
    return res.status(400).json({ error: 'Malformed body' });
  }
  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  res.sendStatus(200);
});
```

Spec conformance notes:

- **Payload format**: `timestamp + '.' + raw_body` — the raw buffer is stringified as UTF-8 and concatenated with the exact timestamp header value (not a reformatted date), so the digest matches what the sender computed.
- **Five-minute window**: `age > MAX_TIMESTAMP_AGE_MS` rejects old timestamps; `age < 0` also rejects future timestamps, which would otherwise be replayable indefinitely within the window.
- **Constant-time comparison**: `crypto.timingSafeEqual` on equal-length buffers only; the length check happens first since it throws on mismatched lengths. Length itself is not secret-dependent here (hex SHA-256 digests are fixed-size), so the early length check leaks nothing useful.
- **Fail closed**: every failure path returns before any body parsing or handler logic runs.

Updated middleware with secret rotation support and replay deduplication:

```js
const crypto = require('crypto');
const express = require('express');

const app = express();

// Rotation: try current first, fall back to previous during the overlap window
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS, // remove after rotation grace period ends
].filter(Boolean);

const MAX_TIMESTAMP_AGE_MS = 5 * 60 * 1000;
const EVENT_ID_TTL_MS = 10 * 60 * 1000;

// Raw body must be captured before any JSON parsing
app.use('/webhooks', express.raw({ type: '*/*' }));

// --- Event ID replay cache (10-minute TTL) ---
// In-memory for a single instance; use Redis SET NX PX 600000 for multi-instance.
const seenEventIds = new Map(); // eventId -> expiry timestamp

function isDuplicateEventId(eventId) {
  const now = Date.now();

  // Opportunistic sweep of expired entries
  for (const [id, expiry] of seenEventIds) {
    if (expiry <= now) seenEventIds.delete(id);
  }

  if (seenEventIds.has(eventId)) return true;
  seenEventIds.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

function signatureMatches(signature, signedPayload) {
  const receivedBuf = Buffer.from(signature, 'utf8');

  for (const secret of WEBHOOK_SECRETS) {
    const expected =
      'sha256=' +
      crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');
    const expectedBuf = Buffer.from(expected, 'utf8');

    // Constant-time comparison (lengths must match or timingSafeEqual throws)
    if (
      receivedBuf.length === expectedBuf.length &&
      crypto.timingSafeEqual(receivedBuf, expectedBuf)
    ) {
      return true;
    }
  }
  return false;
}

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp'); // unix seconds
  const eventId = req.get('X-Webhook-Event-Id');

  if (!signature || !timestamp || !eventId) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Reject timestamps older than five minutes (and future-dated ones)
  const timestampMs = Number(timestamp) * 1000;
  if (!Number.isFinite(timestampMs)) {
    return res.status(401).json({ error: 'Invalid timestamp' });
  }
  const age = Date.now() - timestampMs;
  if (age < 0 || age > MAX_TIMESTAMP_AGE_MS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // Signed payload: timestamp + '.' + raw body
  const signedPayload = timestamp + '.' + req.body.toString('utf8');
  if (!signatureMatches(signature, signedPayload)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Reject repeated event IDs for ten minutes (after signature check,
  // so attackers can't poison the dedup cache with unauthenticated IDs)
  if (isDuplicateEventId(eventId)) {
    return res.status(409).json({ error: 'Duplicate event' });
  }

  // Parse only after successful verification
  try {
    req.body = JSON.parse(req.body.toString('utf8'));
  } catch {
    return res.status(400).json({ error: 'Malformed body' });
  }
  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  res.sendStatus(200);
});
```

Key design decisions:

- **Secret rotation**: both secrets are tried against the same signed payload; either match passes. Deploy the new secret as `CURRENT` while keeping the old one as `PREVIOUS` for the provider's cutover window, then drop `PREVIOUS`. Both comparisons use `timingSafeEqual` — no early-exit timing signal about which secret matched.
- **Dedup ordering matters**: the event ID check runs **after** signature verification. Otherwise an attacker could submit a victim's event ID with a garbage signature and cause the legitimate delivery to be rejected as a duplicate.
- **10-minute TTL**: entries expire after `EVENT_ID_TTL_MS`. The in-memory `Map` works for a single instance; for horizontally scaled deployments, swap `isDuplicateEventId` for an atomic Redis op:
  ```
  SET webhook:event:<id> 1 NX PX 600000
  ```
  A `nil` result means duplicate. Atomicity is essential — a check-then-set race lets concurrent duplicates through.
- **409 for duplicates**: distinguishes replays from auth failures (401) so the sender's retry logic and your alerting can tell them apart. If the provider expects 200 to stop retries, return 200 with a `duplicate: true` body instead.
- **Fail closed preserved**: all prior requirements (raw body, `timestamp + '.' + raw_body`, 5-minute window, constant-time comparison, parse-after-verify) are unchanged.

```typescript
// --- Configuration ---------------------------------------------------------

const WEBHOOK_SECRETS: string[] = [
  env("WEBHOOK_SECRET_CURRENT"),
  env("WEBHOOK_SECRET_PREVIOUS"), // present only during rotation grace period
].filter(Boolean);

const MAX_TIMESTAMP_AGE_MS = 5 * 60 * 1000;   // 5 minutes
const EVENT_ID_TTL_MS      = 10 * 60 * 1000;  // 10 minutes

// --- Replay cache (single instance) ----------------------------------------
// Multi-instance: replace with Redis `SET key 1 NX PX 600000` (atomic).

const seenEventIds: Map<string, number> = new Map(); // eventId -> expiryMs

function isDuplicateEventId(eventId: string): boolean {
  const now = Date.now();
  for (const [id, expiry] of seenEventIds) {
    if (expiry <= now) seenEventIds.delete(id); // opportunistic sweep
  }
  if (seenEventIds.has(eventId)) return true;
  seenEventIds.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// --- Signature check (constant-time, either secret) -------------------------

function signatureMatches(signature: string, signedPayload: string): boolean {
  const received = Buffer.from(signature, "utf8");

  for (const secret of WEBHOOK_SECRETS) {
    const expected =
      "sha256=" +
      crypto.createHmac("sha256", secret)
            .update(signedPayload, "utf8")
            .digest("hex");
    const expectedBuf = Buffer.from(expected, "utf8");

    // timingSafeEqual throws on length mismatch; check length first
    if (received.length === expectedBuf.length &&
        crypto.timingSafeEqual(received, expectedBuf)) {
      return true;
    }
  }
  return false;
}

// --- Middleware --------------------------------------------------------------
// Requires raw body: mount `express.raw({ type: "*/*" })` on the webhook
// route BEFORE any JSON body parser.

function verifyWebhook(req: Request, res: Response, next: NextFunction): void {
  const signature = req.header("X-Webhook-Signature"); // "sha256=<hex>"
  const timestamp = req.header("X-Webhook-Timestamp"); // unix seconds
  const eventId   = req.header("X-Webhook-Event-Id");

  if (!signature || !timestamp || !eventId) {
    return res.status(401).json({ error: "Missing signature headers" });
  }

  // Stale or future-dated timestamp -> 401
  const timestampMs = Number(timestamp) * 1000;
  const age = Date.now() - timestampMs;
  if (!Number.isFinite(timestampMs) || age < 0 || age > MAX_TIMESTAMP_AGE_MS) {
    return res.status(401).json({ error: "Stale or invalid timestamp" });
  }

  // Signed payload: timestamp + "." + raw body; bad signature -> 401
  const signedPayload = timestamp + "." + req.body.toString("utf8");
  if (!signatureMatches(signature, signedPayload)) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  // Replay check AFTER auth, so attackers can't poison the dedup cache
  // with unauthenticated event IDs -> 409
  if (isDuplicateEventId(eventId)) {
    return res.status(409).json({ error: "Duplicate event" });
  }

  // Parse only after all verification succeeds
  try {
    req.body = JSON.parse(req.body.toString("utf8"));
  } catch {
    return res.status(400).json({ error: "Malformed body" });
  }

  next();
}

// --- Route -------------------------------------------------------------------

app.post("/webhooks/events", verifyWebhook, (req: Request, res: Response) => {
  // req.body: verified, fresh, non-replayed, parsed
  res.sendStatus(200);
});
```

**Behavior summary:**

| Condition | Status |
|---|---|
| Missing signature / timestamp / event ID header | 401 |
| Timestamp malformed, future-dated, or > 5 min old | 401 |
| HMAC matches neither current nor previous secret | 401 |
| Event ID seen within the last 10 minutes | 409 |
| Body not valid JSON (post-verification) | 400 |
| All checks pass | handler runs |

**Invariants preserved:** raw body hashed (never re-serialized JSON); payload is exactly `timestamp + "." + raw_body`; all signature comparisons via `timingSafeEqual` with a length pre-check; replay cache written only after authentication; fail closed on every error path.

