  const a = Buffer.from(signature);
  const b = Buffer.from(expected);

  // Constant-time comparison (lengths must match or timingSafeEqual throws)
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  const event = JSON.parse(req.body.toString('utf8'));
  // ... handle event (make handling idempotent!)
  res.sendStatus(200);
});
```

## Common pitfalls

1. **Don't use `express.json()` before verification** — parsing and re-stringifying changes whitespace/key order, breaking the HMAC. Use `express.raw()` (or a `verify` callback that stashes `req.rawBody`).
2. **Never use `===` to compare signatures** — it's vulnerable to timing attacks. Use `crypto.timingSafeEqual`.
3. **Include a timestamp in the signed payload** and enforce a freshness window to prevent replay attacks.
4. **Read the secret from env/secret manager**, never hardcode it.
5. **Make the handler idempotent** — providers retry deliveries; dedupe on the event ID.

## Python/Flask variant (same principles)

```python
import hmac, hashlib, time
from flask import Flask, request, abort

app = Flask(__name__)
SECRET = b"..."  # from env

@app.before_request
def verify_signature():
    if request.path != "/webhooks/events":
        return
    sig = request.headers.get("X-Webhook-Signature", "")
    ts = request.headers.get("X-Webhook-Timestamp", "")
    if not sig or not ts or abs(time.time() - int(ts)) > 300:
        abort(401)
    payload = ts.encode() + b"." + request.get_data()  # raw bytes
    expected = "sha256=" + hmac.new(SECRET, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        abort(401)
```

Adjust the header names and payload format (`timestamp.body` vs. body only) to match your provider's spec (Stripe, GitHub, Shopify, etc. each differ slightly).

Here's the middleware implementing exactly that spec: signed payload = `timestamp + '.' + raw_body`, 5-minute freshness window, constant-time comparison.

## Express (Node.js)

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const MAX_TIMESTAMP_AGE_MS = 5 * 60 * 1000; // 5 minutes

// Raw body required — must run BEFORE any JSON parsing middleware
app.use('/webhooks', express.raw({ type: '*/*' }));

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // format: "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp'); // unix seconds

  if (!signature || !timestamp) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Freshness: reject timestamps older than 5 minutes (or in the future)
  const tsMs = Number(timestamp) * 1000;
  if (!Number.isFinite(tsMs) || Math.abs(Date.now() - tsMs) > MAX_TIMESTAMP_AGE_MS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // Signed payload: timestamp + '.' + raw body
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + '.', 'utf8'),
    req.body, // raw bytes from express.raw()
  ]);

  const expected =
    'sha256=' + crypto.createHmac('sha256', WEBHOOK_SECRET).update(signedPayload).digest('hex');

  const receivedBuf = Buffer.from(signature, 'utf8');
  const expectedBuf = Buffer.from(expected, 'utf8');

  // Constant-time comparison; length check first since timingSafeEqual throws on mismatch
  if (receivedBuf.length !== expectedBuf.length ||
      !crypto.timingSafeEqual(receivedBuf, expectedBuf)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  const event = JSON.parse(req.body.toString('utf8'));
  // ... handle event idempotently
  res.sendStatus(200);
});
```

## Flask (Python)

```python
import hmac, hashlib, os, time
from flask import Flask, request, abort

app = Flask(__name__)
SECRET = os.environ["WEBHOOK_SECRET"].encode()
MAX_AGE_SECONDS = 300  # 5 minutes

@app.before_request
def verify_webhook_signature():
    if request.path != "/webhooks/events":
        return

    signature = request.headers.get("X-Webhook-Signature", "")
    timestamp = request.headers.get("X-Webhook-Timestamp", "")
    if not signature or not timestamp:
        abort(401)

    # Freshness: reject timestamps older than 5 minutes
    try:
        age = abs(time.time() - int(timestamp))
    except ValueError:
        abort(401)
    if age > MAX_AGE_SECONDS:
        abort(401)

    # Signed payload: timestamp + '.' + raw body
    raw_body = request.get_data()  # raw bytes, unparsed
    signed_payload = timestamp.encode() + b"." + raw_body
    expected = "sha256=" + hmac.new(SECRET, signed_payload, hashlib.sha256).hexdigest()

    # Constant-time comparison
    if not hmac.compare_digest(signature, expected):
        abort(401)
```

## Notes

- **Raw body is non-negotiable**: any JSON parse/re-serialize before verification will break the HMAC. In Express, `express.raw()` must be registered before `express.json()` for the webhook route; in Flask, use `request.get_data()` rather than `request.json`.
- **The timestamp is inside the HMAC**, so an attacker can't strip or alter it — the freshness check is trustworthy.
- **`Math.abs` on the age** also rejects far-future timestamps, which would otherwise bypass replay protection.
- **Length check before `timingSafeEqual`** is required in Node since it throws on unequal-length buffers; `hmac.compare_digest` in Python handles this safely on its own.
- Keep the handler **idempotent** (dedupe on event ID) since providers retry deliveries.

Updated middleware with **secret rotation support** (accept current or previous secret) and **event ID deduplication** (10-minute window).

## Express (Node.js)

```js
const crypto = require('crypto');
const express = require('express');

const app = express();

// Rotation: index 0 = current, index 1 = previous. Both accepted during rotation window.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

const MAX_TIMESTAMP_AGE_MS = 5 * 60 * 1000;   // timestamp freshness
const EVENT_ID_TTL_MS = 10 * 60 * 1000;       // dedupe window

// --- Event ID replay cache (swap for Redis in multi-instance deployments) ---
const seenEvents = new Map(); // eventId -> expiry timestamp

function isDuplicateEvent(eventId) {
  const now = Date.now();

  // Opportunistic cleanup of expired entries
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }

  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// Raw body required — must run BEFORE any JSON parsing middleware
app.use('/webhooks', express.raw({ type: '*/*' }));

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp'); // unix seconds
  const eventId = req.get('X-Webhook-Event-Id');

  if (!signature || !timestamp || !eventId) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Freshness: reject timestamps older than 5 minutes (or far-future)
  const tsMs = Number(timestamp) * 1000;
  if (!Number.isFinite(tsMs) || Math.abs(Date.now() - tsMs) > MAX_TIMESTAMP_AGE_MS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // Signed payload: timestamp + '.' + raw body
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + '.', 'utf8'),
    req.body,
  ]);

  const receivedBuf = Buffer.from(signature, 'utf8');

  // Accept a signature from EITHER the current or previous secret.
  // Every candidate is checked with a constant-time comparison.
  const verified = WEBHOOK_SECRETS.some((secret) => {
    const expected =
      'sha256=' + crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');
    const expectedBuf = Buffer.from(expected, 'utf8');
    return receivedBuf.length === expectedBuf.length &&
           crypto.timingSafeEqual(receivedBuf, expectedBuf);
  });

  if (!verified) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Replay protection: reject event IDs seen within the last 10 minutes.
  // Done AFTER signature verification so attackers can't poison the cache
  // with unauthenticated event IDs.
  if (isDuplicateEvent(eventId)) {
    return res.status(409).json({ error: 'Duplicate event' });
  }

  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  const event = JSON.parse(req.body.toString('utf8'));
  // ... handle event
  res.sendStatus(200);
});
```

## Flask (Python)

```python
import hmac, hashlib, os, time
from flask import Flask, request, abort, jsonify

app = Flask(__name__)

# Rotation: current first, previous second. Both accepted.
SECRETS = [s.encode() for s in (
    os.environ.get("WEBHOOK_SECRET_CURRENT"),
    os.environ.get("WEBHOOK_SECRET_PREVIOUS"),
) if s]

MAX_AGE_SECONDS = 300        # timestamp freshness: 5 minutes
EVENT_ID_TTL = 600           # dedupe window: 10 minutes

# Swap for Redis (SET event_id 1 NX EX 600) in multi-instance deployments
_seen_events: dict[str, float] = {}

def is_duplicate_event(event_id: str) -> bool:
    now = time.time()
    expired = [k for k, exp in _seen_events.items() if exp <= now]
    for k in expired:
        del _seen_events[k]
    if event_id in _seen_events:
        return True
    _seen_events[event_id] = now + EVENT_ID_TTL
    return False

@app.before_request
def verify_webhook_signature():
    if request.path != "/webhooks/events":
        return

    signature = request.headers.get("X-Webhook-Signature", "")
    timestamp = request.headers.get("X-Webhook-Timestamp", "")
    event_id = request.headers.get("X-Webhook-Event-Id", "")
    if not signature or not timestamp or not event_id:
        abort(401)

    # Freshness: reject timestamps older than 5 minutes
    try:
        age = abs(time.time() - int(timestamp))
    except ValueError:
        abort(401)
    if age > MAX_AGE_SECONDS:
        abort(401)

    # Signed payload: timestamp + '.' + raw body
    signed_payload = timestamp.encode() + b"." + request.get_data()

    # Accept EITHER current or previous secret; constant-time compare each
    verified = any(
        hmac.compare_digest(
            signature,
            "sha256=" + hmac.new(secret, signed_payload, hashlib.sha256).hexdigest(),
        )
        for secret in SECRETS
    )
    if not verified:
        abort(401)

    # Replay protection AFTER auth, so unauthenticated requests can't
    # poison the dedupe cache
    if is_duplicate_event(event_id):
        return jsonify({"error": "Duplicate event"}), 409
```

## Key design decisions

1. **Dedupe runs after signature verification.** If it ran first, an attacker could submit a victim's event ID with a garbage signature and cause the legitimate delivery to be rejected as a duplicate.
2. **Every secret candidate uses constant-time comparison** — no early-exit on length mismatch alone in a way that leaks which secret matched; the `any`/`some` loop only short-circuits on a *successful* match.
3. **In-memory `Map`/dict is fine for a single instance**, but for horizontally scaled deployments use Redis with an atomic set-if-absent + TTL:
   ```
   SET webhook:event:<id> 1 NX EX 600
   ```
   A `nil` reply means duplicate. This also survives restarts.
4. **Rotation procedure**: set `CURRENT` to the new secret and `PREVIOUS` to the old one, deploy, update the secret at the provider, then remove `PREVIOUS` after the provider's retry window has passed.
5. **409 for duplicates** (rather than 401) so legitimate retries get a semantically correct response; some providers treat 2xx as "stop retrying," so alternatively return `200` with `{ "status": "duplicate" }` if you want retries suppressed — check your provider's retry semantics.

```typescript
// ─── Configuration ──────────────────────────────────────────────────────────

const MAX_TIMESTAMP_AGE_MS = 5 * 60 * 1000;  // freshness window: 5 minutes
const EVENT_ID_TTL_MS      = 10 * 60 * 1000; // replay dedupe window: 10 minutes

// Rotation: both accepted; index 0 = current, index 1 = previous
const WEBHOOK_SECRETS: string[] = [
  env("WEBHOOK_SECRET_CURRENT"),
  env("WEBHOOK_SECRET_PREVIOUS"),
].filter(Boolean);

// ─── Replay cache (use Redis SET NX EX 600 for multi-instance) ──────────────

const seenEvents: Map<string, number> = new Map(); // eventId -> expiryMs

function isDuplicateEvent(eventId: string): boolean {
  const now = Date.now();
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id); // opportunistic cleanup
  }
  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ─── Middleware ─────────────────────────────────────────────────────────────
// Requires raw body: mount express.raw({ type: '*/*' }) BEFORE express.json()

function verifyWebhookSignature(req: Request, res: Response, next: NextFunction): void {
  const signature = req.header("X-Webhook-Signature"); // "sha256=<hex>"
  const timestamp = req.header("X-Webhook-Timestamp"); // unix seconds
  const eventId   = req.header("X-Webhook-Event-Id");

  if (!signature || !timestamp || !eventId) {
    return res.status(401).json({ error: "Missing signature headers" });
  }

  // ── Freshness: reject stale or far-future timestamps ──
  const tsMs = Number(timestamp) * 1000;
  if (!Number.isFinite(tsMs) || Math.abs(Date.now() - tsMs) > MAX_TIMESTAMP_AGE_MS) {
    return res.status(401).json({ error: "Stale timestamp" });
  }

  // ── Signed payload: timestamp + '.' + raw body ──
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + ".", "utf8"),
    req.rawBody, // raw bytes — never re-serialized JSON
  ]);

  // ── Verify against current OR previous secret, constant-time ──
  const receivedBuf = Buffer.from(signature, "utf8");
  const verified = WEBHOOK_SECRETS.some((secret) => {
    const expected = "sha256=" + hmacSha256Hex(secret, signedPayload);
    const expectedBuf = Buffer.from(expected, "utf8");
    return receivedBuf.length === expectedBuf.length
        && crypto.timingSafeEqual(receivedBuf, expectedBuf);
  });

  if (!verified) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  // ── Replay check AFTER auth, so unauthenticated requests
  //    can't poison the dedupe cache ──
  if (isDuplicateEvent(eventId)) {
    return res.status(409).json({ error: "Duplicate event" });
  }

  next();
}

// ─── Route ──────────────────────────────────────────────────────────────────

app.post("/webhooks/events", verifyWebhookSignature, (req, res) => {
  const event = JSON.parse(req.rawBody.toString("utf8"));
  handleEvent(event); // still handle idempotently at the business layer
  res.sendStatus(200);
});
```

**Behavior summary:**

| Condition | Status |
|---|---|
| Missing headers | 401 |
| Timestamp stale (>5 min) or malformed | 401 |
| Signature matches neither current nor previous secret | 401 |
| Valid signature, but event ID seen within 10 min | 409 |
| Valid signature, fresh timestamp, new event ID | → handler |

**Invariants preserved:** raw-body HMAC over `timestamp + '.' + body`; constant-time comparison for every secret candidate; replay cache written only after authentication succeeds.

# Webhook HMAC-SHA256 Verification Middleware

Key requirements: use the **raw** body (not parsed JSON), compare with a **timing-safe** function, and read the secret from config — never hardcode it.

## Express.js example

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // from env, never hardcoded

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // e.g. "sha256=<hex>"
  if (!signature || !signature.startsWith('sha256=')) {
    return res.status(401).json({ error: 'Missing or malformed signature' });
  }

  // req.body must be the RAW body (Buffer), not parsed JSON
  if (!Buffer.isBuffer(req.body)) {
    return res.status(500).json({ error: 'Raw body unavailable' });
  }

  const expected = 'sha256=' + crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(req.body)
    .digest('hex');

  const a = Buffer.from(signature);
  const b = Buffer.from(expected);

  // Length check first: timingSafeEqual throws on length mismatch
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

// Capture raw body ONLY for the webhook route
app.post(
  '/webhooks/payments',
  express.raw({ type: 'application/json' }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString('utf8'));
    // ... handle event
    res.sendStatus(200);
  }
);
```

## Why these details matter

1. **Raw body**: HMAC is computed over exact bytes. `express.json()` re-serializes JSON, and key ordering/whitespace changes will break signature matching. `express.raw()` preserves the original bytes.
2. **`crypto.timingSafeEqual`**: `===` on strings leaks timing information that can enable signature forgery via timing attacks.
3. **Scope the raw parser**: apply `express.raw()` only to webhook routes so the rest of your API can still use `express.json()`.
4. **Constant-time failure**: return the same 401 for missing vs. invalid signatures to avoid oracle behavior.

## Optional hardening: replay protection

If the provider sends a timestamp header, also reject stale requests:

```js
const ts = Number(req.get('X-Webhook-Timestamp'));
if (!ts || Math.abs(Date.now() / 1000 - ts) > 300) {
  return res.status(401).json({ error: 'Stale timestamp' });
}
// then HMAC over `${ts}.${rawBody}` per the provider's scheme
```

This prevents an attacker who captured a valid signed payload from replaying it later.

# Webhook Verification with Timestamp-Signed Payload

The signature now covers `timestamp + '.' + raw_body`, so the timestamp is authenticated — an attacker can't swap in a fresh timestamp without invalidating the signature.

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // from env, never hardcoded
const MAX_TIMESTAMP_AGE_SECONDS = 300; // 5 minutes

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // e.g. "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp'); // unix seconds

  if (!signature || !signature.startsWith('sha256=') || !timestamp) {
    return res.status(401).json({ error: 'Missing signature or timestamp' });
  }

  // --- Replay protection: reject stale (or far-future) timestamps ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) {
    return res.status(401).json({ error: 'Malformed timestamp' });
  }
  const ageSeconds = Math.abs(Date.now() / 1000 - ts);
  if (ageSeconds > MAX_TIMESTAMP_AGE_SECONDS) {
    return res.status(401).json({ error: 'Timestamp outside tolerance window' });
  }

  // --- Raw body required ---
  if (!Buffer.isBuffer(req.body)) {
    return res.status(500).json({ error: 'Raw body unavailable' });
  }

  // --- Recompute HMAC over "timestamp.raw_body" ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp, 'utf8'),
    Buffer.from('.', 'utf8'),
    req.body,
  ]);

  const expected = 'sha256=' + crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(signedPayload)
    .digest('hex');

  // --- Constant-time comparison ---
  const a = Buffer.from(signature, 'utf8');
  const b = Buffer.from(expected, 'utf8');

  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

app.post(
  '/webhooks/payments',
  express.raw({ type: 'application/json' }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString('utf8'));
    // ... handle event
    res.sendStatus(200);
  }
);
```

## Key points

1. **Signed payload construction**: `Buffer.concat([timestamp, '.', rawBody])` — the timestamp string is used *exactly as received* (not reformatted from the parsed number), since any byte difference breaks the HMAC.
2. **Timestamp validated before HMAC**: cheap rejection of stale requests; the `Math.abs` check also rejects far-future timestamps, which could otherwise be used to pre-stage a replay.
3. **Order of checks**: timestamp freshness is checked first, but the signature is still verified before the request is trusted — the timestamp is only meaningful once it's proven to be part of the signed payload.
4. **Constant-time comparison**: `crypto.timingSafeEqual` on equal-length buffers; the length pre-check avoids its throw-on-mismatch behavior without leaking signature content.
5. **Uniform 401s**: missing, malformed, stale, and invalid signatures all return 401 to avoid oracle behavior.

## Optional: deduplication

The 5-minute window still allows replays *within* the window. For strict once-only delivery, store seen event IDs (or signature hashes) in Redis with a 5-minute TTL and reject duplicates:

```js
// after signature verification
const seen = await redis.set(`wh:${signature}`, 1, 'NX', 'EX', 300);
if (!seen) return res.status(409).json({ error: 'Duplicate delivery' });
```

# Webhook Verification with Secret Rotation + Event Deduplication

```js
const crypto = require('crypto');
const express = require('express');
const Redis = require('ioredis');

const app = express();
const redis = new Redis(process.env.REDIS_URL);

// Ordered: current first, then previous. Both from env, never hardcoded.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

const MAX_TIMESTAMP_AGE_SECONDS = 300;  // 5 minutes
const EVENT_ID_TTL_SECONDS = 600;       // 10 minutes

async function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp'); // unix seconds
  const eventId = req.get('X-Webhook-Event-Id');

  if (!signature || !signature.startsWith('sha256=') || !timestamp || !eventId) {
    return res.status(401).json({ error: 'Missing signature, timestamp, or event ID' });
  }

  // --- Replay protection: timestamp freshness ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) {
    return res.status(401).json({ error: 'Malformed timestamp' });
  }
  if (Math.abs(Date.now() / 1000 - ts) > MAX_TIMESTAMP_AGE_SECONDS) {
    return res.status(401).json({ error: 'Timestamp outside tolerance window' });
  }

  // --- Raw body required ---
  if (!Buffer.isBuffer(req.body)) {
    return res.status(500).json({ error: 'Raw body unavailable' });
  }

  // --- Recompute HMAC over "timestamp.raw_body" with each accepted secret ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp, 'utf8'),
    Buffer.from('.', 'utf8'),
    req.body,
  ]);

  const provided = Buffer.from(signature, 'utf8');

  const matched = WEBHOOK_SECRETS.some((secret) => {
    const expected = Buffer.from(
      'sha256=' + crypto.createHmac('sha256', secret).update(signedPayload).digest('hex'),
      'utf8'
    );
    // Length check first: timingSafeEqual throws on length mismatch
    return provided.length === expected.length && crypto.timingSafeEqual(provided, expected);
  });

  if (!matched) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // --- Deduplication: reject repeated event IDs for 10 minutes ---
  // Only AFTER signature verification, so attackers can't poison the dedup
  // store with unauthenticated event IDs.
  try {
    const inserted = await redis.set(`wh:evt:${eventId}`, 1, 'NX', 'EX', EVENT_ID_TTL_SECONDS);
    if (!inserted) {
      return res.status(409).json({ error: 'Duplicate event' });
    }
  } catch (err) {
    // Fail closed: if we can't check for duplicates, don't process the event
    return res.status(503).json({ error: 'Deduplication store unavailable' });
  }

  next();
}

app.post(
  '/webhooks/payments',
  express.raw({ type: 'application/json' }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString('utf8'));
    // ... handle event
    res.sendStatus(200);
  }
);
```

## Key points

1. **Secret rotation**: both current and previous secrets are tried against the same signed payload. Verification succeeds if *either* matches, so in-flight webhooks signed with the old secret keep working during the rotation window. Remove the previous secret from env once the provider has fully cut over.
2. **Constant-time comparison per candidate**: each candidate secret gets its own `timingSafeEqual` with a length pre-check. The `.some()` loop short-circuits on match — acceptable here since the number of secrets is tiny and fixed, and no per-secret timing signal is exposed to the caller (all failures return the same 401).
3. **Deduplication after authentication**: the event-ID claim is only trusted once the signature proves the request is genuine. Checking dedup first would let an unauthenticated attacker burn legitimate event IDs and cause valid deliveries to be rejected (a denial-of-service vector).
4. **Atomic `SET NX EX`**: the check-and-set is a single atomic Redis operation, so concurrent duplicate deliveries can't both slip through. TTL of 600s means the key expires automatically — no cleanup needed.
5. **Fail closed on Redis errors**: if the dedup store is down, we return 503 rather than processing a possibly-duplicate event. The provider will retry later. (If your provider treats 5xx as fatal, use 200-without-processing instead — but never silently process.)
6. **Event ID namespacing**: the `wh:evt:` prefix prevents collisions with other Redis consumers.

## Rotation runbook

| Phase | `SECRET_CURRENT` | `SECRET_PREVIOUS` |
|---|---|---|
| Steady state | `S1` | — |
| Rotation begins (provider switches to `S2`) | `S2` | `S1` |
| After old-secret deliveries drain (≥ provider retry window) | `S2` | — |

# Final Webhook Verification Middleware (TypeScript)

```typescript
import crypto from 'crypto';
import express, { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

const app = express();
const redis = new Redis(process.env.REDIS_URL!);

// Ordered: current first, then previous. From env only — never hardcoded.
const WEBHOOK_SECRETS: string[] = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter((s): s is string => Boolean(s));

const MAX_TIMESTAMP_AGE_SECONDS = 300; // 5 minutes
const EVENT_ID_TTL_SECONDS = 600;      // 10 minutes

const UNAUTHORIZED = { error: 'Unauthorized' } as const; // uniform 401 body

async function verifyWebhookSignature(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  const signature = req.get('X-Webhook-Signature');   // "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp');   // unix seconds
  const eventId   = req.get('X-Webhook-Event-Id');

  // --- Presence / format checks → 401 ---
  if (!signature?.startsWith('sha256=') || !timestamp || !eventId) {
    res.status(401).json(UNAUTHORIZED);
    return;
  }

  // --- Timestamp freshness → 401 ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) {
    res.status(401).json(UNAUTHORIZED);
    return;
  }
  if (Math.abs(Date.now() / 1000 - ts) > MAX_TIMESTAMP_AGE_SECONDS) {
    res.status(401).json(UNAUTHORIZED); // stale or far-future
    return;
  }

  // --- Raw body required (express.raw mounted on this route) ---
  if (!Buffer.isBuffer(req.body)) {
    res.status(500).json({ error: 'Raw body unavailable' });
    return;
  }

  // --- HMAC over "timestamp.raw_body", accepting current OR previous secret ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp, 'utf8'),
    Buffer.from('.', 'utf8'),
    req.body,
  ]);

  const provided = Buffer.from(signature, 'utf8');

  const signatureValid = WEBHOOK_SECRETS.some((secret) => {
    const expected = Buffer.from(
      'sha256=' + crypto.createHmac('sha256', secret).update(signedPayload).digest('hex'),
      'utf8'
    );
    // Length pre-check: timingSafeEqual throws on length mismatch
    return provided.length === expected.length && crypto.timingSafeEqual(provided, expected);
  });

  if (!signatureValid) {
    res.status(401).json(UNAUTHORIZED); // bad signature
    return;
  }

  // --- Replay deduplication → 409 (only AFTER authentication) ---
  try {
    const inserted = await redis.set(
      `wh:evt:${eventId}`, '1', 'EX', EVENT_ID_TTL_SECONDS, 'NX'
    );
    if (inserted === null) {
      res.status(409).json({ error: 'Duplicate event' }); // replay
      return;
    }
  } catch {
    res.status(503).json({ error: 'Deduplication store unavailable' }); // fail closed
    return;
  }

  next();
}

app.post(
  '/webhooks/payments',
  express.raw({ type: 'application/json' }),
  verifyWebhookSignature,
  (req: Request, res: Response) => {
    const event = JSON.parse((req.body as Buffer).toString('utf8'));
    // ... handle event
    res.sendStatus(200);
  }
);
```

## Security invariants preserved

| Requirement | Implementation |
|---|---|
| Raw body for HMAC | `express.raw()` scoped to the webhook route only |
| Signed payload = `timestamp.raw_body` | `Buffer.concat` using the timestamp string **as received** |
| Stale timestamp → **401** | `Math.abs(now - ts) > 300` rejects old and far-future |
| Bad/missing signature → **401** | Uniform `UNAUTHORIZED` body for all auth failures (no oracle) |
| Constant-time comparison | `crypto.timingSafeEqual` with length pre-check, per candidate secret |
| Secret rotation | Current + previous secrets both accepted; drop previous after cutover |
| Replay → **409** | Atomic `SET NX EX 600` on `wh:evt:{eventId}` |
| Dedup after auth | Prevents unauthenticated event-ID poisoning (DoS) |
| Fail closed | 503 if Redis unavailable — never process unverified duplicates |

# HMAC-SHA256 Webhook Signature Verification Middleware

Key requirements: use the **raw** request body (not parsed JSON), compare with a **timing-safe** function, and reject on any mismatch.

## Express.js example

```js
const crypto = require('crypto');
const express = require('express');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // never hardcode

// Capture the raw body BEFORE any JSON parsing
function rawBodySaver(req, res, buf) {
  if (buf && buf.length) req.rawBody = buf;
}

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // e.g. "sha256=<hex>"
  if (!signature || !req.rawBody) {
    return res.status(401).json({ error: 'Missing signature or body' });
  }

  const expected =
    'sha256=' +
    crypto.createHmac('sha256', WEBHOOK_SECRET)
          .update(req.rawBody)
          .digest('hex');

  // Timing-safe comparison (lengths must match for timingSafeEqual)
  const a = Buffer.from(signature);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

const app = express();

// Mount raw-body capture only on webhook routes
app.post(
  '/webhooks/payments',
  express.json({ verify: rawBodySaver }),
  verifyWebhookSignature,
  (req, res) => {
    // Signature verified — process event
    res.status(200).json({ received: true });
  }
);
```

## Optional: replay protection

```js
const MAX_AGE_MS = 5 * 60 * 1000;

function checkTimestamp(req, res, next) {
  const ts = Number(req.get('X-Webhook-Timestamp'));
  if (!ts || Math.abs(Date.now() - ts) > MAX_AGE_MS) {
    return res.status(401).json({ error: 'Stale or missing timestamp' });
  }
  next();
}
// Then sign `${timestamp}.${rawBody}` on the sender side and verify the same way.
```

## Critical points

- **Raw body only** — re-serializing parsed JSON (`JSON.stringify`) can change key order/whitespace and break the HMAC.
- **`crypto.timingSafeEqual`** — never use `===` for signature comparison (timing attacks).
- **Constant-shape failures** — return the same 401 for missing vs. invalid signatures to avoid leaking info.
- **Secret from env/secret manager**, rotate periodically, and use a dedicated secret per webhook endpoint.
- **Replay protection** — include a timestamp (and ideally a nonce/event ID dedupe) in the signed payload.

# Webhook Verification with Timestamped Signed Payload

Signed payload format: `timestamp + '.' + raw_body`. Rejects stale timestamps (>5 min) and uses constant-time comparison throughout.

```js
const crypto = require('crypto');
const express = require('express');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // never hardcode
const MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes

// Capture the raw body BEFORE any JSON parsing
function rawBodySaver(req, res, buf) {
  if (buf && buf.length) req.rawBody = buf;
}

function verifyWebhookSignature(req, res, next) {
  const reject = () => res.status(401).json({ error: 'Unauthorized' });

  const signature = req.get('X-Webhook-Signature'); // hex HMAC
  const timestamp = req.get('X-Webhook-Timestamp'); // ms since epoch

  if (!signature || !timestamp || !req.rawBody) {
    return reject();
  }

  // --- Replay protection: reject stale or future-skewed timestamps ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts) || Math.abs(Date.now() - ts) > MAX_AGE_MS) {
    return reject();
  }

  // --- Recompute HMAC over timestamp + '.' + raw_body ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp, 'utf8'),
    Buffer.from('.', 'utf8'),
    req.rawBody, // Buffer — exact bytes received
  ]);

  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(signedPayload)
    .digest();

  // --- Constant-time comparison ---
  let provided;
  try {
    provided = Buffer.from(signature, 'hex');
  } catch {
    return reject();
  }

  if (provided.length !== expected.length ||
      !crypto.timingSafeEqual(provided, expected)) {
    return reject();
  }

  next();
}

const app = express();

app.post(
  '/webhooks/payments',
  express.json({ verify: rawBodySaver }),
  verifyWebhookSignature,
  (req, res) => {
    // Signature + freshness verified — process event
    res.status(200).json({ received: true });
  }
);
```

## Notes

- **Signed payload construction** uses `Buffer.concat` so the raw body bytes are never re-encoded — the HMAC input is exactly `timestamp + '.' + raw_body`.
- **Timestamp validation** happens *before* the HMAC check; `Math.abs` also rejects timestamps too far in the future (clock-skew attacks). The timestamp is authenticated by the HMAC, so an attacker cannot forge a fresh one.
- **Constant-time comparison** via `crypto.timingSafeEqual`, with a length check first (it throws on unequal lengths). The provided signature is decoded from hex into raw bytes before comparison.
- **Uniform 401** for every failure mode (missing headers, stale timestamp, bad signature) — no oracle leaking which check failed.
- **Optional hardening:** dedupe event IDs / `(timestamp, signature)` pairs in Redis to block replays *within* the 5-minute window.

# Webhook Verification with Secret Rotation + Replay Dedupe

Accepts **current or previous** secret during rotation windows, and rejects **repeated event IDs for 10 minutes**.

```js
const crypto = require('crypto');
const express = require('express');

// Ordered: index 0 = current, 1 = previous. Previous is removed after rotation completes.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

const MAX_AGE_MS = 5 * 60 * 1000;        // timestamp freshness window
const EVENT_ID_TTL_MS = 10 * 60 * 1000;  // dedupe window

// --- Event ID dedupe store (swap for Redis in multi-instance deployments) ---
// Redis equivalent: SET event:<id> 1 NX PX 600000  → null means replay
const seenEvents = new Map(); // id -> expiry timestamp

function isReplay(eventId) {
  const now = Date.now();
  // Lazy cleanup of expired entries
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// Capture the raw body BEFORE any JSON parsing
function rawBodySaver(req, res, buf) {
  if (buf && buf.length) req.rawBody = buf;
}

function verifyWebhook(req, res, next) {
  const reject = () => res.status(401).json({ error: 'Unauthorized' });

  const signature = req.get('X-Webhook-Signature'); // hex HMAC
  const timestamp = req.get('X-Webhook-Timestamp'); // ms since epoch
  const eventId   = req.get('X-Webhook-Event-Id');

  if (!signature || !timestamp || !eventId || !req.rawBody) {
    return reject();
  }

  // --- Freshness: reject stale or future-skewed timestamps ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts) || Math.abs(Date.now() - ts) > MAX_AGE_MS) {
    return reject();
  }

  // --- Recompute HMAC over timestamp + '.' + raw_body ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp, 'utf8'),
    Buffer.from('.', 'utf8'),
    req.rawBody,
  ]);

  let provided;
  try {
    provided = Buffer.from(signature, 'hex');
  } catch {
    return reject();
  }

  // --- Accept current OR previous secret (rotation window) ---
  // Check every candidate with constant-time comparison; no early exit on
  // which secret matched, and no oracle about how many secrets exist.
  let matched = false;
  for (const secret of WEBHOOK_SECRETS) {
    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest();

    if (provided.length === expected.length &&
        crypto.timingSafeEqual(provided, expected)) {
      matched = true;
    }
  }
  if (!matched) return reject();

  // --- Replay protection: reject repeated event IDs for 10 minutes ---
  // Runs AFTER signature verification so attackers can't poison the dedupe
  // store with unauthenticated event IDs.
  if (isReplay(eventId)) {
    return res.status(409).json({ error: 'Duplicate event' });
  }

  next();
}

const app = express();

app.post(
  '/webhooks/payments',
  express.json({ verify: rawBodySaver }),
  verifyWebhook,
  (req, res) => {
    // Authentic, fresh, and not a replay — process event
    res.status(200).json({ received: true });
  }
);
```

## Key decisions

- **Rotation:** both secrets are tried on every request; a request signed with either is accepted. To rotate: set `CURRENT=new`, `PREVIOUS=old`, wait for senders to switch, then unset `PREVIOUS`. The loop deliberately doesn't short-circuit on match, keeping timing uniform regardless of which secret was used.
- **Dedupe ordering:** the event-ID check runs **after** signature verification — otherwise an unauthenticated attacker could burn legitimate event IDs and cause denial of service.
- **Replay window vs. freshness window:** the 10-minute dedupe TTL exceeds the 5-minute timestamp window, so a replayed request is always caught by *some* layer (stale timestamp after 5 min, duplicate ID before that).
- **Multi-instance deployments:** replace the in-memory `Map` with Redis `SET event:<id> 1 NX PX 600000` — the `NX` makes the check-and-set atomic, which the in-memory version is not across processes.
- **Distinct status codes:** `401` for authentication failures (uniform, no oracle), `409` for duplicates — a legitimate sender can tell a replay apart from an auth failure, but an unauthenticated caller learns nothing.

# Final Webhook Verification Middleware (TypeScript Pseudocode)

Consolidates all requirements: raw-body HMAC-SHA256 over `timestamp + '.' + raw_body`, 5-minute freshness window, constant-time comparison, current/previous secret rotation, and 10-minute event-ID dedupe. **401** for bad signature or stale timestamp; **409** for replay.

```typescript
import crypto from 'crypto';
import { Request, Response, NextFunction } from 'express';

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

// Ordered: [0] = current, [1] = previous. Unset PREVIOUS once rotation completes.
const WEBHOOK_SECRETS: Buffer[] = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
]
  .filter((s): s is string => Boolean(s))
  .map((s) => Buffer.from(s, 'utf8'));

const MAX_AGE_MS = 5 * 60 * 1000;       // timestamp freshness window
const EVENT_ID_TTL_MS = 10 * 60 * 1000; // replay dedupe window

// ---------------------------------------------------------------------------
// Replay store — in-memory for single instance.
// Multi-instance: Redis  SET event:<id> 1 NX PX 600000  (null reply = replay)
// ---------------------------------------------------------------------------

const seenEvents = new Map<string, number>(); // eventId -> expiry epoch ms

function isReplay(eventId: string, now: number): boolean {
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id); // lazy eviction
  }
  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ---------------------------------------------------------------------------
// Raw body capture — must run BEFORE any JSON parsing
// ---------------------------------------------------------------------------

function rawBodySaver(req: Request, _res: Response, buf: Buffer): void {
  if (buf?.length) (req as any).rawBody = buf;
}

// ---------------------------------------------------------------------------
// Verification middleware
// ---------------------------------------------------------------------------

export function verifyWebhook(req: Request, res: Response, next: NextFunction): void {
  const now = Date.now();
  const unauthorized = () => res.status(401).json({ error: 'Unauthorized' });

  const signature = req.get('X-Webhook-Signature'); // hex-encoded HMAC
  const timestamp = req.get('X-Webhook-Timestamp'); // ms since epoch
  const eventId   = req.get('X-Webhook-Event-Id');
  const rawBody: Buffer | undefined = (req as any).rawBody;

  if (!signature || !timestamp || !eventId || !rawBody) {
    return void unauthorized();
  }

  // --- Freshness: stale OR future-skewed timestamps -> 401 ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts) || Math.abs(now - ts) > MAX_AGE_MS) {
    return void unauthorized();
  }

  // --- Signed payload: timestamp + '.' + raw_body (exact bytes) ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp, 'utf8'),
    Buffer.from('.', 'utf8'),
    rawBody,
  ]);

  let provided: Buffer;
  try {
    provided = Buffer.from(signature, 'hex');
  } catch {
    return void unauthorized();
  }

  // --- Accept current OR previous secret; constant-time, no early exit ---
  let matched = false;
  for (const secret of WEBHOOK_SECRETS) {
    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest();

    if (provided.length === expected.length &&
        crypto.timingSafeEqual(provided, expected)) {
      matched = true; // keep looping: uniform timing regardless of which key matched
    }
  }
  if (!matched) {
    return void unauthorized(); // bad signature -> 401
  }

  // --- Replay check AFTER auth, so attackers can't poison the store -> 409 ---
  if (isReplay(eventId, now)) {
    return void res.status(409).json({ error: 'Duplicate event' });
  }

  next();
}

// ---------------------------------------------------------------------------
// Route wiring
// ---------------------------------------------------------------------------

// app.post(
//   '/webhooks/payments',
//   express.json({ verify: rawBodySaver }),
//   verifyWebhook,
//   handler,
// );
```

## Behavior summary

| Condition | Status |
|---|---|
| Missing signature / timestamp / event ID / body | 401 |
| Stale or future-skewed timestamp (> 5 min) | 401 |
| Signature matches neither current nor previous secret | 401 |
| Valid auth, but event ID seen within last 10 min | 409 |
| Valid, fresh, first-seen event | `next()` |

## Invariants preserved

- **Raw bytes only** for the HMAC input — never re-serialized JSON.
- **`crypto.timingSafeEqual`** for all signature comparisons; length checked first; loop never short-circuits so timing doesn't reveal which secret matched.
- **Uniform 401** for every authentication failure — no oracle distinguishing stale timestamp from bad signature.
- **Dedupe strictly after authentication** — unauthenticated requests cannot burn legitimate event IDs.
- **Dedupe TTL (10 min) > freshness window (5 min)** — replays are always caught by at least one layer.

Here's a sketch in Node/Express:

```js
const crypto = require('crypto');

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get('X-Signature'); // e.g. "t=1712345678,v1=abcdef..."
  if (!signatureHeader) {
    return res.status(401).json({ error: 'missing signature' });
  }

  // Parse "t=<timestamp>,v1=<hex>"
  const parts = Object.fromEntries(
    signatureHeader.split(',').map((p) => p.split('='))
  );
  const timestamp = parseInt(parts.t, 10);
  const receivedSig = parts.v1;

  if (!timestamp || !receivedSig) {
    return res.status(401).json({ error: 'malformed signature' });
  }

  // Replay protection: reject stale timestamps (e.g. 5 min window)
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - timestamp) > 300) {
    return res.status(401).json({ error: 'timestamp outside tolerance' });
  }

  // Sign the raw body — NOT the parsed object (JSON.stringify is not stable)
  const signedPayload = `${timestamp}.${req.rawBody}`;
  const expectedSig = crypto
    .createHmac('sha256', process.env.WEBHOOK_SECRET)
    .update(signedPayload)
    .digest('hex');

  const expectedBuf = Buffer.from(expectedSig, 'utf8');
  const receivedBuf = Buffer.from(receivedSig, 'utf8');

  // Length check first: timingSafeEqual throws on mismatched lengths
  if (
    expectedBuf.length !== receivedBuf.length ||
    !crypto.timingSafeEqual(expectedBuf, receivedBuf)
  ) {
    return res.status(401).json({ error: 'invalid signature' });
  }

  next();
}
```

Key points:

- **Raw body is essential.** Configure the body parser to keep it, e.g.:
  ```js
  app.use(express.json({
    verify: (req, _res, buf) => { req.rawBody = buf; }
  }));
  ```
  Re-serializing parsed JSON can produce a different byte string and break verification.

- **Constant-time comparison** via `crypto.timingSafeEqual` prevents timing side channels; the length pre-check doesn't leak anything meaningful.

- **Timestamp in the signed payload** gives replay protection — the attacker can't replay an old valid signature because the timestamp is covered by the HMAC.

- **Secret handling:** load from env/secret manager, never hardcode; rotate by accepting multiple active secrets during rotation if needed.

- Consider also checking a source IP allowlist or provider-specific headers (e.g. `Stripe-Signature` style) as defense in depth, and returning generic 401s without detail about *why* verification failed.

That matches the sketch above — the signed payload is `${timestamp}.${req.rawBody}`, the 5-minute tolerance is enforced, and comparison is constant-time. Here's a tightened version with those requirements explicit:

```js
const crypto = require('crypto');

const TOLERANCE_SECONDS = 300; // reject timestamps older than 5 minutes

function verifyWebhookSignature(req, res, next) {
  const header = req.get('X-Signature'); // "t=<unix_seconds>,v1=<hex>"
  if (!header) {
    return res.status(401).json({ error: 'missing signature' });
  }

  const parts = Object.fromEntries(header.split(',').map((p) => p.split('=')));
  const timestamp = Number.parseInt(parts.t, 10);
  const receivedSig = parts.v1;

  if (!Number.isInteger(timestamp) || !receivedSig) {
    return res.status(401).json({ error: 'malformed signature' });
  }

  // Replay protection: reject anything outside the 5-minute window
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - timestamp) > TOLERANCE_SECONDS) {
    return res.status(401).json({ error: 'stale timestamp' });
  }

  // Signed payload: "<timestamp>.<raw_body>"
  const signedPayload = `${timestamp}.${req.rawBody}`;
  const expectedSig = crypto
    .createHmac('sha256', process.env.WEBHOOK_SECRET)
    .update(signedPayload)
    .digest('hex');

  const expectedBuf = Buffer.from(expectedSig, 'utf8');
  const receivedBuf = Buffer.from(receivedSig, 'utf8');

  // Constant-time comparison; length check first because
  // timingSafeEqual throws on mismatched lengths
  if (
    expectedBuf.length !== receivedBuf.length ||
    !crypto.timingSafeEqual(expectedBuf, receivedBuf)
  ) {
    return res.status(401).json({ error: 'invalid signature' });
  }

  next();
}
```

And the raw-body capture it depends on:

```js
app.use(express.json({
  verify: (req, _res, buf) => { req.rawBody = buf; }
}));
```

Notes on the requirements as implemented:

- **`timestamp + '.' + raw_body`** — the timestamp is inside the HMAC input, so an attacker can't take an old valid signature and refresh the timestamp; the whole signed payload is covered.
- **5-minute rejection** — `Math.abs(now - timestamp) > 300` rejects both stale and future-dated timestamps (future skew matters too, since a far-future timestamp would extend replay life).
- **Constant-time comparison** — `crypto.timingSafeEqual` on equal-length buffers; the length pre-check is required because the function throws on length mismatch.

One caveat: the 5-minute window still permits replays *within* that window. If your provider supports it, cache recently seen signature/event IDs and reject duplicates for stronger replay protection.

Here's the updated middleware with secret rotation and event-ID replay protection:

```js
const crypto = require('crypto');

const TOLERANCE_SECONDS = 300;      // 5-minute timestamp window
const EVENT_ID_TTL_MS = 10 * 60 * 1000; // reject repeated event IDs for 10 minutes

// Secrets ordered: [current, previous]. During rotation both verify;
// after rotation completes, drop the oldest.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

if (WEBHOOK_SECRETS.length === 0) {
  throw new Error('No webhook secrets configured');
}

// Event-ID replay cache. For a single process, a Map with periodic
// pruning is fine; for multi-instance deployments, back this with
// Redis (SET key NX EX 600) so the check is atomic across nodes.
const seenEventIds = new Map(); // eventId -> firstSeenAt (ms)

function pruneSeenEvents(now) {
  for (const [id, ts] of seenEventIds) {
    if (now - ts > EVENT_ID_TTL_MS) seenEventIds.delete(id);
  }
}

function verifyWebhookSignature(req, res, next) {
  const header = req.get('X-Signature'); // "t=<unix_seconds>,v1=<hex>"
  if (!header) {
    return res.status(401).json({ error: 'missing signature' });
  }

  const parts = Object.fromEntries(header.split(',').map((p) => p.split('=')));
  const timestamp = Number.parseInt(parts.t, 10);
  const receivedSig = parts.v1;
  const eventId = req.get('X-Event-Id'); // or extract from body after parsing

  if (!Number.isInteger(timestamp) || !receivedSig) {
    return res.status(401).json({ error: 'malformed signature' });
  }

  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - timestamp) > TOLERANCE_SECONDS) {
    return res.status(401).json({ error: 'stale timestamp' });
  }

  // Verify against current OR previous secret (constant-time each)
  const signedPayload = `${timestamp}.${req.rawBody}`;
  const receivedBuf = Buffer.from(receivedSig, 'utf8');

  const verified = WEBHOOK_SECRETS.some((secret) => {
    const expectedBuf = Buffer.from(
      crypto.createHmac('sha256', secret).update(signedPayload).digest('hex'),
      'utf8'
    );
    return (
      expectedBuf.length === receivedBuf.length &&
      crypto.timingSafeEqual(expectedBuf, receivedBuf)
    );
  });

  if (!verified) {
    return res.status(401).json({ error: 'invalid signature' });
  }

  // Replay protection by event ID — only checked AFTER signature
  // verification so unauthenticated requests can't poison the cache.
  if (eventId) {
    const nowMs = Date.now();
    pruneSeenEvents(nowMs);

    const firstSeen = seenEventIds.get(eventId);
    if (firstSeen !== undefined && nowMs - firstSeen <= EVENT_ID_TTL_MS) {
      return res.status(409).json({ error: 'duplicate event' });
    }
    seenEventIds.set(eventId, nowMs);
  }

  next();
}
```

Design notes:

- **Secret rotation:** try each configured secret in order; any match passes. Keep the previous secret until you're confident no in-flight deliveries still use it (at least past the 5-minute timestamp window, ideally longer). Never log which secret matched.
- **Event-ID check placement:** it runs *after* HMAC verification. Otherwise an attacker could spam arbitrary event IDs to DoS legitimate deliveries by poisoning the cache.
- **Multi-instance caveat:** the in-memory `Map` only dedupes within one process. Behind multiple replicas, use Redis: `SET webhook:evt:<id> 1 NX EX 600` — the `NX` makes the check-and-set atomic, closing the race between two concurrent deliveries of the same event.
- **Event ID source:** if the ID lives in the body rather than a header, verify the signature first, then parse `req.body` and check the ID — same ordering principle applies.
- Return a generic error on duplicates (409 here, or 200 if your provider retries on non-2xx and you'd rather ack idempotently — pick based on the provider's retry semantics).

```ts
// ---------- Configuration ----------

const TIMESTAMP_TOLERANCE_SECONDS = 300;        // reject timestamps older/newer than 5 min
const EVENT_ID_TTL_MS = 10 * 60 * 1000;         // reject repeated event IDs for 10 min

// Ordered [current, previous]. Both verify during rotation;
// remove the oldest once rotation is complete.
const WEBHOOK_SECRETS: readonly string[] = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter((s): s is string => Boolean(s));

if (WEBHOOK_SECRETS.length === 0) {
  throw new Error("No webhook secrets configured");
}

// ---------- Replay cache ----------

// Single-process version. For multi-instance deployments, replace with
// Redis: SET webhook:evt:<id> 1 NX EX 600 (atomic check-and-set).
interface EventIdStore {
  has(eventId: string): boolean;
  record(eventId: string, nowMs: number): void;
  prune(nowMs: number): void;
}

const seenEventIds = new Map<string, number>(); // eventId -> firstSeenAtMs

const eventStore: EventIdStore = {
  has(eventId) {
    return seenEventIds.has(eventId);
  },
  record(eventId, nowMs) {
    seenEventIds.set(eventId, nowMs);
  },
  prune(nowMs) {
    for (const [id, ts] of seenEventIds) {
      if (nowMs - ts > EVENT_ID_TTL_MS) seenEventIds.delete(id);
    }
  },
};

// ---------- Helpers ----------

interface SignatureHeader {
  timestamp: number;
  signature: string;
}

function parseSignatureHeader(header: string | undefined): SignatureHeader | null {
  if (!header) return null;
  const parts = Object.fromEntries(
    header.split(",").map((p) => p.split("="))
  );
  const timestamp = Number.parseInt(parts.t ?? "", 10);
  const signature = parts.v1;
  if (!Number.isInteger(timestamp) || !signature) return null;
  return { timestamp, signature };
}

function isTimestampFresh(timestamp: number, nowSeconds: number): boolean {
  return Math.abs(nowSeconds - timestamp) <= TIMESTAMP_TOLERANCE_SECONDS;
}

// Constant-time comparison; length pre-check because timingSafeEqual throws
// on mismatched lengths.
function constantTimeEqual(a: string, b: string): boolean {
  const bufA = Buffer.from(a, "utf8");
  const bufB = Buffer.from(b, "utf8");
  return bufA.length === bufB.length && crypto.timingSafeEqual(bufA, bufB);
}

// Try each active secret; any match passes. Never log which one matched.
function verifyAgainstSecrets(signedPayload: string, receivedSig: string): boolean {
  return WEBHOOK_SECRETS.some((secret) => {
    const expected = crypto
      .createHmac("sha256", secret)
      .update(signedPayload)
      .digest("hex");
    return constantTimeEqual(expected, receivedSig);
  });
}

// ---------- Middleware ----------

interface Request {
  headers: Record<string, string | undefined>;
  rawBody: Buffer; // captured via body-parser `verify` — never re-serialize parsed JSON
}

interface Response {
  status(code: number): { json(body: object): void };
}

async function verifyWebhookSignature(
  req: Request,
  res: Response,
  next: () => void
): Promise<void> {
  // 1. Parse signature header: "t=<unix_seconds>,v1=<hex>"
  const parsed = parseSignatureHeader(req.headers["x-signature"]);
  if (parsed === null) {
    res.status(401).json({ error: "missing or malformed signature" });
    return;
  }

  // 2. Timestamp freshness — reject anything outside the 5-minute window
  //    (both stale and future-dated, since future skew extends replay life).
  const nowSeconds = Math.floor(Date.now() / 1000);
  if (!isTimestampFresh(parsed.timestamp, nowSeconds)) {
    res.status(401).json({ error: "stale timestamp" });
    return;
  }

  // 3. HMAC verification over "<timestamp>.<raw_body>" against current
  //    or previous secret, constant-time.
  const signedPayload = `${parsed.timestamp}.${req.rawBody.toString("utf8")}`;
  if (!verifyAgainstSecrets(signedPayload, parsed.signature)) {
    res.status(401).json({ error: "invalid signature" });
    return;
  }

  // 4. Event-ID replay check — only AFTER signature verification so
  //    unauthenticated requests cannot poison the cache.
  const eventId = req.headers["x-event-id"];
  if (eventId) {
    const nowMs = Date.now();
    eventStore.prune(nowMs);

    if (eventStore.has(eventId)) {
      res.status(409).json({ error: "duplicate event" });
      return;
    }
    eventStore.record(eventId, nowMs);
  }

  next();
}

// ---------- Body parser wiring (required for rawBody) ----------

// app.use(express.json({
//   verify: (req, _res, buf) => { req.rawBody = buf; }
// }));
```

Status-code summary:

| Condition | Response |
|---|---|
| Missing/malformed signature header | 401 |
| Timestamp outside 5-minute window | 401 |
| HMAC mismatch against all configured secrets | 401 |
| Event ID seen within last 10 minutes | 409 |

Remaining caveats, unchanged from earlier discussion:

- The in-memory `EventIdStore` only dedupes within one process; use Redis `SET ... NX EX 600` for atomic cross-instance replay protection.
- The 10-minute event-ID window still permits replays within it; if the provider retries on non-2xx, consider returning 200 for duplicates and deduplicating downstream instead.
- Keep the previous secret active at least past the 5-minute timestamp window before retiring it.

Here's a sketch (Node.js/Express style) with the key security details baked in:

```js
const crypto = require("crypto");

function verifyWebhookSignature(webhookSecret) {
  return (req, res, next) => {
    // 1. Use the RAW body — parsed JSON won't match the signature.
    //    (Configure express.raw({ type: "application/json" }) on this route,
    //     or capture rawBody via a verify callback in express.json().)
    const rawBody = req.rawBody;
    if (!rawBody) {
      return res.status(500).send("Raw body not captured");
    }

    const sigHeader = req.get("X-Signature-256") || "";
    // 2. Parse strictly, e.g. format "sha256=<hex>"
    const m = /^sha256=([a-f0-9]{64})$/i.exec(sigHeader);
    if (!m) {
      return res.status(401).send("Missing or malformed signature");
    }
    const provided = Buffer.from(m[1], "hex");

    // 3. Compute HMAC over the exact bytes received
    const expected = crypto.createHmac("sha256", webhookSecret)
      .update(rawBody)
      .digest();

    // 4. Constant-time comparison — never use === on digests
    const ok =
      expected.length === provided.length &&
      crypto.timingSafeEqual(expected, provided);

    if (!ok) {
      return res.status(401).send("Invalid signature");
    }

    // 5. (Recommended) Replay protection via timestamp header
    //    e.g. check X-Timestamp within a 5-minute window, and include
    //    the timestamp in the signed payload per your provider's scheme.

    next();
  };
}

// Usage:
// app.post("/webhooks",
//   express.raw({ type: "application/json", limit: "1mb" }),
//   verifyWebhookSignature(process.env.WEBHOOK_SECRET),
//   (req, res) => { /* req.body is a Buffer here */ }
// );
```

Key points:

- **Raw body only**: HMAC must be computed over the exact bytes sent. Run this middleware *before* any JSON parser, using `express.raw` or a `verify` callback that stashes `req.rawBody`.
- **Constant-time compare**: `crypto.timingSafeEqual` prevents timing side channels; length-check first since it throws on mismatched lengths.
- **Strict header parsing**: validate the exact expected format rather than loosely splitting.
- **Replay protection**: if your provider includes a timestamp in the signed payload, verify it's recent and reject stale requests.
- **Secret handling**: load from env/secret manager, never hardcode; use a dedicated high-entropy secret per endpoint.

Updated sketch with the `timestamp + '.' + raw_body` scheme:

```js
const crypto = require("crypto");

const TOLERANCE_SECONDS = 300; // 5 minutes

function verifyWebhookSignature(webhookSecret) {
  return (req, res, next) => {
    // 1. Raw body required — parsed JSON won't match the signature.
    //    (Mount express.raw({ type: "application/json" }) before this.)
    const rawBody = req.rawBody;
    if (!rawBody) {
      return res.status(500).send("Raw body not captured");
    }

    // 2. Timestamp header — reject missing/malformed immediately
    const tsHeader = req.get("X-Webhook-Timestamp") || "";
    const timestamp = Number.parseInt(tsHeader, 10);
    if (!/^\d+$/.test(tsHeader) || Number.isNaN(timestamp)) {
      return res.status(401).send("Missing or malformed timestamp");
    }

    // 3. Replay protection: reject timestamps outside a 5-minute window
    const now = Math.floor(Date.now() / 1000);
    if (Math.abs(now - timestamp) > TOLERANCE_SECONDS) {
      return res.status(401).send("Timestamp outside tolerance window");
    }

    // 4. Signature header, e.g. "sha256=<hex>"
    const sigHeader = req.get("X-Signature-256") || "";
    const m = /^sha256=([a-f0-9]{64})$/i.exec(sigHeader);
    if (!m) {
      return res.status(401).send("Missing or malformed signature");
    }
    const provided = Buffer.from(m[1], "hex");

    // 5. HMAC over timestamp + '.' + raw_body (exact raw bytes)
    const expected = crypto.createHmac("sha256", webhookSecret)
      .update(`${timestamp}.${rawBody.toString("latin1")}`)
      .digest();

    // 6. Constant-time comparison
    const ok =
      expected.length === provided.length &&
      crypto.timingSafeEqual(expected, provided);

    if (!ok) {
      return res.status(401).send("Invalid signature");
    }

    next();
  };
}

// Usage:
// app.post("/webhooks",
//   express.raw({ type: "application/json", limit: "1mb" }),
//   verifyWebhookSignature(process.env.WEBHOOK_SECRET),
//   (req, res) => { /* req.body is a Buffer */ }
// );
```

Notes on the changes:

- **Signed payload**: HMAC input is exactly `timestamp + "." + raw_body`. The timestamp used in the HMAC must be the one from the header (as a decimal string), not a re-serialized value — otherwise encoding differences break verification.
- **Timestamp validation order**: parse and range-check the timestamp *before* verifying the signature. This lets you reject stale replays cheaply, and the timestamp is still authenticated by the HMAC itself, so an attacker can't tamper with it to pass the freshness check.
- **Window check**: I used `Math.abs(now - timestamp)` so future-dated timestamps are also rejected, not just old ones — prevents an attacker pre-signing far-future replays if they ever obtain a valid signed payload.
- **Constant-time comparison**: unchanged — `crypto.timingSafeEqual` with a length pre-check.
- **Raw body**: still computed over the exact bytes received; `rawBody.toString("latin1")` is byte-preserving for the concatenation (or you can `Buffer.concat([Buffer.from(ts + "."), rawBody])` to stay fully byte-level).

Updated sketch with secret rotation and event-ID dedup:

```js
const crypto = require("crypto");

const TOLERANCE_SECONDS = 300; // 5 minutes
const EVENT_ID_TTL_MS = 10 * 60 * 1000; // 10 minutes

// Simple in-process TTL cache. For multi-instance deployments,
// back this with Redis (SET key value NX EX 600) instead.
const seenEvents = new Map(); // eventId -> expiryTimestampMs

function isDuplicateEvent(eventId) {
  const now = Date.now();
  // Opportunistic cleanup to bound memory
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

function verifyWebhookSignature(secrets) {
  // secrets: { current: "...", previous: "..." } — accept either
  return (req, res, next) => {
    // 1. Raw body required — parsed JSON won't match the signature.
    const rawBody = req.rawBody;
    if (!rawBody) {
      return res.status(500).send("Raw body not captured");
    }

    // 2. Timestamp header — reject missing/malformed immediately
    const tsHeader = req.get("X-Webhook-Timestamp") || "";
    const timestamp = Number.parseInt(tsHeader, 10);
    if (!/^\d+$/.test(tsHeader) || Number.isNaN(timestamp)) {
      return res.status(401).send("Missing or malformed timestamp");
    }

    // 3. Replay protection: reject timestamps outside a 5-minute window
    const now = Math.floor(Date.now() / 1000);
    if (Math.abs(now - timestamp) > TOLERANCE_SECONDS) {
      return res.status(401).send("Timestamp outside tolerance window");
    }

    // 4. Signature header, e.g. "sha256=<hex>"
    const sigHeader = req.get("X-Signature-256") || "";
    const m = /^sha256=([a-f0-9]{64})$/i.exec(sigHeader);
    if (!m) {
      return res.status(401).send("Missing or malformed signature");
    }
    const provided = Buffer.from(m[1], "hex");

    // 5. Signed payload: timestamp + '.' + raw_body (exact raw bytes)
    const signedPayload = Buffer.concat([
      Buffer.from(`${timestamp}.`),
      rawBody,
    ]);

    // 6. Try current secret, then previous — constant-time each time.
    //    Don't short-circuit on length mismatch across candidates.
    const candidates = [secrets.current, secrets.previous].filter(Boolean);
    const matched = candidates.some((secret) => {
      const expected = crypto.createHmac("sha256", secret)
        .update(signedPayload)
        .digest();
      return expected.length === provided.length &&
        crypto.timingSafeEqual(expected, provided);
    });

    if (!matched) {
      return res.status(401).send("Invalid signature");
    }

    // 7. Event ID dedup — only AFTER signature verification, so an
    //    attacker can't poison the cache with forged event IDs.
    const eventId = req.get("X-Event-Id") || "";
    if (!eventId) {
      return res.status(401).send("Missing event ID");
    }
    if (isDuplicateEvent(eventId)) {
      return res.status(409).send("Duplicate event");
    }

    next();
  };
}

// Usage:
// app.post("/webhooks",
//   express.raw({ type: "application/json", limit: "1mb" }),
//   verifyWebhookSignature({
//     current: process.env.WEBHOOK_SECRET,
//     previous: process.env.WEBHOOK_SECRET_PREVIOUS,
//   }),
//   (req, res) => { /* req.body is a Buffer */ }
// );
```

Notes on the changes:

- **Secret rotation**: the HMAC is computed against each candidate secret and compared constant-time. Any request signed with either the current or previous secret verifies. During rotation, keep the previous secret valid for at least the max retry window of your provider, then drop it. If you later support N secrets, keep the loop but cap the list length.
- **Dedup after auth**: the event-ID check runs *after* signature verification. Checking before would let unauthenticated attackers burn real event IDs (a DoS on legitimate deliveries) by replaying them with garbage signatures.
- **Dedup semantics**: first delivery wins; a redelivery of the same event ID within 10 minutes gets `409`. Your handler should still be idempotent — the TTL cache is best-effort (it's in-process, so it won't dedup across replicas or survive restarts; use Redis `SET NX EX 600` for that).
- **Everything else preserved**: raw body, `timestamp + '.' + raw_body` signed payload, ±5-minute timestamp window (future-dated rejected too), strict header parsing, constant-time comparison.

```ts
// ---- Types & constants -----------------------------------------------------

interface WebhookSecrets {
  current: string;
  previous?: string; // valid during rotation window
}

interface VerifiedWebhook {
  eventId: string;
  timestamp: number;
  rawBody: Buffer;
}

const TIMESTAMP_TOLERANCE_SECONDS = 300; // ±5 minutes
const EVENT_ID_TTL_MS = 10 * 60 * 1000;  // 10 minutes

// ---- Event-ID dedup store --------------------------------------------------
// In-process TTL map. For multi-instance deployments, replace with Redis:
//   SET dedup:<eventId> 1 NX EX 600
const seenEvents = new Map<string, number>(); // eventId -> expiry (epoch ms)

function isDuplicateEvent(eventId: string): boolean {
  const now = Date.now();
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ---- Middleware -------------------------------------------------------------

function verifyWebhook(secrets: WebhookSecrets): Middleware {
  return (req: Request, res: Response, next: NextHandler): void => {
    // 1. Raw body required — HMAC must cover the exact bytes sent.
    //    (Mount express.raw({ type: "application/json" }) before this.)
    const rawBody: Buffer | undefined = req.rawBody;
    if (rawBody === undefined) {
      res.status(500).send("Raw body not captured");
      return;
    }

    // 2. Timestamp header — strict parse
    const tsHeader: string = req.getHeader("X-Webhook-Timestamp") ?? "";
    if (!/^\d+$/.test(tsHeader)) {
      res.status(401).send("Missing or malformed timestamp");
      return;
    }
    const timestamp: number = Number.parseInt(tsHeader, 10);

    // 3. Freshness window — rejects stale AND future-dated timestamps
    const now: number = Math.floor(Date.now() / 1000);
    if (Math.abs(now - timestamp) > TIMESTAMP_TOLERANCE_SECONDS) {
      res.status(401).send("Timestamp outside tolerance window"); // stale timestamp → 401
      return;
    }

    // 4. Signature header — strict format: "sha256=<64 hex chars>"
    const sigHeader: string = req.getHeader("X-Signature-256") ?? "";
    const match: RegExpExecArray | null = /^sha256=([a-f0-9]{64})$/i.exec(sigHeader);
    if (match === null) {
      res.status(401).send("Missing or malformed signature");
      return;
    }
    const provided: Buffer = Buffer.from(match[1]!, "hex");

    // 5. Signed payload: timestamp + '.' + raw_body (exact raw bytes)
    const signedPayload: Buffer = Buffer.concat([
      Buffer.from(`${timestamp}.`),
      rawBody,
    ]);

    // 6. Verify against current, then previous secret.
    //    Constant-time comparison for every candidate.
    const candidates: string[] = [secrets.current, secrets.previous]
      .filter((s): s is string => s !== undefined);

    const matched: boolean = candidates.some((secret) => {
      const expected: Buffer = crypto
        .createHmac("sha256", secret)
        .update(signedPayload)
        .digest();
      return (
        expected.length === provided.length &&
        crypto.timingSafeEqual(expected, provided)
      );
    });

    if (!matched) {
      res.status(401).send("Invalid signature"); // bad signature → 401
      return;
    }

    // 7. Event-ID dedup — AFTER signature verification, so unauthenticated
    //    callers can't poison the cache with forged event IDs.
    const eventId: string = req.getHeader("X-Event-Id") ?? "";
    if (eventId === "") {
      res.status(401).send("Missing event ID");
      return;
    }
    if (isDuplicateEvent(eventId)) {
      res.status(409).send("Duplicate event"); // replay → 409
      return;
    }

    // 8. Attach verified context and proceed
    (req as Request & { webhook: VerifiedWebhook }).webhook = {
      eventId,
      timestamp,
      rawBody,
    };
    next();
  };
}

// ---- Wiring -----------------------------------------------------------------

app.post(
  "/webhooks",
  express.raw({ type: "application/json", limit: "1mb" }),
  verifyWebhook({
    current: process.env.WEBHOOK_SECRET!,
    previous: process.env.WEBHOOK_SECRET_PREVIOUS,
  }),
  (req, res) => {
    const { eventId } = (req as any).webhook as VerifiedWebhook;
    // Handler must still be idempotent — dedup is best-effort.
    res.status(200).send(`Processed ${eventId}`);
  },
);
```

Status-code contract:

| Condition | Status |
|---|---|
| Missing/malformed timestamp or signature, missing event ID | 401 |
| Timestamp outside ±5-minute window (stale or future) | 401 |
| HMAC fails against both current and previous secrets | 401 |
| Valid signature but event ID seen within 10 minutes | 409 |

All prior requirements preserved: raw-body HMAC over `timestamp + '.' + raw_body`, constant-time comparison, dual-secret rotation, dedup checked only after authentication, and future-dated timestamps rejected alongside stale ones.

Here's a sketch (Node.js/Express style) with the key security properties baked in:

```js
import crypto from "crypto";

export function verifyWebhookSignature(secret) {
  return (req, res, next) => {
    // 1. Use the RAW body — parsed JSON would break the signature.
    //    (Configure express.raw({ type: "application/json" }) upstream,
    //    or read the buffered body before any parser runs.)
    const rawBody = req.rawBody ?? req.body;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(400).send("Raw body required");
    }

    // 2. Pull signature + timestamp from headers (adjust names to your provider)
    const sigHeader = req.get("x-webhook-signature");   // e.g. "t=1712345678,v1=abc123..."
    const timestamp = req.get("x-webhook-timestamp");
    if (!sigHeader || !timestamp) {
      return res.status(400).send("Missing signature headers");
    }

    // 3. Reject stale requests (replay protection) — e.g. 5-minute window
    const age = Math.abs(Date.now() / 1000 - Number(timestamp));
    if (!Number.isFinite(age) || age > 300) {
      return res.status(401).send("Timestamp outside tolerance");
    }

    // 4. Recompute HMAC over `${timestamp}.${rawBody}` (per provider's scheme)
    const expected =
      "v1=" +
      crypto
        .createHmac("sha256", secret)
        .update(`${timestamp}.${rawBody}`)
        .digest("hex");

    // 5. Constant-time comparison — never use === on MACs
    const provided = Buffer.from(sigHeader);
    const expectedBuf = Buffer.from(expected);
    if (
      provided.length !== expectedBuf.length ||
      !crypto.timingSafeEqual(provided, expectedBuf)
    ) {
      return res.status(401).send("Invalid signature");
    }

    next();
  };
}
```

Key points to preserve in a real implementation:

- **Raw body only**: the signature is computed over the exact bytes sent; any body parsing/normalization before verification invalidates it. Mount `express.raw()` for the webhook route specifically.
- **Constant-time compare**: `crypto.timingSafeEqual` (or a language equivalent) to avoid timing side channels. Length-check first, since `timingSafeEqual` throws on mismatched lengths.
- **Replay protection**: verify a signed timestamp and reject anything outside a small tolerance window. Optionally track seen event IDs for idempotency.
- **Fail closed**: any missing/invalid input returns an error — never fall through to the handler.
- **Secret handling**: load from a secret manager/env, never hardcode; use a provider-specific secret so compromise is isolated.

The exact header names and the `timestamp.body` concatenation scheme vary by provider (Stripe, GitHub, etc.), so match the provider's documented canonical string.

