// Assertion 1: empty strings become null, but 0 and false are preserved
console.assert(
  JSON.stringify(normalize({ a: "   ", b: 0, c: false })) ===
    JSON.stringify({ a: null, b: 0, c: false }),
  "empty strings -> null; 0 and false preserved"
);

// Assertion 2: undefined object properties are omitted
