# Updated Middleware: Timestamped Payload + Replay Protection

The signature is now computed over `timestamp + '.' + raw_body`, so we verify the HMAC **and** enforce a 5-minute freshness window. Both checks fail closed.

```js
const crypto = require('crypto');

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000; // 5 minutes

/**
 * Verifies an HMAC-SHA256 webhook signature over `timestamp + '.' + rawBody`.
 *
 * Expected header: `X-Signature: <hex HMAC>`
 * Expected header: `X-Timestamp: <unix seconds>` (or extract from a
 * combined header like `t=...,v1=...` — adapt parsing to your provider).
 */
function verifyWebhookSignature(secret) {
  return function webhookSignatureVerifier(req, res, next) {
    const signatureHeader = req.get('X-Signature');
    const timestampHeader = req.get('X-Timestamp');

    // Fail closed: missing headers.
    if (!signatureHeader || !timestampHeader) {
      return res.status(401).json({ error: 'Missing signature headers' });
    }

    // --- Timestamp validation (reject before doing crypto work) ---
    const timestamp = Number(timestampHeader);
    if (
      !Number.isInteger(timestamp) ||
      timestamp <= 0 ||
      String(timestamp) !== timestampHeader.trim() // reject "123abc", "1e3", etc.
    ) {
      return res.status(401).json({ error: 'Malformed timestamp' });
    }

    const age = Date.now() - timestamp * 1000;
    if (age > MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: 'Timestamp expired' });
    }
    // Optionally reject far-future timestamps too (clock skew / abuse):
    if (age < -MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: 'Timestamp out of range' });
    }

    // --- Signature validation ---
    const provided = signatureHeader.replace(/^sha256=/, '').trim();
    if (!/^[0-9a-fA-F]+$/.test(provided)) {
      return res.status(401).json({ error: 'Malformed signature' });
    }

    const providedBuf = Buffer.from(provided, 'hex');
    if (providedBuf.length !== 32) {
      return res.status(401).json({ error: 'Invalid signature length' });
    }

    // Signed payload: timestamp + '.' + raw body — exact bytes.
    const signedPayload = Buffer.concat([
      Buffer.from(`${timestamp}.`, 'utf8'),
      req.rawBody,
    ]);

    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest();

    // Constant-time comparison — never use === on secrets.
    const valid = crypto.timingSafeEqual(providedBuf, expected);

    if (!valid) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}
```

## Raw body capture (unchanged, but critical)

```js
app.use(
  express.json({
    verify: (req, _res, buf) => {
      req.rawBody = buf;
    },
  })
);
```

## Notes on the design

- **Timestamp check runs first** — it's cheap, and rejecting stale requests before the HMAC computation avoids wasting CPU on replays. (The timestamp is still covered by the signature, so an attacker can't tamper with it without invalidating the HMAC.)
- **Strict timestamp parsing** — `Number("1e3")` and `Number("12.5")` are valid JS numbers but not valid unix-second strings; the `String(timestamp) === header` round-trip check rejects those.
- **Future timestamps** — rejecting timestamps more than 5 minutes in the future guards against clients with badly skewed clocks being used to push long-lived valid windows.
- **Replay window caveat** — within the 5-minute window, a captured request can still be replayed. If that matters for your threat model, add a nonce/ID cache (e.g., Redis with 5-minute TTL keyed on a unique event ID) to reject duplicates.
- **Buffer concat, not string concat** — building the signed payload via `Buffer.concat` avoids any re-encoding surprises if the body contains multi-byte characters.

