# Final: TypeScript Webhook Verification Middleware

Consolidated spec:

- HMAC-SHA256 over `timestamp + '.' + rawBody` (exact bytes)
- 5-minute timestamp window (past **and** future)
- Accept current **or** previous secret (rotation)
- Reject repeated event ID within 10 minutes
- Constant-time comparison everywhere
- **401** for bad signature / stale timestamp / malformed input
- **409** for replayed event ID
- Fail closed on internal errors

```ts
import { createHmac, timingSafeEqual } from "crypto";

// ---------- Types ----------

interface SecretPair {
  current: Buffer;
  /** Null when no rotation is in progress. */
  previous: Buffer | null;
}

interface ReplayStore {
  /**
   * Atomically record an event ID.
   * @returns true if first sighting, false if already seen (replay).
   */
  setIfAbsent(key: string, ttlSeconds: number): Promise<boolean>;
}

interface RawBodyRequest extends Request {
  rawBody: Buffer;
}

// ---------- Constants ----------

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;  // timestamp freshness window
const REPLAY_TTL_SECONDS = 10 * 60;       // event dedup window (>= skew window)
const HMAC_LENGTH = 32;                   // SHA-256 digest size in bytes

// ---------- Middleware ----------

function verifyWebhookSignature(
  secrets: SecretPair,
  replayStore: ReplayStore
): (req: RawBodyRequest, res: Response, next: NextFunction) => Promise<void> {
  return async (req, res, next): Promise<void> => {
    try {
      const signatureHeader = req.get("X-Signature");
      const timestampHeader = req.get("X-Timestamp");
      const eventId = req.get("X-Event-Id");

      // --- Fail closed: missing headers -> 401 ---
      if (!signatureHeader || !timestampHeader || !eventId) {
        return res.status(401).json({ error: "Missing required headers" });
      }

      // --- Event ID sanity -> 401 ---
      if (!/^[A-Za-z0-9._-]{1,128}$/.test(eventId)) {
        return res.status(401).json({ error: "Malformed event ID" });
      }

      // --- Timestamp validation -> 401 ---
      const ts = Number(timestampHeader);
      if (
        !Number.isInteger(ts) ||
        ts <= 0 ||
        String(ts) !== timestampHeader.trim()
      ) {
        return res.status(401).json({ error: "Malformed timestamp" });
      }

      const ageMs = Date.now() - ts * 1000;
      if (Math.abs(ageMs) > MAX_CLOCK_SKEW_MS) {
        return res.status(401).json({ error: "Timestamp out of range" });
      }

      // --- Signature validation -> 401 ---
      const providedHex = signatureHeader.replace(/^sha256=/, "").trim();
      if (!/^[0-9a-fA-F]+$/.test(providedHex)) {
        return res.status(401).json({ error: "Malformed signature" });
      }

      const provided = Buffer.from(providedHex, "hex");
      if (provided.length !== HMAC_LENGTH) {
        return res.status(401).json({ error: "Invalid signature length" });
      }

      // Signed payload: timestamp + '.' + raw body, exact bytes.
      const signedPayload = Buffer.concat([
        Buffer.from(`${ts}.`, "utf8"),
        req.rawBody,
      ]);

      // Try current secret first (common case), then previous.
      const candidates = secrets.previous
        ? [secrets.current, secrets.previous]
        : [secrets.current];

      const signatureValid = candidates.some((secret) => {
        const expected = createHmac("sha256", secret)
          .update(signedPayload)
          .digest();
        return timingSafeEqual(provided, expected); // constant-time
      });

      if (!signatureValid) {
        return res.status(401).json({ error: "Invalid signature" });
      }

      // --- Replay protection (only after signature verifies) -> 409 ---
      const firstSighting = await replayStore.setIfAbsent(
        `webhook:seen:${eventId}`,
        REPLAY_TTL_SECONDS
      );

      if (!firstSighting) {
        return res.status(409).json({ error: "Duplicate event" });
      }

      next();
    } catch {
      // Fail closed on internal errors (e.g., replay store outage).
      return res.status(500).json({ error: "Verification unavailable" });
    }
  };
}
```

## Raw body capture (must run before JSON parsing)

```ts
app.use(
  express.json({
    limit: "1mb",
    verify: (req: RawBodyRequest, _res, buf: Buffer) => {
      req.rawBody = buf; // exact bytes as received
    },
  })
);
```

## Redis-backed replay store

```ts
function createReplayStore(redis: RedisClient): ReplayStore {
  return {
    async setIfAbsent(key: string, ttlSeconds: number): Promise<boolean> {
      // SET key 1 NX EX <ttl> — atomic check-and-set.
      const result = await redis.set(key, "1", { NX: true, EX: ttlSeconds });
      return result === "OK";
    },
  };
}
```

## Wiring

```ts
app.post(
  "/webhooks",
  verifyWebhookSignature(
    {
      current: Buffer.from(process.env.WEBHOOK_SECRET!, "utf8"),
      previous: process.env.WEBHOOK_SECRET_PREV
        ? Buffer.from(process.env.WEBHOOK_SECRET_PREV, "utf8")
        : null,
    },
    createReplayStore(redisClient)
  ),
  (req, res) => {
    // Signature verified, timestamp fresh, event not seen before.
    res.status(200).json({ received: true });
  }
);
```

## Response code summary

| Condition | Status |
|---|---|
| Missing/malformed headers, bad timestamp, bad signature | **401** |
| Valid signature, event ID seen in last 10 min | **409** |
| Internal failure (replay store down, etc.) | **500** (fail closed) |
| Verified and fresh | **200** via handler |

## Invariants preserved

1. HMAC computed over raw bytes — never over a re-encoded body.
2. All secret comparisons use `timingSafeEqual` — no `===` on digests.
3. Replay check runs **after** signature verification — unauthenticated callers can't poison the dedup cache.
4. `REPLAY_TTL_SECONDS (600) ≥ MAX_CLOCK_SKEW_MS (300)` — an attacker can't outwait the cache while the timestamp is still valid.
5. Rotation: deploy with `previous = old`, `current = new`; after cutover, deploy with `previous = null`. Never more than two active secrets.
6. Every failure path rejects; nothing falls through to the handler on error.

Here's a sketch using Node.js/Express-style middleware. The key security requirement: **verify the HMAC against the raw request body bytes, before any parsing or decoding**, since signature computation is byte-exact.

```javascript
const crypto = require("crypto");

/**
 * Timing-safe comparison is mandatory — never use === for MAC comparison.
 * Raw body must be captured before JSON parsing.
 */
function verifyWebhookSignature(secret) {
  return function webhookVerifier(req, res, next) {
    const signatureHeader = req.headers["x-webhook-signature"]; // hex-encoded HMAC-SHA256

    if (!signatureHeader || typeof signatureHeader !== "string") {
      return res.status(401).json({ error: "Missing signature" });
    }

    // req.rawBody must be the exact bytes received — attach via a body-parser
    // verify callback or a stream buffer BEFORE express.json() runs.
    if (!Buffer.isBuffer(req.rawBody)) {
      return res.status(500).json({ error: "Raw body unavailable" });
    }

    const expected = crypto
      .createHmac("sha256", secret)
      .update(req.rawBody)
      .digest("hex");

    // Constant-time compare to prevent timing side channels
    const a = Buffer.from(signatureHeader, "utf8");
    const b = Buffer.from(expected, "utf8");

    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: "Invalid signature" });
    }

    next();
  };
}
```

Capturing the raw body (must run **before** the JSON parser):

```javascript
app.use(
  express.json({
    verify: (req, res, buf) => {
      req.rawBody = buf; // buf is the unparsed buffer
    },
  })
);
app.use("/webhooks", verifyWebhookSignature(process.env.WEBHOOK_SECRET));
```

Security notes to preserve:

1. **Raw bytes, not `req.body`** — re-serialized JSON will not match the signature.
2. **`crypto.timingSafeEqual`** — never compare MACs with `===` (timing attacks).
3. **Length check before `timingSafeEqual`** — it throws on length mismatch; check explicitly.
4. **Secret from environment/config**, never hardcoded; reject if absent.
5. **Fail closed** — missing signature, missing raw body, or mismatch all return 401/500 without leaking details.
6. Optionally enforce a **timestamp header + tolerance window** to blunt replay attacks, and reject bodies over a size limit before buffering.

Updated middleware — the MAC is computed over `timestamp + "." + raw_body`, with a 5-minute freshness window and constant-time comparison:

```javascript
const crypto = require("crypto");

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000; // 5 minutes

function verifyWebhookSignature(secret) {
  return function webhookVerifier(req, res, next) {
    const signatureHeader = req.headers["x-webhook-signature"]; // hex HMAC-SHA256
    const timestampHeader = req.headers["x-webhook-timestamp"]; // unix seconds

    if (!signatureHeader || typeof signatureHeader !== "string") {
      return res.status(401).json({ error: "Missing signature" });
    }
    if (!timestampHeader || typeof timestampHeader !== "string") {
      return res.status(401).json({ error: "Missing timestamp" });
    }

    // Raw bytes captured before JSON parsing (see body-parser verify hook)
    if (!Buffer.isBuffer(req.rawBody)) {
      return res.status(500).json({ error: "Raw body unavailable" });
    }

    // --- Timestamp freshness check (replay protection) ---
    const timestamp = Number(timestampHeader);
    if (!Number.isFinite(timestamp) || !Number.isInteger(timestamp)) {
      return res.status(401).json({ error: "Invalid timestamp" });
    }

    const ageMs = Date.now() - timestamp * 1000;
    if (ageMs > MAX_CLOCK_SKEW_MS || ageMs < -MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: "Timestamp outside tolerance window" });
    }

    // --- MAC over timestamp + "." + raw body ---
    const signedPayload = Buffer.concat([
      Buffer.from(timestampHeader + ".", "utf8"), // use the header string verbatim
      req.rawBody,
    ]);

    const expected = crypto
      .createHmac("sha256", secret)
      .update(signedPayload)
      .digest("hex");

    // --- Constant-time comparison ---
    const a = Buffer.from(signatureHeader, "utf8");
    const b = Buffer.from(expected, "utf8");

    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: "Invalid signature" });
    }

    next();
  };
}
