Updated middleware with dual-secret rotation support and a 10-minute event-ID replay cache:

```javascript
const crypto = require("crypto");

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;   // timestamp tolerance window
const REPLAY_TTL_MS = 10 * 60 * 1000;     // event ID dedup window

/**
 * In-memory replay cache. For multi-instance deployments, back this with
 * Redis (SET key value NX EX 600) so the check is shared across nodes.
 */
const seenEventIds = new Map(); // eventId -> expiry (ms)

function pruneReplayCache(now) {
  for (const [id, expiry] of seenEventIds) {
    if (expiry <= now) seenEventIds.delete(id);
  }
}

function verifyWebhookSignature(currentSecret, previousSecret) {
  return function webhookVerifier(req, res, next) {
    const signatureHeader = req.headers["x-webhook-signature"]; // hex HMAC-SHA256
    const timestampHeader = req.headers["x-webhook-timestamp"]; // unix seconds
    const eventIdHeader = req.headers["x-webhook-event-id"];

    if (!signatureHeader || typeof signatureHeader !== "string") {
      return res.status(401).json({ error: "Missing signature" });
    }
    if (!timestampHeader || typeof timestampHeader !== "string") {
      return res.status(401).json({ error: "Missing timestamp" });
    }
    if (!eventIdHeader || typeof eventIdHeader !== "string") {
      return res.status(401).json({ error: "Missing event ID" });
    }

    if (!Buffer.isBuffer(req.rawBody)) {
      return res.status(500).json({ error: "Raw body unavailable" });
    }

    // --- Timestamp freshness (replay protection, layer 1) ---
    const timestamp = Number(timestampHeader);
    if (!Number.isFinite(timestamp) || !Number.isInteger(timestamp)) {
      return res.status(401).json({ error: "Invalid timestamp" });
    }

    const now = Date.now();
    const ageMs = now - timestamp * 1000;
    if (ageMs > MAX_CLOCK_SKEW_MS || ageMs < -MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: "Timestamp outside tolerance window" });
    }

    // --- MAC over timestamp + "." + raw body ---
    const signedPayload = Buffer.concat([
      Buffer.from(timestampHeader + ".", "utf8"),
      req.rawBody,
    ]);

    // --- Dual-secret verification (rotation support) ---
    // Compute MACs under BOTH secrets, then compare in constant time.
    // Always evaluate both so timing doesn't reveal which secret matched.
    const candidates = [currentSecret, previousSecret].filter(Boolean);
    if (candidates.length === 0) {
      return res.status(500).json({ error: "No webhook secrets configured" });
    }

    let matched = false;
    const a = Buffer.from(signatureHeader, "utf8");
    for (const secret of candidates) {
      const expected = crypto
        .createHmac("sha256", secret)
        .update(signedPayload)
        .digest("hex");
      const b = Buffer.from(expected, "utf8");
      if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
        matched = true;
      }
    }

    if (!matched) {
      return res.status(401).json({ error: "Invalid signature" });
    }

    // --- Event ID replay rejection (replay protection, layer 2) ---
    pruneReplayCache(now);
    if (seenEventIds.has(eventIdHeader)) {
      return res.status(401).json({ error: "Duplicate event" });
    }
    seenEventIds.set(eventIdHeader, now + REPLAY_TTL_MS);

    next();
  };
}
