Final TypeScript-like pseudocode, consolidating all accumulated requirements:

```typescript
import { createHmac, timingSafeEqual } from "crypto";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;   // reject timestamps older than 5 min
const REPLAY_TTL_MS     = 10 * 60 * 1000;  // reject repeated event IDs for 10 min

interface WebhookSecrets {
  current:  string;             // active signing secret
  previous?: string;           // prior secret, valid during rotation window
}

// ---------------------------------------------------------------------------
// Replay cache — in-memory for single instance.
// Multi-instance deployments MUST use a shared store
// (e.g. Redis: SET eventId 1 NX EX 600) so the check is global.
// ---------------------------------------------------------------------------
const seenEventIds = new Map<string, number>(); // eventId -> expiry (ms)

function pruneReplayCache(now: number): void {
  for (const [id, expiry] of seenEventIds) {
    if (expiry <= now) seenEventIds.delete(id);
  }
}

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------
interface WebhookRequest {
  headers: {
    "x-webhook-signature"?: string;  // hex-encoded HMAC-SHA256
    "x-webhook-timestamp"?: string;  // unix seconds, as sent
    "x-webhook-event-id"?:  string;
  };
  rawBody?: Buffer;                  // exact bytes received, pre-parse
}

type Next = () => void;

function verifyWebhookSignature(secrets: WebhookSecrets) {
  return (req: WebhookRequest, res: Response, next: Next): void => {
    const signatureHeader  = req.headers["x-webhook-signature"];
    const timestampHeader = req.headers["x-webhook-timestamp"];
    const eventIdHeader   = req.headers["x-webhook-event-id"];

    // --- Fail closed on missing headers ---
    if (!signatureHeader || !timestampHeader || !eventIdHeader) {
      return res.status(401).json({ error: "Missing required headers" });
    }

    // --- Raw body must be the exact bytes received (captured pre-parse) ---
    if (!Buffer.isBuffer(req.rawBody)) {
      return res.status(500).json({ error: "Raw body unavailable" });
    }

    // --- Fail closed if no secrets configured ---
    const candidates = [secrets.current, secrets.previous].filter(Boolean);
    if (candidates.length === 0) {
      return res.status(500).json({ error: "No webhook secrets configured" });
    }

    // ------------------------------------------------------------------
    // 1. Timestamp freshness — stale or future timestamps => 401
    // ------------------------------------------------------------------
    const timestamp = Number(timestampHeader);
    if (!Number.isFinite(timestamp) || !Number.isInteger(timestamp)) {
      return res.status(401).json({ error: "Invalid timestamp" });
    }

    const now = Date.now();
    const ageMs = now - timestamp * 1000;
    if (ageMs > MAX_CLOCK_SKEW_MS || ageMs < -MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: "Timestamp outside tolerance window" });
    }

    // ------------------------------------------------------------------
    // 2. Signature verification — MAC over timestamp + "." + raw body
    //    Accept current OR previous secret (rotation support).
    //    Always evaluate every candidate so timing does not reveal
    //    which secret matched. Constant-time comparison only.
    // ------------------------------------------------------------------
    const signedPayload = Buffer.concat([
      Buffer.from(timestampHeader + ".", "utf8"), // header string verbatim
      req.rawBody,                                // raw bytes, never req.body
    ]);

    const provided = Buffer.from(signatureHeader, "utf8");
    let matched = false;

    for (const secret of candidates) {
      const expected = Buffer.from(
        createHmac("sha256", secret).update(signedPayload).digest("hex"),
        "utf8"
      );
      // Explicit length check: timingSafeEqual throws on length mismatch.
      if (provided.length === expected.length && timingSafeEqual(provided, expected)) {
        matched = true;
      }
    }

    if (!matched) {
      return res.status(401).json({ error: "Invalid signature" });
    }

    // ------------------------------------------------------------------
    // 3. Replay rejection — duplicate event ID within TTL => 409.
    //    Runs AFTER signature verification so unauthenticated callers
    //    cannot poison the cache.
    // ------------------------------------------------------------------
    pruneReplayCache(now);
    if (seenEventIds.has(eventIdHeader)) {
      return res.status(409).json({ error: "Duplicate event" });
    }
    seenEventIds.set(eventIdHeader, now + REPLAY_TTL_MS);

    next();
  };
}

// ---------------------------------------------------------------------------
// Wiring — raw body capture MUST run before the JSON parser
// ---------------------------------------------------------------------------
app.use(express.json({
  verify: (req, res, buf) => { req.rawBody = buf; },
  limit: "1mb", // bound buffering before verification
}));

app.use("/webhooks", verifyWebhookSignature({
  current:  process.env.WEBHOOK_SECRET_CURRENT!,  // fail startup if unset
  previous: process.env.WEBHOOK_SECRET_PREVIOUS,  // optional during rotation
}));
```

**Status code contract:**

| Condition | Status |
|---|---|
| Missing headers, invalid/stale timestamp, bad signature | **401** |
| Valid signature but repeated event ID within 10 min | **409** |
| Server-side misconfiguration (no raw body, no secrets) | **500** |

**Accumulated security requirements (final):**

1. Verify HMAC-SHA256 against the **raw request bytes**, never re-serialized `req.body`.
2. MAC input is `timestamp + "." + raw_body`, timestamp header used **verbatim**.
3. **Reject timestamps older than 5 minutes** (and future ones beyond the same window) → 401.
4. **Constant-time comparison** via `timingSafeEqual`, with an explicit length check first; never `===`.
5. **Dual-secret rotation**: accept current or previous secret; compute and compare against **all** candidates every request so timing doesn't leak which matched; fail closed if none configured.
6. **Reject repeated event IDs for 10 minutes** → 409; check runs after signature verification to prevent cache poisoning; use a shared store (Redis `SET NX EX 600`) for multi-instance deployments.
7. **Fail closed** on all missing/invalid inputs; no detail leakage in error bodies.
8. Secrets from **environment**, never hardcoded; body size limited before buffering.

# Webhook HMAC-SHA256 Verification Middleware

Here's a sketch (Node/Express-style) with the key security points called out:

```js
const crypto = require('crypto');

function verifyWebhook(secret) {
  return (req, res, next) => {
    // 1. Capture the RAW body — do not parse/re-serialize it.
    //    Configure body parser to expose rawBody, e.g.:
    //    app.use(express.json({ verify: (req, buf) => { req.rawBody = buf; } }));
    const rawBody = req.rawBody;
    if (!rawBody) {
      return res.status(400).json({ error: 'Missing raw body' });
    }

    // 2. Read the signature header (adjust name per provider, e.g.
    //    x-signature-256, x-hub-signature-256, x-webhook-signature).
    const header = req.get('x-signature-256') || '';
    const provided = header.replace(/^sha256=/, '').toLowerCase();

    // 3. Reject malformed signatures early (hex, 64 chars).
    if (!/^[a-f0-9]{64}$/.test(provided)) {
      return res.status(400).json({ error: 'Malformed signature' });
    }

    // 4. Compute HMAC-SHA256 over the raw bytes.
    const expected = crypto
      .createHmac('sha256', secret)
      .update(rawBody)
      .digest('hex');

    // 5. Timing-safe comparison — never use === on secrets.
    const a = Buffer.from(expected, 'hex');
    const b = Buffer.from(provided, 'hex');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

app.use('/webhooks', verifyWebhook(process.env.WEBHOOK_SECRET));
```

## Key requirements baked in

1. **Raw body, not parsed body** — HMAC must be computed over the exact bytes received. Re-serializing JSON changes whitespace/ordering and breaks the hash. Capture the buffer *before* parsing (via `verify` hook or a raw-body middleware).
2. **Timing-safe comparison** — `crypto.timingSafeEqual` (or equivalent) prevents leaking the expected digest byte-by-byte via response timing.
3. **Constant-length buffers** — `timingSafeEqual` throws on length mismatch, so check lengths explicitly; the regex pre-check also rejects garbage input cheaply.
4. **Fail closed** — missing body, missing header, or malformed signature all return 4xx without falling through to the handler.
5. **Secret from environment/config**, never hardcoded or logged.
6. **Verify before any business logic** — the middleware runs before handlers so unauthenticated payloads never reach app code.

Optional hardening: replay protection via a timestamp header + nonce with a tolerance window, and per-endpoint secrets if you serve multiple providers. Want me to adapt this for a specific framework (FastAPI, Koa, Go) or a specific provider's header format?

# Updated Middleware: Timestamped Payload

The signature is now computed over `timestamp + '.' + raw_body`, with a 5-minute freshness window:

```js
const crypto = require('crypto');

const TOLERANCE_MS = 5 * 60 * 1000; // 5 minutes

function verifyWebhook(secret) {
  return (req, res, next) => {
    // 1. Raw body captured before JSON parsing:
    //    app.use(express.json({ verify: (req, buf) => { req.rawBody = buf; } }));
    const rawBody = req.rawBody;
    if (!rawBody) {
      return res.status(400).json({ error: 'Missing raw body' });
    }

    // 2. Signature header, e.g. "t=1690000000,v1=abc123..." or a bare hex digest.
    //    Here we assume the timestamp arrives in a header; adjust per provider.
    const tsHeader = req.get('x-webhook-timestamp');
    const provided = (req.get('x-signature-256') || '')
      .replace(/^sha256=/, '')
      .toLowerCase();

    if (!tsHeader || !/^\d+$/.test(tsHeader)) {
      return res.status(400).json({ error: 'Missing or malformed timestamp' });
    }
    if (!/^[a-f0-9]{64}$/.test(provided)) {
      return res.status(400).json({ error: 'Malformed signature' });
    }

    // 3. Freshness check — reject anything older than 5 minutes.
    const timestamp = parseInt(tsHeader, 10);
    const age = Date.now() - timestamp * 1000; // header in seconds
    if (age < 0 || age > TOLERANCE_MS) {
      return res.status(401).json({ error: 'Timestamp outside tolerance window' });
    }

    // 4. Compute HMAC over timestamp + '.' + raw body.
    const signedPayload = `${tsHeader}.${rawBody.toString('binary')}`;
    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest('hex');

    // 5. Constant-time comparison.
    const a = Buffer.from(expected, 'hex');
    const b = Buffer.from(provided, 'hex');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

app.use('/webhooks', verifyWebhook(process.env.WEBHOOK_SECRET));
```

## Notes on the changes

1. **Signed payload construction** — the HMAC input is exactly `timestamp + '.' + raw_body`. The timestamp used in the HMAC must be the *same string* received from the provider (don't reformat it, e.g. don't re-pad or re-parse it), or the digest won't match.
2. **Freshness window** — `age < 0` also rejects future-dated timestamps (clock skew or tampering); you can allow a small negative skew if your servers' clocks drift.
3. **Order of checks** — timestamp validity is checked *before* the (more expensive) HMAC computation, but both fail closed with 401/400 and no information leaked about *why* the signature failed.
4. **Constant-time compare retained** — `timingSafeEqual` with explicit length check; the regex pre-validation still rejects malformed digests cheaply.
5. **Replay protection** — the 5-minute window bounds replay attacks, but doesn't eliminate them. For strict guarantees, cache seen `(timestamp, digest)` pairs (or a digest of the raw body) for the window duration and reject duplicates.

One caveat: `rawBody.toString('binary')` round-trips bytes safely for HMAC input, but if you can, build the signed payload as `Buffer.concat([Buffer.from(tsHeader + '.'), rawBody])` to avoid any encoding surprises entirely. Want me to include that version, or add the replay cache?

# Updated Middleware: Secret Rotation + Replay Cache

Two additions: try both current and previous secrets, and reject duplicate event IDs within a 10-minute window.

```js
const crypto = require('crypto');

const TOLERANCE_MS = 5 * 60 * 1000;   // timestamp freshness
const REPLAY_WINDOW_MS = 10 * 60 * 1000; // event ID dedup window

// In-memory replay cache. For multi-instance deployments, back this with
// Redis (SET key NX EX 600) so all instances share the view.
const seenEvents = new Map(); // eventId -> expiry timestamp

function pruneReplayCache(now = Date.now()) {
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
}

function verifyWebhook(secrets) {
  // secrets: { current: string, previous: string | null }
  return (req, res, next) => {
    // 1. Raw body captured before JSON parsing.
    const rawBody = req.rawBody;
    if (!rawBody) {
      return res.status(400).json({ error: 'Missing raw body' });
    }

    // 2. Headers: timestamp, signature, event ID.
    const tsHeader = req.get('x-webhook-timestamp');
    const eventId = req.get('x-webhook-event-id');
    const provided = (req.get('x-signature-256') || '')
      .replace(/^sha256=/, '')
      .toLowerCase();

    if (!tsHeader || !/^\d+$/.test(tsHeader)) {
      return res.status(400).json({ error: 'Missing or malformed timestamp' });
    }
    if (!eventId) {
      return res.status(400).json({ error: 'Missing event ID' });
    }
    if (!/^[a-f0-9]{64}$/.test(provided)) {
      return res.status(400).json({ error: 'Malformed signature' });
    }

    // 3. Freshness check — reject older than 5 minutes (and future-dated).
    const timestamp = parseInt(tsHeader, 10);
    const now = Date.now();
    const age = now - timestamp * 1000;
    if (age < 0 || age > TOLERANCE_MS) {
      return res.status(401).json({ error: 'Timestamp outside tolerance window' });
    }

    // 4. Compute HMAC over timestamp + '.' + raw body — try BOTH secrets.
    const signedInput = Buffer.concat([
      Buffer.from(tsHeader + '.'),
      rawBody,
    ]);
    const providedBuf = Buffer.from(provided, 'hex');
    let valid = false;

    for (const secret of [secrets.current, secrets.previous]) {
      if (!secret) continue;
      const expected = crypto
        .createHmac('sha256', secret)
        .update(signedInput)
        .digest('hex');
      const expectedBuf = Buffer.from(expected, 'hex');
      if (
        expectedBuf.length === providedBuf.length &&
        crypto.timingSafeEqual(expectedBuf, providedBuf)
      ) {
        valid = true;
        break;
      }
    }

    if (!valid) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // 5. Replay protection — reject repeated event IDs for 10 minutes.
    //    Only reached AFTER signature verification, so attackers can't
    //    poison the cache with forged IDs.
    pruneReplayCache(now);
    if (seenEvents.has(eventId)) {
      return res.status(409).json({ error: 'Duplicate event' });
    }
    seenEvents.set(eventId, now + REPLAY_WINDOW_MS);

    next();
  };
}

app.use('/webhooks', verifyWebhook({
  current: process.env.WEBHOOK_SECRET,
  previous: process.env.WEBHOOK_SECRET_PREVIOUS || null,
}));
```

## Notes on the changes

1. **Dual-secret verification** — both secrets are tried with the same constant-time comparison; the loop breaks on first match. The `previous` secret is optional (`null` skips it), so this degrades cleanly when there's no rotation in flight. Rotation procedure: deploy with the new secret as `current` and old as `previous` → wait longer than the provider's max retry/signing overlap window → drop `previous`.
2. **Replay cache ordering matters** — the event ID is recorded *only after* the signature verifies. If you deduped before verifying, an attacker could send forged requests with a victim's event ID and cause legitimate deliveries to be rejected (a denial-of-service on the cache).
3. **Cache window vs. tolerance window** — the 10-minute replay window deliberately exceeds the 5-minute timestamp tolerance, so a replayed event can't outlive the dedup record by waiting out the freshness check.
4. **In-memory cache caveat** — `Map` works for a single instance. With multiple replicas behind a load balancer, a replay can hit a different instance and slip through; use Redis (`SET eventId 1 NX EX 600`) or similar shared store. The prune-on-access approach also bounds memory; a periodic sweep or LRU cap is a good belt-and-braces addition.
5. **Buffer-concat signed input** — as flagged earlier, the HMAC input is now built via `Buffer.concat` over the raw bytes, avoiding any string-encoding round-trip on the body.
6. **409 vs. 401 for duplicates** — returning 409 (or 200-with-no-op, depending on provider retry semantics) lets you distinguish "we saw this" from "you're not authenticated." Some providers treat any non-2xx as a failure and retry; if yours does, consider returning 200 for verified duplicates to stop retry storms.

