# Final: Webhook Verification Middleware (TypeScript-like Pseudocode)

```ts
import { createHmac, timingSafeEqual } from "crypto";

// ---- Configuration -------------------------------------------------------

const TIMESTAMP_TOLERANCE_MS = 5 * 60 * 1000;   // reject stale timestamps
const REPLAY_WINDOW_MS      = 10 * 60 * 1000;  // reject repeated event IDs

interface Secrets {
  current:  string;          // active signing secret
  previous: string | null;   // prior secret during rotation, else null
}

// ---- Replay cache ---------------------------------------------------------
// Single-instance: in-memory Map. Multi-instance: back with a shared store
// (e.g. Redis SET eventId 1 NX EX 600) so all replicas share the view.

const seenEvents = new Map<string, number>(); // eventId -> expiry epoch ms

function pruneReplayCache(now: number): void {
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
}

// ---- Helpers --------------------------------------------------------------

function isValidHex64(s: string): boolean {
  return /^[a-f0-9]{64}$/.test(s);
}

function constantTimeHexEquals(expectedHex: string, providedBuf: Buffer): boolean {
  const expectedBuf = Buffer.from(expectedHex, "hex");
  return expectedBuf.length === providedBuf.length
      && timingSafeEqual(expectedBuf, providedBuf);
}

// ---- Middleware ----------------------------------------------------------

interface WebhookRequest {
  rawBody: Buffer;  // captured BEFORE JSON parsing, e.g. via body-parser
                    // verify: (req, buf) => { req.rawBody = buf; }
  headers: {
    "x-webhook-timestamp": string | undefined; // unix seconds, digits only
    "x-webhook-event-id":  string | undefined;
    "x-signature-256":     string | undefined; // hex, optional "sha256=" prefix
  };
}

type MiddlewareResult =
  | { status: 200 }                       // verified, proceed to handler
  | { status: 401; reason: "missing_raw_body" | "missing_or_malformed_timestamp"
                    | "malformed_signature" | "stale_timestamp"
                    | "bad_signature" }
  | { status: 409; reason: "missing_event_id" | "duplicate_event" };

function verifyWebhook(secrets: Secrets): (req: WebhookRequest) => MiddlewareResult {
  return (req) => {

    // 1. Raw body must exist (captured pre-parse; HMAC is over exact bytes).
    if (!req.rawBody) {
      return { status: 401, reason: "missing_raw_body" };
    }

    // 2. Extract and validate headers.
    const tsHeader = req.headers["x-webhook-timestamp"];
    const eventId  = req.headers["x-webhook-event-id"];
    const provided = (req.headers["x-signature-256"] ?? "")
      .replace(/^sha256=/, "")
      .toLowerCase();

    if (!tsHeader || !/^\d+$/.test(tsHeader)) {
      return { status: 401, reason: "missing_or_malformed_timestamp" };
    }
    if (!isValidHex64(provided)) {
      return { status: 401, reason: "malformed_signature" };
    }
    if (!eventId) {
      return { status: 409, reason: "missing_event_id" };
    }

    // 3. Freshness: reject timestamps older than 5 minutes (and future-dated).
    const now = Date.now();
    const age = now - parseInt(tsHeader, 10) * 1000;
    if (age < 0 || age > TIMESTAMP_TOLERANCE_MS) {
      return { status: 401, reason: "stale_timestamp" };
    }

    // 4. Signature: HMAC-SHA256 over timestamp + "." + raw body.
    //    Accept EITHER the current or the previous secret (rotation).
    //    Build input via Buffer.concat — no string encoding round-trip.
    const signedInput = Buffer.concat([
      Buffer.from(tsHeader + "."),
      req.rawBody,
    ]);
    const providedBuf = Buffer.from(provided, "hex");

    let valid = false;
    for (const secret of [secrets.current, secrets.previous]) {
      if (secret === null) continue;
      const expected = createHmac("sha256", secret)
        .update(signedInput)
        .digest("hex");
      if (constantTimeHexEquals(expected, providedBuf)) {
        valid = true;
        break;
      }
    }

    if (!valid) {
      return { status: 401, reason: "bad_signature" };
    }

    // 5. Replay protection: reject repeated event IDs for 10 minutes.
    //    Checked AFTER signature verification so attackers cannot poison
    //    the cache with forged event IDs.
    pruneReplayCache(now);
    if (seenEvents.has(eventId)) {
      return { status: 409, reason: "duplicate_event" };
    }
    seenEvents.set(eventId, now + REPLAY_WINDOW_MS);

    // 6. Verified — proceed to handler.
    return { status: 200 };
  };
}

// ---- Wiring ---------------------------------------------------------------

const verify = verifyWebhook({
  current:  process.env.WEBHOOK_SECRET          ?? fail("WEBHOOK_SECRET required"),
  previous: process.env.WEBHOOK_SECRET_PREVIOUS ?? null,
});

// app.use("/webhooks", (req, res, next) => {
//   const result = verify(req);
//   if (result.status === 200) return next();
//   res.status(result.status).json({ error: result.reason });
// });
```

## Consolidated requirements checklist

| # | Requirement | Where enforced |
|---|---|---|
| 1 | HMAC-SHA256 over the **raw** request body | `req.rawBody` captured pre-parse; `Buffer.concat` input |
| 2 | Signed payload is `timestamp + "." + raw_body` | Step 4, `signedInput` |
| 3 | Reject timestamps older than **5 minutes** | Step 3, `TIMESTAMP_TOLERANCE_MS` (also rejects future-dated) |
| 4 | **Constant-time** comparison | `constantTimeHexEquals` via `timingSafeEqual` + length check |
| 5 | Accept **current or previous** secret (rotation) | Step 4, dual-secret loop; `previous` nullable |
| 6 | Reject repeated **event ID** for **10 minutes** | Step 5, `seenEvents` cache (window > tolerance, so replays can't outlive dedup) |
| 7 | **401** for bad signature or stale timestamp | Steps 1–4 |
| 8 | **409** for replay | Step 5 |

**Operational notes carried forward:**

- **Replay cache ordering** — dedup runs only after signature verification, preventing cache-poisoning DoS via forged event IDs.
- **Multi-instance deployments** — swap the in-memory `Map` for a shared store (`SET eventId 1 NX EX 600`); otherwise a replay can hit a different replica.
- **Rotation cutover** — deploy new secret as `current`, old as `previous`; after the provider's signing overlap window elapses, drop `previous`. Alert if `previous` stops authenticating requests so you know the cutover completed.
- **Retry semantics** — if the provider retries on any non-2xx, consider returning 200 for *verified* duplicates to prevent retry storms; 409 is kept here per spec.
- **Fail closed** — every failure path returns 401/409 and never reaches the handler; secrets come from environment config and are never logged.

# HMAC-SHA256 Webhook Signature Verification Middleware

Key points: you must hash the **raw, unparsed body** (JSON parsing/re-serialization changes bytes and breaks the signature), and compare digests with a **constant-time** function.

## Express (Node.js)

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // never hardcode

// Capture the raw body BEFORE any JSON parsing
app.use('/webhook', express.raw({ type: '*/*' }));

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // e.g. "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp');

  if (!signature || !timestamp) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Replay protection: reject stale timestamps (5 min window)
  const age = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (!Number.isFinite(age) || age > 300) {
    return res.status(401).json({ error: 'Stale or invalid timestamp' });
  }

  // Sign over timestamp + body so the timestamp is authenticated too
  const payload = `${timestamp}.${req.body.toString('utf8')}`;
  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(payload, 'utf8')
    .digest('hex');

  const provided = signature.replace(/^sha256=/, '');

  // Constant-time comparison to prevent timing attacks
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(provided, 'hex');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Parse JSON only after verification
  try {
    req.body = JSON.parse(req.body.toString('utf8'));
  } catch {
    return res.status(400).json({ error: 'Invalid JSON body' });
  }

  next();
}

app.post('/webhook', verifyWebhookSignature, (req, res) => {
  // req.body is now verified + parsed
  console.log('Verified event:', req.body);
  res.sendStatus(200);
});
```

## Security checklist

- **Raw body only** — `express.raw()` must run before `express.json()` on this route; never re-serialize parsed JSON to verify.
- **`crypto.timingSafeEqual`** — never use `===` on digests; check lengths first (it throws on mismatch).
- **Timestamp in the signed payload** — prevents replay of captured requests.
- **Secret from env/secret manager**, rotated periodically; use a dedicated secret per sender.
- **Fail closed** — any missing header, parse error, or mismatch → 401, no partial processing.
- **Body size limit** — e.g. `express.raw({ limit: '100kb' })` to bound HMAC input cost.
- **HTTPS only** — HMAC proves integrity, not confidentiality.

