BODY='{"event":"ping"}'
TS=$(date +%s)
SIG=$(printf '%s.%s' "$TS" "$BODY" | openssl dgst -sha256 -hmac "$SECRET" | cut -d' ' -f2)

curl -X POST localhost:3000/webhook \
  -H "Content-Type: application/json" \
  -H "X-Webhook-Timestamp: $TS" \
  -H "X-Webhook-Signature: sha256=$SIG" \
  --data-raw "$BODY"
```

Want a variant for a specific provider (GitHub, Stripe, Slack) or framework (Fastify, Flask)?

Both requirements are already baked into the sketch — here's the middleware tightened to make them explicit and self-contained:

```js
const crypto = require('crypto');
const express = require('express');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const MAX_TIMESTAMP_AGE_SECONDS = 300; // five minutes

const app = express();

// Raw body is mandatory — never verify against re-serialized JSON
app.use('/webhook', express.raw({ type: '*/*', limit: '100kb' }));

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get('X-Webhook-Signature'); // "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp');

  if (!signatureHeader || !timestamp || !/^\d+$/.test(timestamp)) {
    return res.status(401).json({ error: 'Missing or malformed signature headers' });
  }

  // 1) Freshness: reject timestamps older than five minutes (and future-dated)
  const nowSeconds = Math.floor(Date.now() / 1000);
  const timestampSeconds = Number(timestamp);
  if (nowSeconds - timestampSeconds > MAX_TIMESTAMP_AGE_SECONDS ||
      timestampSeconds > nowSeconds) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // 2) Signed payload is exactly: timestamp + '.' + raw_body
  const signedPayload = Buffer.concat([
    Buffer.from(`${timestamp}.`, 'utf8'),
    req.body, // raw bytes, untouched
  ]);

  const expectedDigest = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(signedPayload)
    .digest(); // keep as Buffer — no hex round-trip

  // 3) Constant-time comparison
  const providedDigest = Buffer.from(
    signatureHeader.replace(/^sha256=/, ''),
    'hex'
  );

  const valid =
    providedDigest.length === expectedDigest.length &&
    crypto.timingSafeEqual(providedDigest, expectedDigest);

  if (!valid) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Parse only after successful verification
  try {
    req.body = JSON.parse(req.body.toString('utf8'));
  } catch {
    return res.status(400).json({ error: 'Invalid JSON body' });
  }

  next();
}

app.post('/webhook', verifyWebhookSignature, (req, res) => {
  res.sendStatus(200);
});
```

Notes on the two requirements:

- **Payload construction** — `Buffer.concat([timestamp + '.', rawBody])` concatenates the raw bytes directly, avoiding any string encoding ambiguity between the timestamp and body.
- **Five-minute window** — checked *before* the HMAC computation so stale requests are rejected cheaply; future timestamps are also rejected to prevent an attacker from minting a signature valid indefinitely.
- **Constant-time comparison** — digests are compared as raw `Buffer`s via `crypto.timingSafeEqual`, with the length check short-circuiting first (required, since `timingSafeEqual` throws on unequal lengths). Comparing decoded bytes instead of hex strings also avoids case-normalization pitfalls (`AB` vs `ab`).

Here's the middleware extended with secret rotation support and event-ID replay protection:

```js
const crypto = require('crypto');
const express = require('express');

// Rotation: try current first, fall back to previous during the overlap window
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS, // remove after rotation grace period
].filter(Boolean);

const MAX_TIMESTAMP_AGE_SECONDS = 300;  // five minutes
const EVENT_ID_TTL_MS = 10 * 60 * 1000; // ten minutes

const app = express();
app.use('/webhook', express.raw({ type: '*/*', limit: '100kb' }));

// --- Replay cache: event ID -> expiry timestamp ---
const seenEventIds = new Map();

// Periodic sweep so the map doesn't grow unboundedly
setInterval(() => {
  const now = Date.now();
  for (const [id, expiresAt] of seenEventIds) {
    if (expiresAt <= now) seenEventIds.delete(id);
  }
}, 60_000).unref();

function isReplayedEventId(eventId) {
  const now = Date.now();
  const expiresAt = seenEventIds.get(eventId);
  if (expiresAt !== undefined && expiresAt > now) return true;
  // Record (or refresh) with a fresh 10-minute TTL
  seenEventIds.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get('X-Webhook-Signature'); // "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp');
  const eventId = req.get('X-Webhook-Event-Id');

  if (!signatureHeader || !timestamp || !/^\d+$/.test(timestamp) || !eventId) {
    return res.status(401).json({ error: 'Missing or malformed signature headers' });
  }

  // 1) Freshness: reject timestamps older than five minutes (and future-dated)
  const nowSeconds = Math.floor(Date.now() / 1000);
  const timestampSeconds = Number(timestamp);
  if (nowSeconds - timestampSeconds > MAX_TIMESTAMP_AGE_SECONDS ||
      timestampSeconds > nowSeconds) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // 2) Signed payload is exactly: timestamp + '.' + raw_body
  const signedPayload = Buffer.concat([
    Buffer.from(`${timestamp}.`, 'utf8'),
    req.body, // raw bytes, untouched
  ]);

  const providedDigest = Buffer.from(
    signatureHeader.replace(/^sha256=/, ''),
    'hex'
  );

  // 3) Accept a signature from EITHER the current or previous secret.
  //    Compute all candidates and OR the results — no early exit, so the
  //    response time doesn't reveal which secret matched (or that one did).
  let valid = providedDigest.length === 32; // SHA-256 digest length
  for (const secret of WEBHOOK_SECRETS) {
    const expectedDigest = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest();
    const matches =
      providedDigest.length === expectedDigest.length &&
      crypto.timingSafeEqual(providedDigest, expectedDigest);
    valid = valid || matches;
  }

  if (!valid) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // 4) Replay protection: reject an event ID seen within the last ten minutes.
  //    Checked AFTER signature verification so attackers can't probe/poison
  //    the cache with unauthenticated IDs.
  if (isReplayedEventId(eventId)) {
    return res.status(409).json({ error: 'Duplicate event ID' });
  }

  // Parse only after successful verification
  try {
    req.body = JSON.parse(req.body.toString('utf8'));
  } catch {
    return res.status(400).json({ error: 'Invalid JSON body' });
  }

  next();
}

app.post('/webhook', verifyWebhookSignature, (req, res) => {
  res.sendStatus(200);
});
```

Design notes:

- **Secret rotation** — both secrets are tried on every request and the results OR'd without short-circuiting, so timing doesn't leak whether the current or previous secret matched. Operationally: deploy with both set, rotate senders to the new secret, then unset `WEBHOOK_SECRET_PREVIOUS` after the grace period.
- **Replay cache ordering** — the event-ID check runs *after* signature verification. Otherwise an unauthenticated attacker could submit a victim's event ID with a garbage signature and poison the cache, causing the legitimate delivery to be rejected (a DoS vector).
- **Why both timestamp and event-ID checks** — the 5-minute timestamp window bounds how long a captured request stays valid; the 10-minute event-ID cache closes the gap *within* that window (an attacker replaying immediately) and also deduplicates legitimate sender retries.
- **409 for duplicates** — distinguishes replays from auth failures (401), which helps sender retry logic and your monitoring.
- **In-memory `Map` caveat** — fine for a single process. For multi-instance deployments, move the cache to Redis (`SET eventId 1 NX PX 600000` gives you atomic check-and-set with TTL in one operation), otherwise replays can hit a different instance.

```typescript
// ─── Configuration ──────────────────────────────────────────────────────────

const MAX_TIMESTAMP_AGE_SECONDS = 300;        // five minutes
const EVENT_ID_TTL_MS           = 10 * 60_000; // ten minutes
const SHA256_DIGEST_BYTES       = 32;

// Rotation: current first, previous kept during the overlap window
const WEBHOOK_SECRETS: Buffer[] = [
  env("WEBHOOK_SECRET_CURRENT"),
  env("WEBHOOK_SECRET_PREVIOUS"),  // remove after rotation grace period
].filter(isDefined).map(toUtf8Buffer);

// ─── Replay cache (single-process; use Redis SET NX PX for multi-instance) ──

const seenEventIds: Map<string, EpochMillis> = new Map();

every(60_000, () => {                      // periodic sweep, unref'd
  const now = Date.now();
  for (const [id, expiresAt] of seenEventIds) {
    if (expiresAt <= now) seenEventIds.delete(id);
  }
});

function isReplayedEventId(eventId: string): boolean {
  const now = Date.now();
  const expiresAt = seenEventIds.get(eventId);
  if (expiresAt !== undefined && expiresAt > now) return true;
  seenEventIds.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ─── Middleware ─────────────────────────────────────────────────────────────
// Precondition: route uses a RAW body parser (no JSON parsing before this).

function verifyWebhookSignature(req: Request, res: Response, next: Next): void {
  const signatureHeader = req.header("X-Webhook-Signature");  // "sha256=<hex>"
  const timestamp       = req.header("X-Webhook-Timestamp");
  const eventId         = req.header("X-Webhook-Event-Id");

  if (!signatureHeader || !timestamp || !/^\d+$/.test(timestamp) || !eventId) {
    return res.status(401).json({ error: "Missing or malformed signature headers" });
  }

  // 1) Freshness — stale or future-dated → 401
  const nowSeconds       = floor(Date.now() / 1000);
  const timestampSeconds = parseInt(timestamp, 10);
  if (nowSeconds - timestampSeconds > MAX_TIMESTAMP_AGE_SECONDS ||
      timestampSeconds > nowSeconds) {
    return res.status(401).json({ error: "Timestamp outside allowed window" });
  }

  // 2) Signed payload is exactly: timestamp + "." + raw_body
  const signedPayload: Buffer = concat([
    utf8Buffer(timestamp + "."),
    req.rawBody,               // raw bytes, untouched
  ]);

  const providedDigest: Buffer = hexToBuffer(
    stripPrefix(signatureHeader, "sha256=")
  );

  // 3) Accept EITHER current or previous secret — constant-time, no early
  //    exit, so timing doesn't reveal which secret matched (or that one did)
  let valid: boolean = providedDigest.length === SHA256_DIGEST_BYTES;
  for (const secret of WEBHOOK_SECRETS) {
    const expectedDigest: Buffer = hmacSha256(secret, signedPayload);
    const matches: boolean =
      providedDigest.length === expectedDigest.length &&
      timingSafeEqual(providedDigest, expectedDigest);
    valid = valid || matches;
  }

  if (!valid) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  // 4) Replay protection — AFTER signature check, so unauthenticated
  //    requests can't poison the cache with a victim's event ID → 409
  if (isReplayedEventId(eventId)) {
    return res.status(409).json({ error: "Duplicate event ID" });
  }

  // 5) Parse only after successful verification
  try {
    req.body = JSON.parse(req.rawBody.toString("utf8"));
  } catch {
    return res.status(400).json({ error: "Invalid JSON body" });
  }

  next();
}

// ─── Route ──────────────────────────────────────────────────────────────────

app.post("/webhook", rawBodyParser({ limit: "100kb" }), verifyWebhookSignature,
  (req: Request, res: Response) => {
    res.sendStatus(200);
  }
);
```

**Behavior summary**

| Condition | Status |
|---|---|
| Missing/malformed headers | 401 |
| Timestamp stale (> 5 min) or future-dated | 401 |
| Signature matches neither current nor previous secret | 401 |
| Valid signature, but event ID seen within 10 min | 409 |
| Valid signature, fresh timestamp, new event ID, malformed JSON | 400 |
| All checks pass | → handler |

**Invariants preserved**

- Verification always runs on the **raw body**; the signed payload is exactly `timestamp + "." + raw_body`.
- All digest comparisons use `timingSafeEqual` with a length pre-check; the multi-secret loop never short-circuits.
- The replay cache is only written to **after** authentication succeeds.
- For multi-instance deployments, replace the `Map` with an atomic `SET eventId 1 NX PX 600000` in Redis.

# HMAC-SHA256 Webhook Signature Verification Middleware

Key points: you must hash the **raw, unparsed body** (JSON parsing/serialization changes bytes and breaks the signature), and compare digests with a **constant-time** comparison.

## Express (Node.js)

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;

// Capture the raw body BEFORE any JSON parsing
app.use('/webhooks', express.raw({ type: '*/*' }));

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Webhook-Signature'); // e.g. "sha256=<hex>"
  const timestamp = req.get('X-Webhook-Timestamp');

  if (!signature || !timestamp) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Replay protection: reject stale timestamps (5 min window)
  const age = Math.abs(Date.now() - Number(timestamp) * 1000);
  if (!Number.isFinite(age) || age > 5 * 60 * 1000) {
    return res.status(401).json({ error: 'Stale or invalid timestamp' });
  }

  // Sign over "timestamp.body" so the timestamp is authenticated too
  const payload = `${timestamp}.${req.body.toString('utf8')}`;
  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(payload)
    .digest('hex');

  const provided = signature.replace(/^sha256=/, '');

  // Constant-time comparison — never use ===
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(provided, 'hex');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Parse the body only after verification
  req.body = JSON.parse(req.body.toString('utf8'));
  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  // req.body is now verified and parsed
  res.status(200).json({ received: true });
});
```

## Why these choices matter

1. **Raw body**: `express.json()` would consume and re-serialize the body; whitespace/key-order differences change the digest. `express.raw()` gives you the exact bytes the sender signed.
2. **`timingSafeEqual`**: a plain string comparison leaks length/prefix info via timing side channels.
3. **Timestamp in the signed payload**: prevents replay attacks — an attacker can't reuse a captured valid signature later.
4. **Secret from env**: never hardcode; rotate periodically.
5. **Fail closed**: any missing header, parse error, or mismatch → 401, no processing.

## Common provider variants

- **Stripe**: signature header contains `t=...,v1=...`; signed payload is `t.rawBody`. Use their SDK (`stripe.webhooks.constructEvent`) rather than hand-rolling.
- **GitHub**: `X-Hub-Signature-256: sha256=<hex>` over the raw body only.
- **Slack**: `X-Slack-Signature: v0=<hex>` over `v0:timestamp:rawBody`.

Adapt the header names and payload format to your provider, but keep the raw-body + timing-safe-compare + replay-window structure.

# HMAC-SHA256 Webhook Signature Verification Middleware

Key requirements: use the **raw** body (not parsed JSON), compare with a **timing-safe** function, and reject on any mismatch.

## Express.js example

```js
const crypto = require('crypto');
const express = require('express');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const SIGNATURE_HEADER = 'x-webhook-signature'; // e.g. "sha256=<hex>"

function verifyWebhookSignature(req, res, next) {
  const signature = req.get(SIGNATURE_HEADER);
  if (!signature || !req.rawBody) {
    return res.status(401).json({ error: 'Missing signature or body' });
  }

  const expected =
    'sha256=' +
    crypto.createHmac('sha256', WEBHOOK_SECRET)
          .update(req.rawBody) // Buffer of the exact bytes received
          .digest('hex');

  const a = Buffer.from(signature);
  const b = Buffer.from(expected);

  // Lengths must match before timingSafeEqual (it throws otherwise)
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

const app = express();

// Capture the raw body BEFORE any JSON parsing transforms it
app.use(express.json({
  verify: (req, res, buf) => { req.rawBody = buf; }
}));

app.post('/webhooks/payments', verifyWebhookSignature, (req, res) => {
  // Signature verified — safe to process req.body
  res.sendStatus(200);
});
```

## Why these details matter

1. **Raw body**: HMAC is computed over exact bytes. `JSON.parse` → `JSON.stringify` can reorder keys or change whitespace, breaking the signature. The `verify` callback in `express.json()` captures the buffer before parsing.
2. **`crypto.timingSafeEqual`**: prevents timing attacks that could leak the expected signature byte-by-byte. Never use `===`.
3. **Length check first**: `timingSafeEqual` throws on unequal-length buffers.
4. **Secret from env**: never hardcode; rotate periodically.

## Optional hardening

```js
// Replay protection: reject stale timestamps (if provider sends one)
const ts = Number(req.get('x-webhook-timestamp'));
if (!ts || Math.abs(Date.now() / 1000 - ts) > 300) {
  return res.status(401).json({ error: 'Stale or missing timestamp' });
}
// Then sign over `${ts}.${rawBody}` per the provider's scheme
```

Also consider: rejecting requests without `Content-Type: application/json`, logging failures without logging the signature itself, and rate-limiting the endpoint.

# Updated Middleware: Timestamp-Prefixed Signature + Replay Protection

The HMAC is now computed over `timestamp + '.' + raw_body`, with a 5-minute freshness window and constant-time comparison throughout.

```js
const crypto = require('crypto');
const express = require('express');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const SIGNATURE_HEADER = 'x-webhook-signature';   // "sha256=<hex>"
const TIMESTAMP_HEADER = 'x-webhook-timestamp';   // Unix seconds
const MAX_AGE_SECONDS = 300;                       // 5 minutes

function verifyWebhookSignature(req, res, next) {
  const signature = req.get(SIGNATURE_HEADER);
  const timestamp = req.get(TIMESTAMP_HEADER);

  if (!signature || !timestamp || !req.rawBody) {
    return res.status(401).json({ error: 'Missing signature, timestamp, or body' });
  }

  // --- Replay protection: reject stale or future-skewed timestamps ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) {
    return res.status(401).json({ error: 'Malformed timestamp' });
  }
  const ageSeconds = Math.abs(Date.now() / 1000 - ts);
  if (ageSeconds > MAX_AGE_SECONDS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // --- Recompute HMAC over "timestamp.raw_body" ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + '.', 'utf8'),
    req.rawBody, // Buffer of exact bytes received
  ]);

  const expected =
    'sha256=' +
    crypto.createHmac('sha256', WEBHOOK_SECRET)
          .update(signedPayload)
          .digest('hex');

  // --- Constant-time comparison ---
  const a = Buffer.from(signature, 'utf8');
  const b = Buffer.from(expected, 'utf8');

  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

const app = express();

// Capture the raw body BEFORE JSON parsing alters the bytes
app.use(express.json({
  verify: (req, res, buf) => { req.rawBody = buf; }
}));

app.post('/webhooks/payments', verifyWebhookSignature, (req, res) => {
  // Signature valid AND fresh — safe to process req.body
  res.sendStatus(200);
});
```

## Security notes

1. **Signed payload construction**: the timestamp string is taken *verbatim from the header* (not the parsed number) so the signed bytes match exactly what the sender signed — `Buffer.from(timestamp + '.')` avoids normalization issues like `1700000000.0` vs `1700000000`.
2. **Timestamp validated before HMAC**: cheap rejection of stale requests; the signature check still authoritatively binds the timestamp to the payload, so an attacker can't swap in a fresh timestamp without invalidating the signature.
3. **`Math.abs` window**: rejects both old timestamps *and* far-future ones (which could be stockpiled for later replay). Assumes server clock is synced via NTP.
4. **Constant-time comparison**: `crypto.timingSafeEqual` with a length pre-check (it throws on mismatched lengths). Never `===`.
5. **Raw body preserved**: captured in `express.json`'s `verify` callback before parsing; HMAC runs over exact received bytes.

## Optional additions

- **Nonce/idempotency store**: the 5-minute window still permits replay *within* the window. Record seen signature hashes (or event IDs) in Redis with a 5-minute TTL and reject duplicates.
- **Error responses stay generic**: don't reveal *which* check failed to the caller in production (log the detail server-side instead).

# Updated Middleware: Secret Rotation + Event ID Deduplication

Two additions: verify against **current or previous** secret (both in constant time), and reject **repeated event IDs** within a 10-minute window.

```js
const crypto = require('crypto');
const express = require('express');
const Redis = require('ioredis');

const redis = new Redis(process.env.REDIS_URL);

// Rotation: index 0 = current, index 1 = previous. Update both on rotation.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

const SIGNATURE_HEADER = 'x-webhook-signature';   // "sha256=<hex>"
const TIMESTAMP_HEADER = 'x-webhook-timestamp';   // Unix seconds
const EVENT_ID_HEADER  = 'x-webhook-event-id';    // unique per event
const MAX_AGE_SECONDS = 300;                       // 5 min timestamp window
const EVENT_ID_TTL_SECONDS = 600;                  // 10 min dedup window

async function verifyWebhookSignature(req, res, next) {
  const signature = req.get(SIGNATURE_HEADER);
  const timestamp = req.get(TIMESTAMP_HEADER);
  const eventId   = req.get(EVENT_ID_HEADER);

  if (!signature || !timestamp || !eventId || !req.rawBody) {
    return res.status(401).json({ error: 'Missing required headers or body' });
  }

  // --- Replay protection: timestamp freshness ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) {
    return res.status(401).json({ error: 'Malformed timestamp' });
  }
  if (Math.abs(Date.now() / 1000 - ts) > MAX_AGE_SECONDS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // --- Recompute HMAC over "timestamp.raw_body" for EACH candidate secret ---
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + '.', 'utf8'),
    req.rawBody,
  ]);

  const provided = Buffer.from(signature, 'utf8');

  // Constant-time compare against every secret; never short-circuit on match
  let matched = false;
  for (const secret of WEBHOOK_SECRETS) {
    const expected = Buffer.from(
      'sha256=' +
      crypto.createHmac('sha256', secret).update(signedPayload).digest('hex'),
      'utf8'
    );
    if (provided.length === expected.length &&
        crypto.timingSafeEqual(provided, expected)) {
      matched = true; // record, but keep iterating to avoid timing oracle
    }
  }

  if (!matched) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // --- Deduplication: reject repeated event IDs for 10 minutes ---
  // SET NX is atomic: only the first delivery of this event ID succeeds.
  // Key is namespaced; value stores nothing sensitive.
  const dedupKey = `webhook:event:${eventId}`;
  const wasNew = await redis.set(dedupKey, '1', 'EX', EVENT_ID_TTL_SECONDS, 'NX');
  if (wasNew === null) {
    return res.status(409).json({ error: 'Duplicate event' });
  }

  next();
}

const app = express();

// Capture the raw body BEFORE JSON parsing alters the bytes
app.use(express.json({
  verify: (req, res, buf) => { req.rawBody = buf; }
}));

app.post('/webhooks/payments', verifyWebhookSignature, (req, res) => {
  // Signature valid (current or previous secret), timestamp fresh,
  // and event ID not seen in the last 10 minutes.
  res.sendStatus(200);
});
```

## Security notes

1. **No short-circuit on secret match**: the loop always evaluates *all* candidate secrets with `timingSafeEqual`, so response timing doesn't reveal whether the current or previous secret matched (or how many secrets are configured).
2. **Rotation procedure**: on rotate, set `WEBHOOK_SECRET_PREVIOUS = <old current>`, `WEBHOOK_SECRET_CURRENT = <new>`, redeploy. After the previous secret's grace period (at least the sender's cutover time + 5 min), remove it from the list.
3. **Atomic dedup**: `SET ... NX EX 600` is a single atomic operation — concurrent duplicate deliveries can't both pass. The 10-minute TTL intentionally exceeds the 5-minute timestamp window, so any replayable request is guaranteed to be caught.
4. **Ordering matters**: dedup runs *after* signature verification, so unauthenticated callers can't poison the dedup store with arbitrary event IDs to cause denial of service against legitimate events.
5. **Event ID key hygiene**: IDs are namespaced (`webhook:event:`) and only the ID is stored — no payload or secret material in Redis. Consider hashing the ID if it's sensitive.
6. **409 vs 401**: duplicates return `409` so legitimate senders with retry logic can distinguish "already processed" from "unauthorized". If your provider retries on non-2xx, return `200` with `{ deduplicated: true }` instead.

## Caveats

- **Multi-instance deployments require Redis** (or another shared store) — an in-memory `Map` would let duplicates slip through different instances. If you're single-instance, a `Map` with expiry works, but Redis is shown as the safe default.
- **Handler idempotency still recommended**: dedup has a 10-minute horizon; a provider retry after that window would re-process. Make the downstream handler idempotent on the event ID as defense in depth.

# Final Middleware: TypeScript Pseudocode

Consolidates all accumulated requirements: raw-body HMAC-SHA256 over `timestamp.raw_body`, 5-minute freshness window, current-or-previous secret rotation with constant-time comparison, and 10-minute event-ID deduplication.

```typescript
import crypto from 'crypto';
import { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

// ---------- Configuration ----------
const redis = new Redis(process.env.REDIS_URL!);

// Rotation: index 0 = current, index 1 = previous. Update both on rotation.
const WEBHOOK_SECRETS: string[] = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter((s): s is string => Boolean(s));

const SIGNATURE_HEADER = 'x-webhook-signature';   // "sha256=<hex>"
const TIMESTAMP_HEADER = 'x-webhook-timestamp';   // Unix seconds
const EVENT_ID_HEADER  = 'x-webhook-event-id';    // unique per event

const MAX_AGE_SECONDS      = 300;  // 5-minute timestamp window
const EVENT_ID_TTL_SECONDS = 600;  // 10-minute dedup window

// Augmented request: raw body captured before JSON parsing
interface RawRequest extends Request {
  rawBody?: Buffer;
}

// ---------- Middleware ----------
async function verifyWebhookSignature(
  req: RawRequest,
  res: Response,
  next: NextFunction
): Promise<void> {
  const signature = req.get(SIGNATURE_HEADER);
  const timestamp = req.get(TIMESTAMP_HEADER);
  const eventId   = req.get(EVENT_ID_HEADER);

  if (!signature || !timestamp || !eventId || !req.rawBody) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  // --- 1. Timestamp freshness (401 on failure) ---
  const ts = Number(timestamp);
  if (!Number.isFinite(ts) ||
      Math.abs(Date.now() / 1000 - ts) > MAX_AGE_SECONDS) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  // --- 2. HMAC-SHA256 over "timestamp.raw_body" (401 on failure) ---
  const signedPayload: Buffer = Buffer.concat([
    Buffer.from(timestamp + '.', 'utf8'),
    req.rawBody, // exact bytes as received
  ]);

  const provided: Buffer = Buffer.from(signature, 'utf8');

  // Evaluate ALL candidate secrets in constant time; never short-circuit,
  // so timing doesn't reveal which secret matched or how many exist.
  let matched = false;
  for (const secret of WEBHOOK_SECRETS) {
    const expected: Buffer = Buffer.from(
      'sha256=' +
      crypto.createHmac('sha256', secret).update(signedPayload).digest('hex'),
      'utf8'
    );
    if (provided.length === expected.length &&
        crypto.timingSafeEqual(provided, expected)) {
      matched = true;
    }
  }

  if (!matched) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  // --- 3. Replay deduplication (409 on repeat) ---
  // Runs AFTER auth so attackers can't poison the dedup store.
  // SET NX EX is atomic: concurrent duplicates cannot both pass.
  const dedupKey = `webhook:event:${eventId}`;
  const wasNew = await redis.set(
    dedupKey, '1', 'EX', EVENT_ID_TTL_SECONDS, 'NX'
  );
  if (wasNew === null) {
    res.status(409).json({ error: 'Duplicate event' });
    return;
  }

  next();
}

// ---------- App wiring ----------
// Capture raw body BEFORE JSON parsing alters the bytes.
app.use(express.json({
  verify: (req: RawRequest, _res, buf: Buffer) => { req.rawBody = buf; },
}));

app.post('/webhooks/payments', verifyWebhookSignature, (req, res) => {
  // Authenticated, fresh, and not a replay — safe to process.
  res.sendStatus(200);
});
```

## Behavior summary

| Check | Failure response | Notes |
|---|---|---|
| Missing headers/body | `401` | Treated as unauthenticated |
| Timestamp malformed or >5 min skew (either direction) | `401` | `Math.abs` also rejects far-future timestamps |
| Signature matches neither current nor previous secret | `401` | All secrets compared via `timingSafeEqual`, no early exit |
| Event ID seen within last 10 minutes | `409` | Atomic `SET NX EX`; checked only after auth passes |
| All pass | `next()` | Handler should still be idempotent as defense in depth |

## Standing security properties

- **Raw body**: HMAC input is the exact received bytes; JSON parsing never affects verification.
- **Constant-time comparison**: `crypto.timingSafeEqual` with length pre-check; no `===` on secrets or signatures.
- **Timestamp bound to payload**: the signed `timestamp.raw_body` construction means a fresh timestamp can't be swapped onto a stale signature.
- **Dedup TTL (10 min) > timestamp window (5 min)**: any replayable request is guaranteed to be caught by the dedup store.
- **Generic error bodies**: failure details are logged server-side only, never leaked to the caller.

Here's a sketch (Node/Express) — the key points are: use the **raw** body (not parsed JSON), compare with a **timing-safe** function, and verify a timestamp to prevent replay.

```js
const crypto = require('crypto');

// Express config: capture raw body BEFORE json parser
// app.use(express.json({ verify: (req, res, buf) => { req.rawBody = buf; } }));

function verifyWebhookSignature(secret, toleranceSeconds = 300) {
  return (req, res, next) => {
    const sigHeader = req.get('X-Signature'); // e.g. "t=1712345678,v1=5f8a..."
    if (!sigHeader) return res.status(401).json({ error: 'missing signature' });

    const parts = Object.fromEntries(
      sigHeader.split(',').map((kv) => kv.split('='))
    );
    const timestamp = parts.t;
    const receivedSig = parts.v1;

    if (!timestamp || !receivedSig) {
      return res.status(401).json({ error: 'malformed signature header' });
    }

    // 1. Replay protection
    const age = Math.abs(Date.now() / 1000 - Number(timestamp));
    if (!Number.isFinite(age) || age > toleranceSeconds) {
      return res.status(401).json({ error: 'timestamp outside tolerance' });
    }

    // 2. Compute expected signature over "timestamp.rawBody"
    const payload = Buffer.concat([
      Buffer.from(`${timestamp}.`),
      req.rawBody, // raw bytes exactly as received
    ]);
    const expected = crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');

    // 3. Timing-safe comparison (also guard length mismatch)
    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(receivedSig, 'utf8');
    const valid =
      a.length === b.length && crypto.timingSafeEqual(a, b);

    if (!valid) return res.status(401).json({ error: 'invalid signature' });

    next();
  };
}

// Usage:
// app.post('/webhooks/provider', verifyWebhookSignature(process.env.WEBHOOK_SECRET), handler)
```

Notes:

- **Raw body is essential** — signing the re-serialized parsed JSON will fail because key order/whitespace may differ. The `verify` callback above preserves the exact bytes.
- **Constant-time compare** (`crypto.timingSafeEqual`) prevents timing attacks that could recover the signature byte-by-byte.
- **Timestamp scheme** (`t` + `v1`) follows the common Stripe-style pattern; if your provider signs only the body, drop the timestamp prefix and the replay check (or add your own idempotency/dedup layer).
- Keep the secret in env/config, never in code, and use a dedicated secret per webhook endpoint.
- Return `401` without detail on failure; don't log the signature or body at error level (may contain sensitive payload data).

That matches the sketch — here's the tightened version locking in those exact requirements:

```js
const crypto = require('crypto');

