```javascript
const crypto = require("crypto");

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const MAX_AGE_SECONDS = 300; // reject timestamps older than 5 minutes

function verifySignature(rawBody, signatureHeader, secret, now = Date.now() / 1000) {
  if (typeof signatureHeader !== "string") return false;

  // Header format: t=<unix_seconds>,v1=<hex_hmac>[,v1=<hex_hmac>...]
  const parts = signatureHeader.split(",").map((p) => p.split("="));
  const timestamp = parts.find(([k]) => k === "t")?.[1];
  const provided = parts.filter(([k]) => k === "v1").map(([, v]) => v);

  if (!timestamp || provided.length === 0) return false;

  // Timestamp must be a plain integer
  if (!/^\d+$/.test(timestamp)) return false;
  const ts = Number(timestamp);

  // Reject timestamps older than 5 minutes (and from the future)
  const age = now - ts;
  if (age > MAX_AGE_SECONDS || age < -MAX_AGE_SECONDS) return false;

  // Signed payload: `${timestamp}.${rawBody}` — raw bytes, not re-serialized JSON
  const expected = crypto
    .createHmac("sha256", secret)
    .update(`${timestamp}.${rawBody}`)
    .digest("hex");

  const expectedBuf = Buffer.from(expected, "utf8");

  // Constant-time comparison against each provided signature
  return provided.some((sig) => {
    if (typeof sig !== "string") return false;
    const sigBuf = Buffer.from(sig, "utf8");
    return (
      sigBuf.length === expectedBuf.length &&
      crypto.timingSafeEqual(sigBuf, expectedBuf)
    );
  });
}

function webhookMiddleware(req, res, next) {
  // Raw body captured pre-parse:
  // express.json({ verify: (req, _res, buf) => { req.rawBody = buf; } })
  const rawBody = req.rawBody;
  if (!Buffer.isBuffer(rawBody) || rawBody.length === 0) {
    return res.status(400).json({ error: "Missing body" });
  }

  if (!verifySignature(rawBody, req.get("X-Signature"), WEBHOOK_SECRET)) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  try {
    req.body = JSON.parse(rawBody.toString("utf8"));
  } catch {
    return res.status(400).json({ error: "Invalid JSON" });
  }

  next();
}
```

Notes on the details you specified:

- **Signed payload** is exactly `` `${timestamp}.${rawBody}` `` — the timestamp string as it appears in the header, concatenated with the raw request bytes.
- **Five-minute window**: `age > 300` rejects old timestamps; I also reject future timestamps beyond the same tolerance, since a far-future `t` would otherwise extend the replay window indefinitely.
- **Constant-time**: `crypto.timingSafeEqual` with a length pre-check (it throws on length mismatch). Comparing against every `v1` value supports secret rotation without widening the timing surface.

One caveat: the 5-minute window still permits replays *within* it. If your events carry unique IDs, dedupe on those (e.g., Redis `SET NX` with a 5-minute TTL) for full replay protection.

Here's the updated middleware with secret rotation and event-ID dedupe:

```javascript
const crypto = require("crypto");
const { Redis } = require("ioredis");

// Ordered: [current, previous]. Current is tried first; previous accepted
// only during rotation overlap.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

const MAX_AGE_SECONDS = 300;      // timestamp window
const EVENT_TTL_SECONDS = 600;    // 10-minute event-ID dedupe

const redis = new Redis(process.env.REDIS_URL);

function computeExpected(timestamp, rawBody, secret) {
  return crypto
    .createHmac("sha256", secret)
    .update(`${timestamp}.${rawBody}`)
    .digest("hex");
}

function verifySignature(rawBody, signatureHeader, secrets, now = Date.now() / 1000) {
  if (typeof signatureHeader !== "string") return false;

  const parts = signatureHeader.split(",").map((p) => p.split("="));
  const timestamp = parts.find(([k]) => k === "t")?.[1];
  const provided = parts.filter(([k]) => k === "v1").map(([, v]) => v);

  if (!timestamp || provided.length === 0) return false;
  if (!/^\d+$/.test(timestamp)) return false;

  const age = now - Number(timestamp);
  if (age > MAX_AGE_SECONDS || age < -MAX_AGE_SECONDS) return false;

  const providedBufs = provided
    .filter((s) => typeof s === "string")
    .map((s) => Buffer.from(s, "utf8"));

  // Try each secret; accept if any matches any provided signature.
  // All comparisons are constant-time.
  return secrets.some((secret) => {
    const expectedBuf = Buffer.from(computeExpected(timestamp, rawBody, secret), "utf8");
    return providedBufs.some(
      (sigBuf) =>
        sigBuf.length === expectedBuf.length &&
        crypto.timingSafeEqual(sigBuf, expectedBuf)
    );
  });
}

// Returns true if the event ID is fresh; false if it was seen within 10 min.
async function claimEventId(eventId) {
  // SET key 1 NX EX 600 — atomic check-and-set
  const result = await redis.set(
    `webhook:event:${eventId}`,
    "1",
    "EX",
    EVENT_TTL_SECONDS,
    "NX"
  );
  return result === "OK";
}

function extractEventId(body) {
  // Adjust to your provider's schema
  return typeof body?.id === "string" && body.id.length > 0 && body.id.length <= 256
    ? body.id
    : null;
}

async function webhookMiddleware(req, res, next) {
  const rawBody = req.rawBody;
  if (!Buffer.isBuffer(rawBody) || rawBody.length === 0) {
    return res.status(400).json({ error: "Missing body" });
  }

  if (!verifySignature(rawBody, req.get("X-Signature"), WEBHOOK_SECRETS)) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  let body;
  try {
    body = JSON.parse(rawBody.toString("utf8"));
  } catch {
    return res.status(400).json({ error: "Invalid JSON" });
  }

  const eventId = extractEventId(body);
  if (!eventId) {
    return res.status(400).json({ error: "Missing event ID" });
  }

  // Dedupe AFTER signature verification so only authenticated
  // requests can consume dedupe state.
  let fresh;
  try {
    fresh = await claimEventId(eventId);
  } catch (err) {
    // Fail closed: if Redis is down, don't process unverified-duplicate traffic
    return res.status(503).json({ error: "Dedupe store unavailable" });
  }
  if (!fresh) {
    return res.status(200).json({ status: "duplicate" }); // ack, don't reprocess
  }

  req.body = body;
  next();
}
```

Design decisions worth noting:

- **Secret rotation**: `WEBHOOK_SECRETS` is ordered `[current, previous]`. Senders sign with the current secret; during rotation overlap, payloads signed with the previous one still verify. Once all senders have switched, drop the previous secret from config. Never accept more than two — an unbounded list keeps old leaked secrets valid forever.
- **Dedupe ordering**: the event-ID check runs *after* signature verification. Otherwise unauthenticated requests could pollute or probe the dedupe store.
- **Atomic claim**: `SET NX EX 600` is a single atomic operation, so concurrent deliveries of the same event can't both pass. The 10-minute TTL comfortably exceeds the 5-minute signature window, so any replay that passes the timestamp check is still caught by the dedupe.
- **Duplicates get a 200**: providers typically retry on non-2xx, so returning success for a duplicate prevents retry storms while skipping reprocessing.
- **Fail closed on Redis outage**: a 503 makes the provider retry later rather than risking double-processing.

One caveat: if your provider doesn't guarantee at-least-once delivery with stable event IDs, verify the ID field is attacker-controlled-safe — the length cap above prevents using dedupe keys as a memory/DoS vector.

```typescript
// webhook.ts — HMAC-SHA256 webhook verification middleware (TypeScript-style pseudocode)

import crypto from "crypto";
import type { Request, Response, NextFunction, RequestHandler } from "express";
import type Redis from "ioredis";

// ---------- Configuration ----------

interface Config {
  // Ordered [current, previous]; previous accepted only during rotation overlap.
  secrets: string[];
  maxAgeSeconds: number;      // timestamp tolerance (300 = 5 minutes)
  eventTtlSeconds: number;    // replay-dedupe TTL (600 = 10 minutes)
  redis: Redis;
}

const DEFAULTS = {
  maxAgeSeconds: 300,
  eventTtlSeconds: 600,
};

// ---------- Types ----------

interface ParsedSignatureHeader {
  timestamp: string;
  signatures: string[];
}

type VerifyResult =
  | { ok: true }
  | { ok: false; reason: "malformed_header" | "stale_timestamp" | "bad_signature" };

// ---------- Signature verification ----------

function parseSignatureHeader(header: unknown): ParsedSignatureHeader | null {
  if (typeof header !== "string") return null;

  const parts = header.split(",").map((p) => p.split("="));
  const timestamp = parts.find(([k]) => k === "t")?.[1];
  const signatures = parts.filter(([k]) => k === "v1").map(([, v]) => v);

  if (!timestamp || signatures.length === 0) return null;
  if (!/^\d+$/.test(timestamp)) return null; // plain integer only

  return { timestamp, signatures };
}

function computeExpectedMac(timestamp: string, rawBody: Buffer, secret: string): Buffer {
  // Signed payload is exactly `${timestamp}.${rawBody}` — raw bytes, never re-serialized JSON.
  return crypto
    .createHmac("sha256", secret)
    .update(`${timestamp}.${rawBody}`)
    .digest();
}

function constantTimeEqual(a: Buffer, b: Buffer): boolean {
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function verifySignature(
  rawBody: Buffer,
  header: unknown,
  secrets: string[],
  nowSeconds: number,
  maxAgeSeconds: number,
): VerifyResult {
  const parsed = parseSignatureHeader(header);
  if (!parsed) return { ok: false, reason: "malformed_header" };

  const ts = Number(parsed.timestamp);

  // Reject timestamps older than 5 minutes — and from the future,
  // so a far-future `t` can't extend the replay window.
  const age = nowSeconds - ts;
  if (age > maxAgeSeconds || age < -maxAgeSeconds) {
    return { ok: false, reason: "stale_timestamp" };
  }

  const providedBufs = parsed.signatures
    .filter((s) => typeof s === "string")
    .map((s) => Buffer.from(s, "utf8"));

  // Accept if any provided signature matches under the current OR previous secret.
  // Every comparison is constant-time.
  for (const secret of secrets) {
    const expected = computeExpectedMac(parsed.timestamp, rawBody, secret);
    for (const sigBuf of providedBufs) {
      if (constantTimeEqual(sigBuf, expected)) return { ok: true };
    }
  }

  return { ok: false, reason: "bad_signature" };
}

// ---------- Replay protection ----------

/**
 * Atomically claims an event ID. Returns true if fresh, false if it was
 * seen within the TTL. Uses SET NX EX — a single atomic operation, so
 * concurrent deliveries of the same event cannot both pass.
 */
async function claimEventId(redis: Redis, eventId: string, ttlSeconds: number): Promise<boolean> {
  const result = await redis.set(
    `webhook:event:${eventId}`,
    "1",
    "EX",
    ttlSeconds,
    "NX",
  );
  return result === "OK";
}

function extractEventId(body: unknown): string | null {
  // Adjust to your provider's schema. Cap length to bound key size.
  const id = (body as { id?: unknown } | null)?.id;
  return typeof id === "string" && id.length > 0 && id.length <= 256 ? id : null;
}

// ---------- Middleware ----------

function webhookMiddleware(config: Config): RequestHandler {
  const { secrets, redis } = config;
  const maxAgeSeconds = config.maxAgeSeconds ?? DEFAULTS.maxAgeSeconds;
  const eventTtlSeconds = config.eventTtlSeconds ?? DEFAULTS.eventTtlSeconds;

  if (secrets.length === 0 || secrets.length > 2) {
    throw new Error("Provide exactly one or two secrets: [current, previous].");
  }

  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    // Raw body must be captured pre-parse, e.g.:
    //   express.json({ verify: (req, _res, buf) => { req.rawBody = buf; } })
    const rawBody = req.rawBody as Buffer | undefined;
    if (!Buffer.isBuffer(rawBody) || rawBody.length === 0) {
      res.status(400).json({ error: "Missing body" });
      return;
    }

    // 1. Signature + timestamp verification
    const result = verifySignature(
      rawBody,
      req.get("X-Signature"),
      secrets,
      Date.now() / 1000,
      maxAgeSeconds,
    );
    if (!result.ok) {
      // 401 for bad signature OR stale timestamp — generic, no reason leaked
      res.status(401).json({ error: "Invalid signature" });
      return;
    }

    // 2. Parse only after authentication
    let body: unknown;
    try {
      body = JSON.parse(rawBody.toString("utf8"));
    } catch {
      res.status(400).json({ error: "Invalid JSON" });
      return;
    }

    // 3. Replay protection — AFTER signature verification, so only
    //    authenticated requests can consume dedupe state.
    const eventId = extractEventId(body);
    if (!eventId) {
      res.status(400).json({ error: "Missing event ID" });
      return;
    }

    let fresh: boolean;
    try {
      fresh = await claimEventId(redis, eventId, eventTtlSeconds);
    } catch {
      // Fail closed: dedupe store down → 503 so the provider retries later
      res.status(503).json({ error: "Dedupe store unavailable" });
      return;
    }
    if (!fresh) {
      // 409 for a replay within the 10-minute window
      res.status(409).json({ error: "Duplicate event" });
      return;
    }

    req.body = body;
    next();
  };
}

export { webhookMiddleware };
export type { Config };
```

Behavior summary:

| Condition | Status |
|---|---|
| Missing/malformed signature header, HMAC mismatch | **401** |
| Timestamp older than 5 min (or too far in the future) | **401** |
| Event ID seen within last 10 min | **409** |
| Missing body / bad JSON / missing event ID | **400** |
| Redis unavailable | **503** (fail closed) |

Notes:

- **401 vs 409**: both failure classes under 401 return the same generic body, so an attacker can't distinguish a stale timestamp from a wrong MAC. The 409 is only reachable by a request that already passed signature verification — safe to be specific there.
- **Rotation**: exactly `[current, previous]` is enforced at startup; the previous secret is dropped once all senders have migrated.
- **TTL ordering**: `eventTtlSeconds` (600) > `maxAgeSeconds` (300), so any replay that survives the timestamp check is still caught by the dedupe claim.
- One caveat: if the dedupe claim succeeds but your handler later crashes before processing, that event ID is blocked for 10 minutes. If your provider retries on non-2xx only, consider claiming *after* the handler succeeds instead — the tradeoff is a small double-processing window.

Here's a sketch (Node.js/Express) that follows webhook verification best practices:

```js
const crypto = require('crypto');

// Precondition: body parser must be configured with raw capture,
// e.g. express.raw({ type: 'application/json' }) for this route,
// because HMAC must be computed over the exact bytes sent.

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET; // never hardcode

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get('X-Signature-256');
  if (!signatureHeader) {
    return res.status(400).json({ error: 'missing signature' });
  }

  // Parse "sha256=<hex>" (or "t=<ts>,v1=<hex>" style if using timestamps)
  const match = /^sha256=([0-9a-f]{64})$/i.exec(signatureHeader);
  if (!match) {
    return res.status(400).json({ error: 'malformed signature' });
  }
  const received = Buffer.from(match[1], 'hex');

  // Compute HMAC over the RAW body bytes
  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(req.body) // must be a Buffer of raw bytes
    .digest();

  // Timing-safe comparison; also check length equality first
  const valid =
    received.length === expected.length &&
    crypto.timingSafeEqual(received, expected);

  if (!valid) {
    return res.status(401).json({ error: 'invalid signature' });
  }

  next();
}

// Route: raw body is essential
app.post('/webhooks',
  express.raw({ type: 'application/json', limit: '1mb' }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString('utf8'));
    // handle event...
    res.status(200).end();
  }
);
```

Key security points:

1. **Raw body only** — verify against the exact bytes received; re-serializing parsed JSON can change whitespace/encoding and break or weaken verification.
2. **Timing-safe comparison** — `crypto.timingSafeEqual`, never `===` on hex strings.
3. **Constant-length check first** — `timingSafeEqual` throws on length mismatch, so compare lengths before calling.
4. **Fail closed** — missing/malformed headers are rejected, not skipped.
5. **Secret from env/config** — rotate it if it leaks; never log it or the signature.
6. **Optional hardening** — include a timestamp in the signed payload and reject events older than a few minutes to prevent replay attacks; add an idempotency key (event ID) to dedupe redeliveries.

Updated sketch with the `timestamp + '.' + raw_body` scheme and replay protection:

```js
const crypto = require('crypto');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const TOLERANCE_SECONDS = 5 * 60; // reject timestamps older than 5 minutes

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get('X-Signature-256');
  if (!signatureHeader) {
    return res.status(400).json({ error: 'missing signature' });
  }

  // Expected format: "t=<unix_ts>,v1=<hex_hmac>"
  const parts = Object.fromEntries(
    signatureHeader.split(',').map((kv) => kv.split('='))
  );
  const timestamp = parts.t;
  const receivedHex = parts.v1;

  if (!timestamp || !receivedHex) {
    return res.status(400).json({ error: 'malformed signature' });
  }

  // Replay protection: reject stale timestamps
  const ts = Number.parseInt(timestamp, 10);
  if (!Number.isFinite(ts)) {
    return res.status(400).json({ error: 'invalid timestamp' });
  }
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - ts) > TOLERANCE_SECONDS) {
    return res.status(401).json({ error: 'timestamp outside tolerance' });
  }

  // Signed payload is timestamp + '.' + raw_body
  const signedPayload = Buffer.concat([
    Buffer.from(`${timestamp}.`, 'utf8'),
    req.body, // raw Buffer from express.raw()
  ]);

  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(signedPayload)
    .digest();

  const received = Buffer.from(receivedHex, 'hex');

  // Constant-time comparison with length pre-check
  const valid =
    received.length === expected.length &&
    crypto.timingSafeEqual(received, expected);

  if (!valid) {
    return res.status(401).json({ error: 'invalid signature' });
  }

  next();
}

app.post('/webhooks',
  express.raw({ type: 'application/json', limit: '1mb' }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString('utf8'));
    // handle event...
    res.status(200).end();
  }
);
```

Notes on the changes:

1. **Signed payload construction** — the HMAC input is exactly `t + '.' + raw_body` as bytes; the timestamp string used here must be the same one from the header (don't re-format it).
2. **Replay window** — timestamps more than 5 minutes from now (in either direction) are rejected. Using `Math.abs` also rejects future-dated timestamps, which prevents an attacker pre-signing with a far-future `t`.
3. **Constant-time comparison** — `crypto.timingSafeEqual` with a length pre-check, as before.
4. **Remaining hardening** — even within the 5-minute window, replays are possible, so dedupe on the event ID (idempotency cache) in your handler; and keep the raw-body middleware route-specific so parsed-body routes can't accidentally bypass verification.

Updated sketch with secret rotation and event-ID deduplication:

```js
const crypto = require('crypto');

// Ordered: current secret first, then previous. Rotate by appending
// the new secret and dropping the oldest after the overlap window.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

const TOLERANCE_SECONDS = 5 * 60;   // timestamp freshness window
const DEDUPE_TTL_MS = 10 * 60 * 1000; // reject repeated event IDs for 10 min

// In-memory dedupe; swap for Redis in multi-instance deployments.
const seenEvents = new Map(); // eventId -> expiry timestamp

function isDuplicateEvent(eventId) {
  const now = Date.now();

  // Opportunistic cleanup so the map doesn't grow unbounded
  if (seenEvents.size > 10000) {
    for (const [id, expiry] of seenEvents) {
      if (expiry <= now) seenEvents.delete(id);
    }
  }

  const expiry = seenEvents.get(eventId);
  if (expiry && expiry > now) return true;

  seenEvents.set(eventId, now + DEDUPE_TTL_MS);
  return false;
}

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get('X-Signature-256');
  if (!signatureHeader) {
    return res.status(400).json({ error: 'missing signature' });
  }

  // Expected format: "t=<unix_ts>,v1=<hex_hmac>"
  const parts = Object.fromEntries(
    signatureHeader.split(',').map((kv) => kv.split('='))
  );
  const timestamp = parts.t;
  const receivedHex = parts.v1;

  if (!timestamp || !receivedHex) {
    return res.status(400).json({ error: 'malformed signature' });
  }

  // Replay protection: reject timestamps outside the 5-minute window
  const ts = Number.parseInt(timestamp, 10);
  if (!Number.isFinite(ts)) {
    return res.status(400).json({ error: 'invalid timestamp' });
  }
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - ts) > TOLERANCE_SECONDS) {
    return res.status(401).json({ error: 'timestamp outside tolerance' });
  }

  // Signed payload: timestamp + '.' + raw_body
  const timestampPrefix = Buffer.from(`${timestamp}.`, 'utf8');
  const received = Buffer.from(receivedHex, 'hex');

  // Try each known secret; accept if any verifies (constant-time per secret)
  let valid = false;
  for (const secret of WEBHOOK_SECRETS) {
    const expected = crypto
      .createHmac('sha256', secret)
      .update(timestampPrefix)
      .update(req.body) // raw Buffer
      .digest();

    if (
      received.length === expected.length &&
      crypto.timingSafeEqual(received, expected)
    ) {
      valid = true;
      break;
    }
  }

  if (!valid) {
    return res.status(401).json({ error: 'invalid signature' });
  }

  // Event-ID dedupe: reject repeats within 10 minutes
  const eventId = req.get('X-Event-Id'); // or extract from parsed body
  if (eventId && isDuplicateEvent(eventId)) {
    return res.status(409).json({ error: 'duplicate event' });
  }

  next();
}

app.post('/webhooks',
  express.raw({ type: 'application/json', limit: '1mb' }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString('utf8'));
    // handle event...
    res.status(200).end();
  }
);
```

Notes on the changes:

1. **Multi-secret verification** — the HMAC is recomputed against each configured secret (current, then previous) and compared constant-time per secret. This lets senders migrate to the new secret without a hard cutover. Drop the previous secret once you're confident no old-signed deliveries remain in flight.
2. **Dedupe only after signature verification** — the event ID is trusted only once the request is authenticated, so attackers can't poison the dedupe cache with forged IDs.
3. **Dedupe TTL** — entries expire after 10 minutes; cleanup is opportunistic to bound memory. For multiple app instances, back this with Redis (`SET event:<id> 1 NX EX 600`) so dedupe is shared.
4. **409 for duplicates** — signals the sender it's a redelivery, not a failure to retry; alternatively return 200 and skip processing if the sender treats non-2xx as retry-worthy.
5. **Event ID source** — adjust `X-Event-Id` to wherever your sender puts it (header or a body field like `event.id`); if it's in the body, parse it after verification.

```ts
// webhookVerification.ts — final pseudocode

import { createHmac, timingSafeEqual } from "crypto";

// ---------- Configuration ----------

// Ordered: current secret first, then previous. Rotate by prepending
// the new secret and dropping the oldest after the overlap window.
const WEBHOOK_SECRETS: readonly string[] = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter((s): s is string => Boolean(s));

const TOLERANCE_SECONDS = 5 * 60;        // reject timestamps older/newer than 5 min
const DEDUPE_TTL_MS = 10 * 60 * 1000;    // reject repeated event IDs for 10 min
const MAX_BODY_BYTES = 1 * 1024 * 1024;

// ---------- Types ----------

interface SignatureHeader {
  timestamp: string;
  hmacHex: string;
}

interface VerificationResult {
  ok: boolean;
  status?: 401 | 409;
  error?: string;
}

// ---------- Signature header parsing ----------

// Expected format: "t=<unix_ts>,v1=<hex_hmac>"
function parseSignatureHeader(header: string | undefined): SignatureHeader | null {
  if (!header) return null;

  const parts = new Map<string, string>();
  for (const kv of header.split(",")) {
    const [key, value] = kv.split("=");
    if (key && value) parts.set(key, value);
  }

  const timestamp = parts.get("t");
  const hmacHex = parts.get("v1");
  if (!timestamp || !hmacHex) return null;

  return { timestamp, hmacHex };
}

// ---------- Timestamp freshness ----------

function isTimestampFresh(timestamp: string): boolean {
  const ts = Number.parseInt(timestamp, 10);
  if (!Number.isFinite(ts)) return false;

  const now = Math.floor(Date.now() / 1000);
  return Math.abs(now - ts) <= TOLERANCE_SECONDS; // rejects past AND future skew
}

// ---------- HMAC verification (constant-time, multi-secret) ----------

// Signed payload is exactly: timestamp + '.' + raw_body (raw bytes)
function verifyHmac(
  timestamp: string,
  rawBody: Buffer,
  hmacHex: string,
): boolean {
  const received = Buffer.from(hmacHex, "hex");

  for (const secret of WEBHOOK_SECRETS) {
    const expected = createHmac("sha256", secret)
      .update(Buffer.from(`${timestamp}.`, "utf8"))
      .update(rawBody)
      .digest();

    const valid =
      received.length === expected.length &&
      timingSafeEqual(received, expected);

    if (valid) return true;
  }
  return false;
}

// ---------- Event-ID dedupe (10-minute TTL) ----------

// In-memory for single instance; use Redis SET NX EX 600 for multi-instance.
const seenEvents = new Map<string, number>(); // eventId -> expiry (ms)

function isReplay(eventId: string): boolean {
  const now = Date.now();

  if (seenEvents.size > 10_000) {
    for (const [id, expiry] of seenEvents) {
      if (expiry <= now) seenEvents.delete(id);
    }
  }

  const expiry = seenEvents.get(eventId);
  if (expiry !== undefined && expiry > now) return true;

  seenEvents.set(eventId, now + DEDUPE_TTL_MS);
  return false;
}

// ---------- Middleware ----------

export function verifyWebhook(
  req: { headers: Record<string, string | undefined>; rawBody: Buffer },
  res: { status(code: number): { json(body: object): void; end(): void } },
  next: () => void,
): void {
  // 1. Parse and validate the signature header
  const sig = parseSignatureHeader(req.headers["x-signature-256"]);
  if (!sig) {
    res.status(401).json({ error: "missing or malformed signature" });
    return;
  }

  // 2. Reject stale (or future-skewed) timestamps -> 401
  if (!isTimestampFresh(sig.timestamp)) {
    res.status(401).json({ error: "timestamp outside tolerance" });
    return;
  }

  // 3. Verify HMAC over timestamp + '.' + raw_body against current/previous secrets
  if (!verifyHmac(sig.timestamp, req.rawBody, sig.hmacHex)) {
    res.status(401).json({ error: "invalid signature" });
    return;
  }

  // 4. Dedupe on event ID (only after authentication) -> 409 on replay
  const eventId = req.headers["x-event-id"];
  if (eventId && isReplay(eventId)) {
    res.status(409).json({ error: "duplicate event" });
    return;
  }

  next();
}

// ---------- Route wiring ----------

// app.post(
//   "/webhooks",
//   express.raw({ type: "application/json", limit: MAX_BODY_BYTES }), // raw bytes required
//   verifyWebhook,
//   (req, res) => {
//     const event = JSON.parse(req.rawBody.toString("utf8"));
//     // handle event...
//     res.status(200).end();
//   },
// );
```

Summary of the contract:

| Condition | Response |
|---|---|
| Missing/malformed signature header | 401 |
| Timestamp outside ±5 minutes | 401 |
| HMAC fails against all configured secrets | 401 |
| Event ID seen within last 10 minutes | 409 |

Security invariants preserved: HMAC computed over raw body bytes only; signed payload is `timestamp + '.' + raw_body`; constant-time comparison with length pre-check per secret; dedupe runs only after authentication so forged event IDs can't poison the cache; secrets sourced from environment, never logged.

Here's a sketch (Node.js/Express) of HMAC-SHA256 webhook verification:

```js
const crypto = require('crypto');

function verifyWebhook(req, res, next) {
  const signatureHeader = req.get('X-Signature-256') || '';
  const secret = process.env.WEBHOOK_SECRET;

  if (!secret) {
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  // Parse "sha256=<hex>" format
  const [scheme, providedSig] = signatureHeader.split('=');
  if (scheme !== 'sha256' || !providedSig) {
    return res.status(401).json({ error: 'Invalid signature format' });
  }

  // Compute HMAC over the RAW body — must be captured before any body parser runs
  const expected = crypto
    .createHmac('sha256', secret)
    .update(req.rawBody)
    .digest('hex');

  // Timing-safe comparison to prevent timing attacks
  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(providedSig, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}
```

Key points:

1. **Raw body is essential.** The signature is computed over the exact bytes sent. Any JSON parsing/re-serialization will break verification. Capture the raw body before your body parser:

```js
app.use(express.json({
  verify: (req, _res, buf) => { req.rawBody = buf; }
}));
```

2. **Timing-safe comparison.** Use `crypto.timingSafeEqual`, never `===` on hex strings.

3. **Constant behavior on failure.** Return the same 401 regardless of whether the header is missing, malformed, or mismatched, to avoid leaking details to attackers.

4. **Optional hardening:**
   - Replay protection: if the provider includes a timestamp header (e.g., Stripe's `t=...` scheme), verify it's within a small window (e.g., 5 minutes) and sign `timestamp + '.' + payload`.
   - Per-provider secrets so a leaked key doesn't affect all integrations.
   - Rate-limit the endpoint and return 413 for oversized bodies before verification.

