Here's the updated middleware with timestamp validation and replay protection:

```js
const crypto = require('crypto');

const REPLAY_WINDOW_MS = 5 * 60 * 1000; // 5 minutes

function verifyWebhook(req, res, next) {
  const secret = process.env.WEBHOOK_SECRET;
  if (!secret) {
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  const timestampHeader = req.get('X-Timestamp');
  const signatureHeader = req.get('X-Signature-256') || '';

  // --- Timestamp validation (replay protection) ---
  const timestamp = Number(timestampHeader);
  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  const now = Date.now();
  const skew = Math.abs(now - timestamp * 1000);
  if (skew > REPLAY_WINDOW_MS) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // --- Signature verification over timestamp + '.' + raw body ---
  const [scheme, providedSig] = signatureHeader.split('=');
  if (scheme !== 'sha256' || !providedSig) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  const signedPayload = `${timestampHeader}.${req.rawBody}`;

  const expected = crypto
    .createHmac('sha256', secret)
    .update(signedPayload)
    .digest('hex');

  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(providedSig, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}
```

Notes on the changes:

1. **Signed payload format.** The HMAC now covers `timestamp + '.' + rawBody`, exactly as the sender computes it. The timestamp string used in the HMAC is the raw header value (not a re-parsed number) so byte-for-byte comparison matches the sender.

2. **Replay window.** Timestamps more than 5 minutes from *now* (in either direction — future skew is rejected too, since `Math.abs` guards against an attacker pre-signing a far-future timestamp) are rejected. An attacker replaying an old captured request fails the freshness check even though the signature is still valid.

3. **Uniform 401 responses.** Missing timestamp, malformed timestamp, stale timestamp, and bad signature all return the identical error, so an attacker learns nothing about which check failed.

4. **Timestamp is still authenticated.** Because the timestamp is inside the signed payload, a client can't update the timestamp without recomputing the signature — the freshness check and the signature check reinforce each other.

One caveat: this requires reasonably synchronized clocks. If your server clock drifts, legitimate webhooks will start failing — consider NTP sync and monitoring the skew distribution in logs to tune the window.

Here's the updated middleware with secret rotation and event ID deduplication:

```js
const crypto = require('crypto');

const REPLAY_WINDOW_MS = 5 * 60 * 1000;   // 5 minutes
const EVENT_ID_TTL_MS  = 10 * 60 * 1000;  // 10 minutes

// --- Secret rotation: current first, then previous ---
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

if (WEBHOOK_SECRETS.length === 0) {
  throw new Error('No webhook secrets configured');
}

// --- Event ID dedup cache (in-memory; use Redis in multi-instance deployments) ---
const seenEventIds = new Map(); // eventId -> expiry timestamp

function isDuplicateEvent(eventId) {
  const now = Date.now();

  // Opportunistic cleanup to bound memory growth
  for (const [id, expiry] of seenEventIds) {
    if (expiry <= now) seenEventIds.delete(id);
  }

  if (seenEventIds.has(eventId)) {
    return true;
  }
  seenEventIds.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// --- Timing-safe string comparison ---
function safeEqual(a, b) {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) {
    // Compare against itself to burn equivalent time, then fail
    crypto.timingSafeEqual(bufA, bufA);
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

function verifyWebhook(req, res, next) {
  const timestampHeader = req.get('X-Timestamp');
  const signatureHeader = req.get('X-Signature-256') || '';
  const eventId = req.get('X-Event-Id');

  // --- Timestamp validation (replay protection) ---
  const timestamp = Number(timestampHeader);
  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    return res.status(401).json({ error: 'Invalid signature' });
  }
  if (Math.abs(Date.now() - timestamp * 1000) > REPLAY_WINDOW_MS) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // --- Parse signature ---
  const [scheme, providedSig] = signatureHeader.split('=');
  if (scheme !== 'sha256' || !providedSig) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // --- Try each known secret; accept if any verifies ---
  const signedPayload = `${timestampHeader}.${req.rawBody}`;
  const valid = WEBHOOK_SECRETS.some((secret) => {
    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest('hex');
    return safeEqual(expected, providedSig);
  });

  if (!valid) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // --- Event ID dedup (only after signature is verified) ---
  if (!eventId || isDuplicateEvent(eventId)) {
    return res.status(409).json({ error: 'Duplicate event' });
  }

  next();
}
```

Design notes:

1. **Secret rotation.** Both the current and previous secrets are tried. During rotation, senders that have already switched verify against the current secret; stragglers still verify against the previous one. Once you're confident all senders have rotated, drop `WEBHOOK_SECRET_PREVIOUS`. Secrets are read at module load — restart or hot-reload config on rotation.

2. **Timing-safe across secrets.** Each candidate secret's HMAC is compared with `safeEqual`. The length-mismatch branch still performs a `timingSafeEqual` call so response timing doesn't reveal whether the failure was a length mismatch or a content mismatch.

3. **Dedup only after authentication.** The event ID check runs *after* signature verification. This is important: if it ran first, an unauthenticated attacker could poison the cache by replaying a captured event ID with a garbage body, causing the *real* delivery of that event to be rejected as a duplicate (a denial-of-service on legitimate events).

4. **Duplicate response is 409, not 401.** A verified-but-repeated event is a different condition from a bad signature. Returning 409 lets the sender distinguish "your request was unauthenticated" from "we already processed this" — many providers treat non-2xx as a delivery failure and retry, so pick the status code your provider handles correctly (some expect 200 even for duplicates; adjust if so).

5. **In-memory cache caveat.** `Map` works for a single instance. If you run multiple replicas behind a load balancer, the same event can land on different nodes and slip through. Use Redis with a 10-minute TTL (`SET event:<id> 1 NX EX 600`) for correctness at scale.

6. **Ordering of checks.** Timestamp freshness → signature → dedup. Cheap, unauthenticated-safe checks first; stateful checks last, only for verified requests.

```ts
// webhookVerification.ts
import { createHmac, timingSafeEqual } from 'crypto';

// ---------- Configuration ----------

const REPLAY_WINDOW_MS = 5 * 60 * 1000;   // reject timestamps older/newer than 5 min
const EVENT_ID_TTL_MS  = 10 * 60 * 1000;  // reject repeated event IDs for 10 min

interface WebhookConfig {
  currentSecret: string;
  previousSecret?: string; // present only during rotation
}

const CONFIG: WebhookConfig = {
  currentSecret: process.env.WEBHOOK_SECRET_CURRENT!,
  previousSecret: process.env.WEBHOOK_SECRET_PREVIOUS,
};

const SECRETS: readonly string[] = [
  CONFIG.currentSecret,
  CONFIG.previousSecret,
].filter((s): s is string => typeof s === 'string' && s.length > 0);

if (SECRETS.length === 0) {
  throw new Error('No webhook secrets configured');
}

// ---------- Event ID dedup cache ----------
// In-memory for single instance; use Redis (SET NX EX 600) for multi-replica.

const seenEventIds: Map<string, number> = new Map(); // eventId -> expiry (epoch ms)

function isDuplicateEvent(eventId: string): boolean {
  const now = Date.now();

  // Opportunistic cleanup to bound memory growth
  for (const [id, expiry] of seenEventIds) {
    if (expiry <= now) seenEventIds.delete(id);
  }

  if (seenEventIds.has(eventId)) return true;
  seenEventIds.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ---------- Crypto helpers ----------

function safeEqual(a: string, b: string): boolean {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) {
    timingSafeEqual(bufA, bufA); // burn equivalent time; don't leak length mismatch
    return false;
  }
  return timingSafeEqual(bufA, bufB);
}

function hmacHex(secret: string, payload: string): string {
  return createHmac('sha256', secret).update(payload).digest('hex');
}

// ---------- Types ----------

interface WebhookRequest {
  rawBody: Buffer;                 // captured before any body parser runs
  get(header: string): string | undefined;
}

interface WebhookResponse {
  status(code: number): { json(body: object): void };
}

type NextFn = () => void;

// ---------- Middleware ----------

export function verifyWebhook(req: WebhookRequest, res: WebhookResponse, next: NextFn): void {
  const timestampHeader = req.get('X-Timestamp');
  const signatureHeader = req.get('X-Signature-256') ?? '';
  const eventId = req.get('X-Event-Id');

  // 1. Timestamp validation (replay window)
  const timestamp = Number(timestampHeader);
  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    res.status(401).json({ error: 'Invalid signature' });
    return;
  }
  if (Math.abs(Date.now() - timestamp * 1000) > REPLAY_WINDOW_MS) {
    res.status(401).json({ error: 'Invalid signature' }); // stale timestamp -> 401
    return;
  }

  // 2. Parse signature header ("sha256=<hex>")
  const [scheme, providedSig] = signatureHeader.split('=');
  if (scheme !== 'sha256' || !providedSig) {
    res.status(401).json({ error: 'Invalid signature' });
    return;
  }

  // 3. Verify HMAC over "timestamp.rawBody" against current or previous secret
  const signedPayload = `${timestampHeader}.${req.rawBody.toString('utf8')}`;
  const signatureValid = SECRETS.some((secret) =>
    safeEqual(hmacHex(secret, signedPayload), providedSig)
  );

  if (!signatureValid) {
    res.status(401).json({ error: 'Invalid signature' }); // bad signature -> 401
    return;
  }

  // 4. Event ID dedup — only after authentication, so unauthenticated
  //    requests cannot poison the cache and DoS legitimate deliveries
  if (!eventId || isDuplicateEvent(eventId)) {
    res.status(409).json({ error: 'Duplicate event' }); // replay -> 409
    return;
  }

  next();
}
```

