    except ValueError:
        return False, "Malformed timestamp"

    # Replay protection: reject stale deliveries
    now = int(time.time())
    if abs(now - ts) > MAX_AGE_SECONDS:
        return False, "Timestamp outside allowed window"

    # Signed message is exactly: timestamp + "." + raw_body
    # Use the *original header string*, not the parsed int, so bytes match
    # what the sender signed.
    signed_payload = f"{timestamp}.".encode() + raw_body

    expected = hmac.new(
        WEBHOOK_SECRET.encode(),
        signed_payload,
        hashlib.sha256,
    ).hexdigest()

    scheme, _, provided = signature.partition("=")
    if scheme != "sha256" or not provided:
        return False, "Malformed signature header"

    # Constant-time comparison
    if not hmac.compare_digest(expected, provided):
        return False, "Invalid signature"

    return True, None
