    return value.map(normalize);
  }
  if (value !== null && typeof value === 'object') {
    const result = {};
    for (const key of Object.keys(value)) {
      const normalized = normalize(value[key]);
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return result;
  }
  return value;
}
```

Changes from the previous version:
- **Object properties with `undefined` values** are omitted from the result
- **`null` entries in arrays** are kept — arrays use `map`, which preserves every position, and `null` falls through to `return value` unchanged

Example:

```javascript
normalize({
  a: undefined,
  b: null,
  list: [null, "  x  ", undefined]
});
// { b: null, list: [null, "x", undefined] }
```

Note: `undefined` inside arrays is preserved by `map` (the slot stays, becoming a hole in the array). If you'd rather drop those too, say the word.

