const a = normalize({ name: '  Alice  ', nick: '   ', age: 0, active: false });
console.assert(a.name === 'Alice', 'strings are trimmed');
console.assert(a.nick === null, 'empty string becomes null');
console.assert(a.age === 0 && a.active === false, '0 and false are preserved');

// 2. Undefined properties omitted, null values kept
