    return result;
  }
  return value;
}
```

Changes:

- **Empty strings** (including strings that are only whitespace, like `'   '`) now normalize to `null`.
- **`0` and `false`** are preserved — they fall through to the final `return value`, since the function never uses truthiness checks. The same applies to `NaN`, `''`-adjacent falsy values like `null` and `undefined`.

Examples:

```js
normalize('  ');                    // null
normalize('  hi  ');                // 'hi'
normalize(0);                       // 0
normalize(false);                  // false
normalize({ a: ' ', b: 0, c: false, d: ['  ', 0] });
// { a: null, b: 0, c: false, d: [null, 0] }
```

One caveat: if you later refactor, avoid patterns like `if (!value) return value;` or `value ? ... : ...` — those would swallow `0` and `false` distinctions. The explicit type checks above are what keep them safe.

```js
function normalize(value) {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? null : trimmed;
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === 'object') {
    const result = {};
    for (const key of Object.keys(value)) {
      const normalized = normalize(value[key]);
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return result;
  }
  return value;
}
```

Changes:

- **Object properties** whose normalized value is `undefined` are omitted from the result. Note the check happens *after* normalization, so a property explicitly set to `undefined` is dropped, and any nested value that normalizes to `undefined` would also be dropped.
- **Arrays** are untouched by this rule — `map` preserves every index, so `null` entries (including empty strings that normalized to `null`) stay in place. `undefined` array entries also remain as `undefined` at their index, since the omission rule applies only to object keys.

Examples:

```js
normalize({ a: undefined, b: ' x ', c: null });
// { b: 'x', c: null }   — 'a' omitted, 'c' kept

normalize({ a: 0, b: false, c: '  ' });
// { a: 0, b: false, c: null }  — 0 and false preserved

normalize(['  ', undefined, 0, null]);
// [null, undefined, 0, null]   — array length and positions unchanged

normalize({ list: ['  ', undefined], inner: { skip: undefined } });
// { list: [null, undefined], inner: {} }
```

Summary of the full behavior so far:

| Input | Output |
|---|---|
| `'  hi  '` | `'hi'` |
| `'   '` (whitespace-only) | `null` |
| `0`, `false`, `NaN` | unchanged |
| `undefined` (object property) | property omitted |
| `undefined` (array element) | stays `undefined` in place |
| `null` (array element) | stays `null` in place |
| arrays / objects | recursed, new copies returned |

