# Webhook Verification with Timestamp + Replay Protection

The signature header carries the timestamp alongside the signature (Stripe-style: `t=<unix_seconds>,v1=<hex>`). The HMAC is computed over `t + '.' + rawBody`, so the timestamp itself is authenticated — an attacker can't strip or alter it without invalidating the signature.

```js
const crypto = require('crypto');
const express = require('express');

const app = express();

// Capture the raw body BEFORE any JSON parsing
app.use('/webhooks', express.raw({ type: 'application/json' }));

const MAX_TIMESTAMP_AGE_SECONDS = 5 * 60; // 5 minutes

function parseSignatureHeader(header) {
  // Expected format: t=1700000000,v1=abc123...
  const parts = {};
  for (const pair of header.split(',')) {
    const idx = pair.indexOf('=');
    if (idx === -1) return null;
    parts[pair.slice(0, idx)] = pair.slice(idx + 1);
  }
  if (!parts.t || !parts.v1) return null;
  const timestamp = Number(parts.t);
  if (!Number.isInteger(timestamp)) return null;
  return { timestamp, signature: parts.v1 };
}

function verifyWebhookSignature(secret) {
  return (req, res, next) => {
    const header = req.get('X-Webhook-Signature');
    if (!header) {
      return res.status(401).json({ error: 'Missing signature' });
    }

    const parsed = parseSignatureHeader(header);
    if (!parsed) {
      return res.status(401).json({ error: 'Malformed signature header' });
    }

    if (!Buffer.isBuffer(req.body)) {
      return res.status(500).json({ error: 'Raw body unavailable' });
    }

    // 1. Replay protection: reject stale (or far-future) timestamps
    const nowSeconds = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSeconds - parsed.timestamp) > MAX_TIMESTAMP_AGE_SECONDS) {
      return res.status(401).json({ error: 'Timestamp outside tolerance' });
    }

    // 2. Recompute HMAC over timestamp + '.' + raw body
    const signedPayload = Buffer.concat([
      Buffer.from(`${parsed.timestamp}.`, 'utf8'),
      req.body,
    ]);

    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest('hex');

    // 3. Constant-time comparison (lengths must match first)
    const providedBuf = Buffer.from(parsed.signature, 'utf8');
    const expectedBuf = Buffer.from(expected, 'utf8');

    if (
      providedBuf.length !== expectedBuf.length ||
      !crypto.timingSafeEqual(providedBuf, expectedBuf)
    ) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // Authenticated — safe to parse and process
    req.body = JSON.parse(req.body.toString('utf8'));
    next();
  };
}

app.post(
  '/webhooks/events',
  verifyWebhookSignature(process.env.WEBHOOK_SECRET),
  (req, res) => {
    console.log('Verified event:', req.body);
    res.sendStatus(200);
  }
);
```

## How the sender signs

```js
const timestamp = Math.floor(Date.now() / 1000);
const signature = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

headers['X-Webhook-Signature'] = `t=${timestamp},v1=${signature}`;
```

## Security notes

1. **Order of checks matters**: timestamp freshness is checked *before* the HMAC comparison. This is safe because the timestamp is part of the signed payload — a forged timestamp fails verification anyway.
2. **`Math.abs` tolerance** also rejects far-future timestamps, guarding against clock-skew abuse and pre-computed "future" signatures.
3. **Constant-time comparison** via `crypto.timingSafeEqual`, with the length pre-check to avoid both the throw and length leakage.
4. **The `.` separator** prevents ambiguity attacks (e.g., `t=12` + body `3...` vs `t=123` + body `...` colliding).
5. **Clock skew**: 5 minutes assumes reasonably synced clocks (NTP). If senders are third parties with unreliable clocks, consider logging rejections for monitoring before tightening.
6. **Multiple signatures**: if you support key rotation, allow multiple `v1=` values in the header and accept if *any* matches (still using `timingSafeEqual` for each).

# Webhook Verification with Secret Rotation + Event Deduplication

Two additions: try **current secret first, then previous** (both with constant-time comparison), and reject **repeated event IDs within a 10-minute window** to stop replayed deliveries.

```js
const crypto = require('crypto');
const express = require('express');

const app = express();

// Capture the raw body BEFORE any JSON parsing
app.use('/webhooks', express.raw({ type: 'application/json' }));

const MAX_TIMESTAMP_AGE_SECONDS = 5 * 60;   // 5 minutes
const EVENT_ID_TTL_MS = 10 * 60 * 1000;     // 10 minutes

// ---------------------------------------------------------------------------
// Seen-event store (in-memory; use Redis SET NX PX for multi-instance deploys)
// ---------------------------------------------------------------------------
const seenEvents = new Map(); // eventId -> expiry timestamp (ms)

function isDuplicateEvent(eventId) {
  const now = Date.now();

  // Opportunistic cleanup of expired entries
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }

  if (seenEvents.has(eventId)) return true;

  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ---------------------------------------------------------------------------
// Signature header parsing: t=<unix_seconds>,v1=<hex>
// ---------------------------------------------------------------------------
function parseSignatureHeader(header) {
  const parts = {};
  for (const pair of header.split(',')) {
    const idx = pair.indexOf('=');
    if (idx === -1) return null;
    parts[pair.slice(0, idx)] = pair.slice(idx + 1);
  }
  if (!parts.t || !parts.v1) return null;
  const timestamp = Number(parts.t);
  if (!Number.isInteger(timestamp)) return null;
  return { timestamp, signature: parts.v1 };
}

// Constant-time check of one signature against one secret
function signatureMatches(secret, signedPayload, providedSignature) {
  const expected = crypto
    .createHmac('sha256', secret)
    .update(signedPayload)
    .digest('hex');

  const providedBuf = Buffer.from(providedSignature, 'utf8');
  const expectedBuf = Buffer.from(expected, 'utf8');

  return (
    providedBuf.length === expectedBuf.length &&
    crypto.timingSafeEqual(providedBuf, expectedBuf)
  );
}

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------
function verifyWebhookSignature(secrets) {
  const { current, previous } = secrets;
  if (!current) throw new Error('Current webhook secret is required');

  return (req, res, next) => {
    const header = req.get('X-Webhook-Signature');
    if (!header) {
      return res.status(401).json({ error: 'Missing signature' });
    }

    const parsed = parseSignatureHeader(header);
    if (!parsed) {
      return res.status(401).json({ error: 'Malformed signature header' });
    }

    if (!Buffer.isBuffer(req.body)) {
      return res.status(500).json({ error: 'Raw body unavailable' });
    }

    // 1. Replay protection: timestamp freshness
    const nowSeconds = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSeconds - parsed.timestamp) > MAX_TIMESTAMP_AGE_SECONDS) {
      return res.status(401).json({ error: 'Timestamp outside tolerance' });
    }

    // 2. Verify HMAC over timestamp + '.' + raw body,
    //    trying current secret first, then previous (rotation window)
    const signedPayload = Buffer.concat([
      Buffer.from(`${parsed.timestamp}.`, 'utf8'),
      req.body,
    ]);

    const candidates = previous ? [current, previous] : [current];
    const valid = candidates.some((secret) =>
      signatureMatches(secret, signedPayload, parsed.signature)
    );

    if (!valid) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // 3. Parse body only after authenticity is established
    const body = JSON.parse(req.body.toString('utf8'));

    // 4. Deduplication: reject repeated event IDs within 10 minutes
    const eventId = body.id;
    if (typeof eventId !== 'string' || eventId.length === 0) {
      return res.status(400).json({ error: 'Missing event ID' });
    }
    if (isDuplicateEvent(eventId)) {
      // 200 so the sender stops retrying, but we don't reprocess
      return res.status(200).json({ status: 'duplicate_ignored' });
    }

    req.body = body;
    next();
  };
}

app.post(
  '/webhooks/events',
  verifyWebhookSignature({
    current: process.env.WEBHOOK_SECRET_CURRENT,
    previous: process.env.WEBHOOK_SECRET_PREVIOUS, // may be undefined
  }),
  (req, res) => {
    console.log('Verified, fresh event:', req.body.id);
    res.sendStatus(200);
  }
);
```

## Security notes

1. **Rotation window**: the previous secret is accepted only until all in-flight senders have switched over. Unset `WEBHOOK_SECRET_PREVIOUS` once rotation completes — don't leave old secrets valid indefinitely.
2. **Both comparisons are constant-time.** `Array.some` short-circuits on the first match, which leaks *which* secret matched via timing — acceptable here since both secrets are equally trusted, but if that matters in your threat model, evaluate both and OR the results.
3. **Duplicate → 200, not 4xx.** Returning an error causes legitimate senders to retry, amplifying duplicates. Acknowledge and discard.
4. **Dedup window (10 min) > timestamp tolerance (5 min)** is deliberate: a replayed request must arrive within 5 minutes to pass signature checks, so 10 minutes of ID retention covers the entire attack surface with margin.
5. **In-memory store is single-instance only.** Behind a load balancer, use Redis: `SET eventId 1 NX PX 600000` — atomic, TTL'd, shared across instances.
6. **Event ID is checked only after signature verification**, so attackers can't probe or poison the dedup cache with forged IDs.
7. **Fail-closed**: middleware throws at startup if the current secret is missing, rather than running with verification silently broken.

# Final Webhook Verification Middleware (TypeScript Pseudocode)

Consolidates all requirements: raw-body HMAC over `timestamp + '.' + rawBody`, 5-minute timestamp tolerance, current/previous secret rotation, constant-time comparison, and 10-minute event-ID deduplication. **401** for bad signature or stale timestamp; **409** for replay.

```typescript
import crypto from "crypto";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const MAX_TIMESTAMP_AGE_SECONDS = 5 * 60;   // 5 minutes
const EVENT_ID_TTL_MS           = 10 * 60 * 1000; // 10 minutes

interface WebhookSecrets {
  current: string;
  previous?: string; // accepted only during rotation window
}

interface SignatureParts {
  timestamp: number;
  signature: string; // hex
}

// ---------------------------------------------------------------------------
// Seen-event store (single instance; use Redis SET NX PX for multi-instance)
// ---------------------------------------------------------------------------
const seenEvents = new Map<string, number>(); // eventId -> expiry (ms epoch)

function isDuplicateEvent(eventId: string): boolean {
  const now = Date.now();

  // Opportunistic cleanup of expired entries
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }

  if (seenEvents.has(eventId)) return true;

  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// Header format: "t=<unix_seconds>,v1=<hex_signature>"
function parseSignatureHeader(header: string): SignatureParts | null {
  const parts: Record<string, string> = {};
  for (const pair of header.split(",")) {
    const idx = pair.indexOf("=");
    if (idx === -1) return null;
    parts[pair.slice(0, idx)] = pair.slice(idx + 1);
  }
  if (!parts.t || !parts.v1) return null;

  const timestamp = Number(parts.t);
  if (!Number.isInteger(timestamp)) return null;

  return { timestamp, signature: parts.v1 };
}

// Constant-time HMAC check of one candidate secret
function signatureMatches(
  secret: string,
  signedPayload: Buffer,
  providedSignature: string
): boolean {
  const expected = crypto
    .createHmac("sha256", secret)
    .update(signedPayload)
    .digest("hex");

  const providedBuf = Buffer.from(providedSignature, "utf8");
  const expectedBuf = Buffer.from(expected, "utf8");

  return (
    providedBuf.length === expectedBuf.length &&
    crypto.timingSafeEqual(providedBuf, expectedBuf)
  );
}

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------
function verifyWebhookSignature(secrets: WebhookSecrets) {
  if (!secrets.current) {
    throw new Error("Current webhook secret is required"); // fail closed
  }

  return function (req: Request, res: Response, next: NextFunction): void {
    // Precondition: raw body captured before any JSON parsing
    // (e.g., express.raw({ type: "application/json" }) on this route)
    if (!Buffer.isBuffer(req.rawBody)) {
      res.status(500).json({ error: "Raw body unavailable" });
      return;
    }

    const header = req.getHeader("X-Webhook-Signature");
    if (!header) {
      res.status(401).json({ error: "Missing signature" });
      return;
    }

    const parsed = parseSignatureHeader(header);
    if (!parsed) {
      res.status(401).json({ error: "Malformed signature header" });
      return;
    }

    // 1. Timestamp freshness (rejects stale AND far-future) -> 401
    const nowSeconds = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSeconds - parsed.timestamp) > MAX_TIMESTAMP_AGE_SECONDS) {
      res.status(401).json({ error: "Stale timestamp" });
      return;
    }

    // 2. HMAC over timestamp + "." + raw body; try current, then previous
    const signedPayload = Buffer.concat([
      Buffer.from(`${parsed.timestamp}.`, "utf8"),
      req.rawBody,
    ]);

    const candidates = secrets.previous
      ? [secrets.current, secrets.previous]
      : [secrets.current];

    const valid = candidates.some((secret) =>
      signatureMatches(secret, signedPayload, parsed.signature)
    );

    if (!valid) {
      res.status(401).json({ error: "Invalid signature" });
      return;
    }

    // 3. Parse body only after authenticity is established
    const body = JSON.parse(req.rawBody.toString("utf8"));

    // 4. Replay deduplication: repeated event ID within 10 minutes -> 409
    const eventId = body.id;
    if (typeof eventId !== "string" || eventId.length === 0) {
      res.status(400).json({ error: "Missing event ID" });
      return;
    }
    if (isDuplicateEvent(eventId)) {
      res.status(409).json({ error: "Duplicate event" });
      return;
    }

    req.body = body;
    next();
  };
}

// ---------------------------------------------------------------------------
// Wiring
// ---------------------------------------------------------------------------
app.post(
  "/webhooks/events",
  verifyWebhookSignature({
    current: env("WEBHOOK_SECRET_CURRENT"),
    previous: envOptional("WEBHOOK_SECRET_PREVIOUS"),
  }),
  (req, res) => {
    // Authenticated, fresh, non-duplicate event
    processEvent(req.body);
    res.sendStatus(200);
  }
);
```

## Behavior summary

| Condition | Status |
|---|---|
| Missing / malformed signature header | 401 |
| Timestamp older than 5 min (or far-future) | 401 |
| HMAC matches neither current nor previous secret | 401 |
| Event ID already seen within 10 minutes | 409 |
| Missing event ID in verified payload | 400 |
| Valid, fresh, first-seen event | 200 → handler |

## Invariants preserved

- **Raw bytes only** for HMAC input — never re-serialized JSON.
- **Constant-time comparison** (`timingSafeEqual`) with length pre-check; no `===` on secrets or signatures.
- **Timestamp is authenticated** (inside the signed payload), so checking freshness before the HMAC is safe.
- **Dedup runs only after verification**, so forged requests can't poison the replay cache.
- **Dedup TTL (10 min) > timestamp tolerance (5 min)** covers the full replay window with margin.
- **Fail-closed startup** if the current secret is unset; previous secret is dropped once rotation completes.
- **Multi-instance deployments**: swap the in-memory `Map` for Redis `SET eventId 1 NX PX 600000` (atomic, shared, TTL'd).

# HMAC-SHA256 Webhook Signature Verification Middleware

Key points: you must hash the **raw, unparsed body** (JSON parsing/serialization can change bytes and break the signature), and compare digests with a **constant-time** function.

## Express (Node.js)

```js
const crypto = require('crypto');
const express = require('express');

const app = express();
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;

// Capture the raw body ONLY for the webhook route
app.use('/webhooks', express.raw({ type: '*/*' }));

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Signature-256'); // e.g. "sha256=<hex>"
  const timestamp = req.get('X-Signature-Timestamp');

  if (!signature || !timestamp) {
    return res.status(401).json({ error: 'Missing signature headers' });
  }

  // Replay protection: reject stale timestamps (5 min window)
  const age = Math.abs(Date.now() - Number(timestamp));
  if (!Number.isFinite(age) || age > 5 * 60 * 1000) {
    return res.status(401).json({ error: 'Stale or invalid timestamp' });
  }

  // Sign over "timestamp.body" so the timestamp is authenticated too
  const payload = Buffer.concat([
    Buffer.from(`${timestamp}.`),
    req.body, // raw Buffer, never re-serialized
  ]);

  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(payload)
    .digest('hex');

  const provided = signature.replace(/^sha256=/, '');

  // Constant-time comparison; lengths must match to avoid exceptions
  const a = Buffer.from(provided, 'utf8');
  const b = Buffer.from(expected, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Optionally re-parse the body for downstream handlers
  req.parsedBody = JSON.parse(req.body.toString('utf8'));
  next();
}

app.post('/webhooks/events', verifyWebhookSignature, (req, res) => {
  // handle verified event via req.parsedBody
  res.sendStatus(200);
});
```

## FastAPI (Python) equivalent

```python
import hashlib, hmac, os, time
from fastapi import FastAPI, Request, HTTPException

app = FastAPI()
SECRET = os.environ["WEBHOOK_SECRET"].encode()

@app.middleware("http")
async def verify_webhook(request: Request, call_next):
    if not request.url.path.startswith("/webhooks"):
        return await call_next(request)

    raw = await request.body()  # raw bytes, before any parsing
    sig = request.headers.get("X-Signature-256", "").removeprefix("sha256=")
    ts = request.headers.get("X-Signature-Timestamp", "")

    if not sig or not ts.isdigit() or abs(time.time() - int(ts)) > 300:
        raise HTTPException(401, "Missing or stale signature")

    expected = hmac.new(SECRET, ts.encode() + b"." + raw, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        raise HTTPException(401, "Invalid signature")

    return await call_next(request)
```

## Security checklist

- **Raw body only** — never verify against `JSON.stringify(req.body)`; key order/whitespace changes break or weaken verification.
- **`timingSafeEqual` / `compare_digest`** — prevents timing side-channel attacks.
- **Signed timestamp + expiry window** — mitigates replay attacks.
- **Secret from env/secret manager** — never hardcode; support rotation (accept current + previous key during rollover).
- **Scope raw-body parsing** to webhook routes only, so normal JSON routes still work.
- **HTTPS required** — HMAC integrity doesn't replace transport encryption.

