## Express (Node.js)

```js
const crypto = require('crypto');
const express = require('express');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const MAX_AGE_MS = 5 * 60 * 1000; // five minutes

function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Signature-256');       // "sha256=<hex>"
  const timestamp = req.get('X-Signature-Timestamp'); // unix ms

  if (!signature || !timestamp || !/^\d+$/.test(timestamp)) {
    return res.status(401).json({ error: 'Missing or malformed signature headers' });
  }

  // 1. Reject timestamps older than five minutes (also rejects future skew)
  const age = Date.now() - Number(timestamp);
  if (age < 0 || age > MAX_AGE_MS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // 2. Signed payload is exactly: timestamp + '.' + raw_body
  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(timestamp)      // string, as sent
    .update('.')
    .update(req.body)       // raw Buffer from express.raw()
    .digest('hex');

  const provided = signature.replace(/^sha256=/, '');

  // 3. Constant-time comparison (length check first — timingSafeEqual throws on mismatch)
  const a = Buffer.from(provided, 'utf8');
  const b = Buffer.from(expected, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  next();
}

const app = express();
app.use('/webhooks', express.raw({ type: '*/*' })); // raw body, webhook routes only
app.post('/webhooks/events', verifyWebhookSignature, (req, res) => res.sendStatus(200));
