const crypto = require('crypto');
const express = require('express');
const Redis = require('ioredis');

const redis = new Redis(process.env.REDIS_URL);
const SECRETS = [process.env.WEBHOOK_SECRET_CURRENT, process.env.WEBHOOK_SECRET_PREVIOUS]
  .filter(Boolean);
const MAX_AGE_MS = 5 * 60 * 1000;
const EVENT_TTL_S = 10 * 60; // ten minutes

async function verifyWebhookSignature(req, res, next) {
  const signature = req.get('X-Signature-256');
  const timestamp = req.get('X-Signature-Timestamp');
  const eventId = req.get('X-Event-Id');

  if (!signature || !timestamp || !/^\d+$/.test(timestamp) || !eventId) {
    return res.status(401).json({ error: 'Missing or malformed headers' });
  }

  // 1. Timestamp window: five minutes
  const age = Date.now() - Number(timestamp);
  if (age < 0 || age > MAX_AGE_MS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // 2. Verify against current OR previous secret (rotation support)
  const provided = Buffer.from(signature.replace(/^sha256=/, ''), 'utf8');
  const valid = SECRETS.some((secret) => {
    const expected = Buffer.from(
      crypto.createHmac('sha256', secret)
        .update(timestamp)
        .update('.')
        .update(req.body) // raw Buffer
        .digest('hex'),
      'utf8'
    );
    return provided.length === expected.length && crypto.timingSafeEqual(provided, expected);
  });
  if (!valid) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // 3. Reject repeated event IDs for ten minutes (atomic set-if-absent)
  const claimed = await redis.set(`webhook:event:${eventId}`, '1', 'EX', EVENT_TTL_S, 'NX');
  if (claimed === null) {
    return res.status(409).json({ error: 'Duplicate event' });
  }

  next();
}

const app = express();
app.use('/webhooks', express.raw({ type: '*/*' }));
app.post('/webhooks/events', verifyWebhookSignature, (req, res) => res.sendStatus(200));
```

## FastAPI (Python)

```python
import hashlib, hmac, os, time
import redis.asyncio as redis
from fastapi import FastAPI, Request, HTTPException

app = FastAPI()
r = redis.from_url(os.environ["REDIS_URL"])
SECRETS = [s.encode() for s in (
    os.environ.get("WEBHOOK_SECRET_CURRENT"),
    os.environ.get("WEBHOOK_SECRET_PREVIOUS"),
) if s]
MAX_AGE_S = 300
EVENT_TTL_S = 600  # ten minutes

@app.middleware("http")
async def verify_webhook(request: Request, call_next):
    if not request.url.path.startswith("/webhooks"):
        return await call_next(request)

    raw = await request.body()
    sig = request.headers.get("X-Signature-256", "").removeprefix("sha256=")
    ts = request.headers.get("X-Signature-Timestamp", "")
    event_id = request.headers.get("X-Event-Id", "")

    if not sig or not ts.isdigit() or not event_id:
        raise HTTPException(401, "Missing or malformed headers")

    # 1. Five-minute timestamp window
    if abs(time.time() - int(ts)) > MAX_AGE_S:
        raise HTTPException(401, "Timestamp outside allowed window")

    # 2. Accept current OR previous secret
    payload = ts.encode() + b"." + raw
    if not any(
        hmac.compare_digest(sig, hmac.new(s, payload, hashlib.sha256).hexdigest())
        for s in SECRETS
    ):
        raise HTTPException(401, "Invalid signature")

    # 3. Reject repeated event IDs for ten minutes (atomic)
    if not await r.set(f"webhook:event:{event_id}", "1", ex=EVENT_TTL_S, nx=True):
        raise HTTPException(409, "Duplicate event")

    return await call_next(request)
```

## Design notes

- **Rotation**: both secrets are tried with constant-time comparison per candidate. During rotation, the sender switches to the new secret while receivers still accept the old; once all senders are migrated, drop `WEBHOOK_SECRET_PREVIOUS`. Keep at most two active secrets — more widens the attack surface.
- **Ordering matters**: signature is verified *before* the dedup check, so unauthenticated requests can't burn event IDs or probe which IDs exist.
- **Atomic dedup**: `SET ... NX EX` is a single atomic operation — concurrent duplicate deliveries can't both slip through, unlike a check-then-set. The 10-minute TTL comfortably outlives the 5-minute timestamp window, so any replay within the valid window is caught.
- **409 vs 401**: duplicates return `409` so legitimate senders with retry logic can distinguish "already processed" from "bad signature."
- **No Redis?** An in-memory `Map` with expiry works for a single instance, but Redis is required once you run multiple replicas — otherwise a replay hitting a different node would pass.

```typescript
// ── Configuration ────────────────────────────────────────────────
const SECRETS: string[] = [
  env("WEBHOOK_SECRET_CURRENT"),
  env("WEBHOOK_SECRET_PREVIOUS"),   // kept during rotation window
].filter(Boolean);

const MAX_TIMESTAMP_AGE_MS = 5 * 60 * 1000;   // five minutes
const EVENT_ID_TTL_SECONDS = 10 * 60;         // ten minutes

// ── Middleware ───────────────────────────────────────────────────
async function verifyWebhook(req: Request, res: Response, next: Next): Promise<void> {
  // req.rawBody: Buffer — captured by raw body parser, NEVER re-serialized
  const signature = req.header("X-Signature-256");        // "sha256=<hex>"
  const timestamp = req.header("X-Signature-Timestamp");  // unix ms
  const eventId   = req.header("X-Event-Id");

  if (!signature || !timestamp || !/^\d+$/.test(timestamp) || !eventId) {
    return res.status(401).send({ error: "Missing or malformed headers" });
  }

  // ── 1. Timestamp freshness (five-minute window, no future skew) ──
  const age = Date.now() - Number(timestamp);
  if (age < 0 || age > MAX_TIMESTAMP_AGE_MS) {
    return res.status(401).send({ error: "Stale timestamp" });
  }

  // ── 2. HMAC-SHA256 over timestamp + '.' + raw_body ─────────────
  //    Accept current OR previous secret; constant-time comparison.
  const provided = Buffer.from(signature.replace(/^sha256=/, ""), "utf8");

  const signatureValid = SECRETS.some((secret) => {
    const expected = Buffer.from(
      hmacSha256(secret, concat(timestamp, ".", req.rawBody)).hex(),
      "utf8"
    );
    return provided.length === expected.length
        && timingSafeEqual(provided, expected);
  });

  if (!signatureValid) {
    return res.status(401).send({ error: "Invalid signature" });
  }

  // ── 3. Replay protection: reject repeated event ID for 10 min ──
  //    Atomic set-if-absent; runs AFTER auth so attackers can't burn IDs.
  const claimed = await redis.set(
    `webhook:event:${eventId}`, "1",
    { EX: EVENT_ID_TTL_SECONDS, NX: true }
  );
  if (claimed === null) {
    return res.status(409).send({ error: "Duplicate event" });
  }

  next();
}

// ── Wiring ───────────────────────────────────────────────────────
app.use("/webhooks", rawBodyParser());  // raw bytes, webhook routes only
app.post("/webhooks/events", verifyWebhook, handleEvent);
```

**Behavior summary:**

| Condition | Status |
|---|---|
| Missing/malformed headers | `401` |
| Timestamp older than 5 min (or in the future) | `401` |
| Signature matches neither current nor previous secret | `401` |
| Valid signature but event ID seen within last 10 min | `409` |
| Valid signature, fresh timestamp, new event ID | → handler |

**Invariants preserved:** raw body hashed (never re-serialized), payload is exactly `timestamp + '.' + raw_body`, constant-time comparison per candidate secret, timestamp authenticated via HMAC (replay-resistant), dedup check strictly after authentication, atomic `SET NX EX` safe across replicas.

Here's a sketch (Express-style) of HMAC-SHA256 webhook verification middleware:

```javascript
const crypto = require('crypto');

function verifyWebhookSignature(secret, headerName = 'x-signature') {
  return (req, res, next) => {
    // 1. Raw body is required — parsed JSON won't do, because
    //    re-serialization can change bytes and break the MAC.
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(500).json({ error: 'raw body not captured' });
    }

    // 2. Read signature header
    const provided = req.headers[headerName];
    if (typeof provided !== 'string') {
      return res.status(401).json({ error: 'missing signature' });
    }

    // 3. Compute expected HMAC over the exact raw bytes
    const expected =
      'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

    // 4. Constant-time comparison — never use ===
    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(provided, 'utf8');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'invalid signature' });
    }

    next();
  };
}
```

Key points:

- **Raw body capture**: mount `express.raw({ type: '*/*' })` (or a body parser that stores `req.rawBody`) *before* JSON parsing, so the HMAC is computed over the exact bytes the sender signed.
- **Constant-time compare**: `crypto.timingSafeEqual` prevents timing side channels; length check first since it throws on mismatched lengths.
- **Replay protection (recommended)**: many providers (e.g., Stripe) include a timestamp in the signed payload — verify it's within a small tolerance window (e.g., 5 minutes) before accepting.
- **Secret handling**: load from env/secret manager, never hardcode; use a per-endpoint secret so compromise is contained.
- **Fail closed**: any missing/invalid signature returns 401 and the request never reaches your handler.

If you tell me the provider (Stripe, GitHub, Shopify, etc.), I can match their exact header format and signing scheme.

Here's the updated middleware with the `timestamp + '.' + raw_body` signing scheme (Stripe-style):

```javascript
const crypto = require('crypto');

const TOLERANCE_SECONDS = 5 * 60; // 5 minutes

function verifyWebhookSignature(secret, headerName = 'x-signature') {
  return (req, res, next) => {
    // 1. Raw body is required — parsed JSON won't do, because
    //    re-serialization can change bytes and break the MAC.
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(500).json({ error: 'raw body not captured' });
    }

    // 2. Parse signature header: "t=<timestamp>,v1=<hex_hmac>"
    const header = req.headers[headerName];
    if (typeof header !== 'string') {
      return res.status(401).json({ error: 'missing signature' });
    }

    let timestamp, signatures;
    try {
      const parts = header.split(',').map((kv) => {
        const [k, v] = kv.split('=');
        if (!k || !v) throw new Error('malformed');
        return [k.trim(), v.trim()];
      });
      timestamp = parts.find(([k]) => k === 't')?.[1];
      signatures = parts.filter(([k]) => k === 'v1').map(([, v]) => v);
    } catch {
      return res.status(401).json({ error: 'malformed signature header' });
    }

    if (!timestamp || signatures.length === 0) {
      return res.status(401).json({ error: 'malformed signature header' });
    }

    // 3. Reject timestamps outside the tolerance window (replay protection)
    const ts = Number(timestamp);
    if (!Number.isInteger(ts)) {
      return res.status(401).json({ error: 'invalid timestamp' });
    }
    const now = Math.floor(Date.now() / 1000);
    if (Math.abs(now - ts) > TOLERANCE_SECONDS) {
      return res.status(401).json({ error: 'timestamp outside tolerance' });
    }

    // 4. Compute expected HMAC over timestamp + '.' + raw_body
    const signedPayload = Buffer.concat([
      Buffer.from(`${timestamp}.`, 'utf8'),
      rawBody,
    ]);
    const expected =
      'sha256=' +
      crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');

    // 5. Constant-time comparison against each provided signature
    const a = Buffer.from(expected, 'utf8');
    const valid = signatures.some((sig) => {
      const b = Buffer.from(`sha256=${sig}`, 'utf8');
      return b.length === a.length && crypto.timingSafeEqual(a, b);
    });
    if (!valid) {
      return res.status(401).json({ error: 'invalid signature' });
    }

    next();
  };
}
```

Notes on the changes:

- **Signed payload**: HMAC is computed over `timestamp + '.' + raw_body`, built via `Buffer.concat` so the raw body bytes are never re-encoded.
- **Replay window**: timestamps older than 5 minutes (or in the future beyond tolerance) are rejected *before* signature comparison, so stale replays fail fast.
- **Multiple signatures**: some providers include several `v1` values (e.g., during secret rotation); each is checked with `timingSafeEqual`, and length is compared before calling it since `timingSafeEqual` throws on mismatched lengths.
- **Fail closed**: malformed headers, bad timestamps, and signature mismatches all return 401 without reaching the handler.

One caveat: this sketch trusts the timestamp from the header only because it's covered by the HMAC — the freshness check is only meaningful *after* the signature verifies. If you want strict ordering, verify the signature first and then check freshness; both orders are defensible, but the freshness check must never be the only gate.

Here's the updated middleware with secret rotation support and event ID replay protection:

```javascript
const crypto = require('crypto');

const TOLERANCE_SECONDS = 5 * 60;      // 5 minutes
const EVENT_ID_TTL_MS = 10 * 60 * 1000; // 10 minutes

// Simple in-memory cache; swap for Redis/memcached in multi-instance deployments.
const seenEvents = new Map(); // eventId -> expiry (ms epoch)

function pruneSeenEvents(now) {
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
}

function verifyWebhookSignature(secrets, headerName = 'x-signature') {
  // secrets: { current: string, previous?: string } — previous is optional
  const secretList = [secrets.current, secrets.previous].filter(Boolean);

  return (req, res, next) => {
    // 1. Raw body is required — parsed JSON won't do, because
    //    re-serialization can change bytes and break the MAC.
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(500).json({ error: 'raw body not captured' });
    }

    // 2. Parse signature header: "t=<timestamp>,v1=<hex_hmac>"
    const header = req.headers[headerName];
    if (typeof header !== 'string') {
      return res.status(401).json({ error: 'missing signature' });
    }

    let timestamp, signatures;
    try {
      const parts = header.split(',').map((kv) => {
        const [k, v] = kv.split('=');
        if (!k || !v) throw new Error('malformed');
        return [k.trim(), v.trim()];
      });
      timestamp = parts.find(([k]) => k === 't')?.[1];
      signatures = parts.filter(([k]) => k === 'v1').map(([, v]) => v);
    } catch {
      return res.status(401).json({ error: 'malformed signature header' });
    }

    if (!timestamp || signatures.length === 0) {
      return res.status(401).json({ error: 'malformed signature header' });
    }

    // 3. Timestamp sanity before HMAC work
    const ts = Number(timestamp);
    if (!Number.isInteger(ts)) {
      return res.status(401).json({ error: 'invalid timestamp' });
    }
    const now = Math.floor(Date.now() / 1000);
    if (Math.abs(now - ts) > TOLERANCE_SECONDS) {
      return res.status(401).json({ error: 'timestamp outside tolerance' });
    }

    // 4. Verify against current OR previous secret (rotation window)
    const signedPayload = Buffer.concat([
      Buffer.from(`${timestamp}.`, 'utf8'),
      rawBody,
    ]);
    const expected =
      'sha256=' +
      crypto.createHmac('sha256', secretList[0]).update(signedPayload).digest('hex');

    const a = Buffer.from(expected, 'utf8');
    const matchesSecret = (secret) => {
      const candidate =
        'sha256=' + crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');
      const c = Buffer.from(candidate, 'utf8');
      return signatures.some((sig) => {
        const b = Buffer.from(`sha256=${sig}`, 'utf8');
        return b.length === c.length && crypto.timingSafeEqual(c, b);
      });
    };

    if (!secretList.some(matchesSecret)) {
      return res.status(401).json({ error: 'invalid signature' });
    }

    // 5. Event ID replay protection (10-minute window)
    const eventId = req.headers['x-event-id'];
    if (typeof eventId !== 'string' || eventId.length === 0 || eventId.length > 256) {
      return res.status(401).json({ error: 'missing or invalid event id' });
    }
    const nowMs = Date.now();
    pruneSeenEvents(nowMs);
    const expiry = seenEvents.get(eventId);
    if (expiry !== undefined && expiry > nowMs) {
      return res.status(409).json({ error: 'duplicate event' });
    }
    seenEvents.set(eventId, nowMs + EVENT_ID_TTL_MS);

    next();
  };
}
```

Notes on the changes:

- **Secret rotation**: the middleware accepts a signature produced by either the current or previous secret, so in-flight events signed with the old secret still verify during the rotation window. Once you're confident all senders have switched, drop `previous`. Each candidate secret's HMAC is compared with `timingSafeEqual` — never compare secrets or signatures with `===`.
- **Event ID dedup**: after the signature verifies, the event ID is checked against a 10-minute TTL cache. The check-then-set here is not atomic; under concurrent delivery (or multiple app instances) two requests could race past the check. For production, use an atomic store — e.g., Redis `SET key 1 NX EX 600` — rather than this in-process `Map`.
- **Ordering**: signature verification happens *before* the replay check, so unauthenticated requests can't pollute the dedup cache (an attacker can't DoS legitimate event IDs by spamming forged requests with them).
- **Event ID source**: I assumed an `x-event-id` header; if your provider embeds the event ID in the payload body instead, parse it from the raw body after signature verification — same ordering principle applies.

One caveat: the in-memory cache only works for a single process. If you run multiple instances or restart frequently, replays can slip through — move the dedup state to a shared store with atomic set-if-absent semantics.

```typescript
// webhookVerification.ts — final pseudocode

import { createHmac, timingSafeEqual } from 'crypto';

const TOLERANCE_SECONDS = 5 * 60;        // reject timestamps older than 5 min
const EVENT_ID_TTL_SECONDS = 10 * 60;    // reject repeated event IDs for 10 min

interface Secrets {
  current: string;
  previous?: string; // optional, during rotation window
}

interface WebhookRequest {
  rawBody: Buffer | undefined;          // exact bytes as received
  headers: Record<string, string | undefined>;
}

interface WebhookResponse {
  status: (code: 401 | 409 | 500) => WebhookResponse;
  json: (body: { error: string }) => void;
}

type Next = () => void;

// Dedup store — must be atomic set-if-absent in production (e.g., Redis SET NX EX).
// In-process Map shown for clarity; unsafe across instances/restarts.
const seenEvents = new Map<string, number>(); // eventId -> expiry (epoch seconds)

function pruneSeenEvents(nowSec: number): void {
  for (const [id, expiry] of seenEvents) {
    if (expiry <= nowSec) seenEvents.delete(id);
  }
}

function parseSignatureHeader(
  header: string
): { timestamp: string; signatures: string[] } | null {
  let timestamp: string | undefined;
  const signatures: string[] = [];

  for (const kv of header.split(',')) {
    const eq = kv.indexOf('=');
    if (eq === -1) return null;
    const key = kv.slice(0, eq).trim();
    const value = kv.slice(eq + 1).trim();
    if (key === '' || value === '') return null;
    if (key === 't') timestamp = value;
    else if (key === 'v1') signatures.push(value);
  }

  if (timestamp === undefined || signatures.length === 0) return null;
  return { timestamp, signatures };
}

function hmacMatches(
  secret: string,
  timestamp: string,
  rawBody: Buffer,
  signatures: string[]
): boolean {
  // Sign exactly: timestamp + '.' + raw_body (raw bytes, never re-serialized)
  const signedPayload = Buffer.concat([
    Buffer.from(`${timestamp}.`, 'utf8'),
    rawBody,
  ]);
  const expected =
    'sha256=' + createHmac('sha256', secret).update(signedPayload).digest('hex');

  const a = Buffer.from(expected, 'utf8');
  return signatures.some((sig) => {
    const b = Buffer.from(`sha256=${sig}`, 'utf8');
    // Length check first: timingSafeEqual throws on length mismatch
    return b.length === a.length && timingSafeEqual(a, b);
  });
}

export function verifyWebhookSignature(
  secrets: Secrets,
  headerName: string = 'x-signature',
  eventIdHeader: string = 'x-event-id'
) {
  const secretList: string[] = [secrets.current, secrets.previous].filter(
    (s): s is string => s !== undefined
  );

  return (req: WebhookRequest, res: WebhookResponse, next: Next): void => {
    // --- 1. Raw body must have been captured before any body parser ---
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      res.status(500).json({ error: 'raw body not captured' });
      return;
    }

    // --- 2. Parse signature header: "t=<unix_ts>,v1=<hex_hmac>[,v1=...] ---
    const header = req.headers[headerName];
    if (typeof header !== 'string') {
      res.status(401).json({ error: 'missing signature' });
      return;
    }
    const parsed = parseSignatureHeader(header);
    if (parsed === null) {
      res.status(401).json({ error: 'malformed signature header' });
      return;
    }
    const { timestamp, signatures } = parsed;

    // --- 3. Timestamp freshness: reject stale (or far-future) timestamps ---
    const ts = Number(timestamp);
    if (!Number.isInteger(ts)) {
      res.status(401).json({ error: 'invalid timestamp' });
      return;
    }
    const nowSec = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSec - ts) > TOLERANCE_SECONDS) {
      res.status(401).json({ error: 'timestamp outside tolerance' }); // 401
      return;
    }

    // --- 4. Verify HMAC against current OR previous secret ---
    const signatureValid = secretList.some((secret) =>
      hmacMatches(secret, timestamp, rawBody, signatures)
    );
    if (!signatureValid) {
      res.status(401).json({ error: 'invalid signature' }); // 401
      return;
    }

    // --- 5. Event ID replay protection (only after auth succeeds) ---
    const eventId = req.headers[eventIdHeader];
    if (
      typeof eventId !== 'string' ||
      eventId.length === 0 ||
      eventId.length > 256
    ) {
      res.status(401).json({ error: 'missing or invalid event id' });
      return;
    }
    pruneSeenEvents(nowSec);
    const existingExpiry = seenEvents.get(eventId);
    if (existingExpiry !== undefined && existingExpiry > nowSec) {
      res.status(409).json({ error: 'duplicate event' }); // 409
      return;
    }
    seenEvents.set(eventId, nowSec + EVENT_ID_TTL_SECONDS);

    next();
  };
}
```

Summary of behavior:

| Condition | Status |
|---|---|
| Raw body missing | 500 (server misconfiguration) |
| Missing/malformed signature header | 401 |
| Timestamp stale or > 5 min in future | 401 |
| HMAC fails against both secrets | 401 |
| Event ID seen within last 10 min | 409 |

Security invariants preserved:

- HMAC computed over `timestamp + '.' + raw_body` using the exact raw bytes.
- Constant-time comparison (`timingSafeEqual`) with a length pre-check; no `===` on secrets or signatures.
- Accepts current or previous secret for rotation; drop `previous` once rotation completes.
- Replay check runs only after signature verification, so unauthenticated requests can't poison the dedup cache.
- Fail closed on every error path.

Caveat: the in-process `Map` is not atomic and not shared across instances — replace with Redis `SET key 1 NX EX 600` (or equivalent) for production, and consider returning 409 only when the stored event matches, or 200 with an idempotent no-op, depending on how your provider treats duplicate deliveries.

Here's a sketch (Node.js/Express) that verifies an HMAC-SHA256 webhook signature against the **raw** request body:

```js
const crypto = require("crypto");

// Raw body capture must happen BEFORE any JSON parsing middleware.
// Use express.raw({ type: "*/*" }) for the webhook route only.
app.post(
  "/webhooks/provider",
  express.raw({ type: "*/*", limit: "1mb" }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString("utf8"));
    // ... handle event
    res.status(200).json({ received: true });
  }
);

function verifyWebhookSignature(req, res, next) {
  const secret = process.env.WEBHOOK_SIGNING_SECRET;
  if (!secret) {
    console.error("Webhook signing secret not configured");
    return res.status(500).end();
  }

  const signatureHeader = req.get("X-Provider-Signature"); // e.g. "sha256=<hex>"
  if (!signatureHeader) {
    return res.status(401).end();
  }

  const [scheme, providedSig] = signatureHeader.split("=", 2);
  if (scheme !== "sha256" || !providedSig) {
    return res.status(401).end();
  }

  // Compute HMAC over the RAW bytes — not the parsed/re-serialized body.
  const expected = crypto
    .createHmac("sha256", secret)
    .update(req.body) // req.body is a Buffer from express.raw
    .digest("hex");

  const provided = Buffer.from(providedSig, "utf8");
  const expectedBuf = Buffer.from(expected, "utf8");

  // Length check first, then constant-time comparison to avoid timing leaks.
  if (
    provided.length !== expectedBuf.length ||
    !crypto.timingSafeEqual(provided, expectedBuf)
  ) {
    return res.status(401).end();
  }

  next();
}
```

Key security points:

1. **Raw body only** — HMAC must be computed over the exact bytes the sender signed. If `express.json()` runs first, re-serialization (key order, whitespace, unicode escaping) can break or, worse, mask tampering. That's why `express.raw()` is scoped to this route and placed first.
2. **Constant-time comparison** — `crypto.timingSafeEqual` prevents timing side channels; a length check guards against the exception it throws on mismatched lengths.
3. **Fail closed** — missing/malformed headers, missing secret config, or any mismatch returns 401/500 without processing.
4. **Limit body size** — prevents DoS via huge payloads before verification.
5. **Replay protection (extension)** — if the provider includes a timestamp (e.g., `t=<ts>,v1=<sig>` like Stripe), verify the timestamp is within a small tolerance window (e.g., 5 minutes) and include it in the signed payload. The sketch above is the minimal version; add this if your provider supports it.
6. **Secret handling** — loaded from env/secret manager, never hardcoded or logged.

If your provider uses a different header name or signature format (e.g., base64 digests, multiple versioned signatures), adjust the parsing accordingly — the core pattern (raw bytes → HMAC → constant-time compare) stays the same.

Updated sketch with the timestamped signed payload (`timestamp + '.' + raw_body`), a five-minute replay window, and constant-time comparison:

```js
const crypto = require("crypto");

const TOLERANCE_SECONDS = 5 * 60; // reject timestamps older than 5 minutes

app.post(
  "/webhooks/provider",
  express.raw({ type: "*/*", limit: "1mb" }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString("utf8"));
    // ... handle event
    res.status(200).json({ received: true });
  }
);

function verifyWebhookSignature(req, res, next) {
  const secret = process.env.WEBHOOK_SIGNING_SECRET;
  if (!secret) {
    console.error("Webhook signing secret not configured");
    return res.status(500).end();
  }

  // Header format: t=<unix_seconds>,v1=<hex_hmac>
  const header = req.get("X-Provider-Signature");
  if (!header) {
    return res.status(401).end();
  }

  const parts = Object.fromEntries(
    header.split(",").map((kv) => kv.split("=", 2))
  );
  const timestamp = parts["t"];
  const providedSig = parts["v1"];

  if (!timestamp || !providedSig || !/^\d+$/.test(timestamp)) {
    return res.status(401).end();
  }

  // Replay protection: reject timestamps outside the tolerance window.
  const tsSeconds = Number(timestamp);
  const nowSeconds = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSeconds - tsSeconds) > TOLERANCE_SECONDS) {
    return res.status(401).end();
  }

  // Signed payload = timestamp + '.' + raw_body (raw bytes, not re-serialized).
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + ".", "utf8"),
    req.body, // Buffer from express.raw
  ]);

  const expected = crypto
    .createHmac("sha256", secret)
    .update(signedPayload)
    .digest("hex");

  const provided = Buffer.from(providedSig, "utf8");
  const expectedBuf = Buffer.from(expected, "utf8");

  // Length check first (timingSafeEqual throws on length mismatch),
  // then constant-time comparison.
  if (
    provided.length !== expectedBuf.length ||
    !crypto.timingSafeEqual(provided, expectedBuf)
  ) {
    return res.status(401).end();
  }

  next();
}
```

Notes on the changes:

1. **Signed payload construction** — the HMAC input is exactly `timestamp + "." + raw_body`, matching the sender. The timestamp is taken from the header (the value that was signed), never from the body, so an attacker can't substitute a fresh timestamp with an old signature.
2. **Replay window** — timestamps older than (or too far ahead of) five minutes are rejected before signature verification. `Math.abs` covers clock skew in both directions; tighten or loosen as your provider documents.
3. **Constant-time comparison** — `crypto.timingSafeEqual` with a prior length check, as before.
4. **Strict timestamp parsing** — the `/^\d+$/` regex rejects negative numbers, floats, and injection attempts before `Number()` conversion.
5. **Raw body preserved** — `express.raw()` still runs first so the bytes hashed are the bytes signed.

One caveat: if your provider's header format differs (e.g., base64 signatures, multiple `v1` entries for key rotation), adjust the parsing — but keep the verify-then-compare structure intact.

Updated sketch with secret rotation (accept current or previous) and event ID deduplication (10-minute window):

```js
const crypto = require("crypto");

const TOLERANCE_SECONDS = 5 * 60; // timestamp tolerance
const EVENT_TTL_MS = 10 * 60 * 1000; // event ID dedup window

// Secrets: current first, previous second (during rotation both are valid).
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SIGNING_SECRET_CURRENT,
  process.env.WEBHOOK_SIGNING_SECRET_PREVIOUS,
].filter(Boolean);

if (WEBHOOK_SECRETS.length === 0) {
  throw new Error("No webhook signing secrets configured");
}

// Simple in-process dedup cache. For multi-instance deployments, use a
// shared store (e.g., Redis SET with TTL) instead.
const seenEvents = new Map(); // eventId -> expiry timestamp

function isDuplicateEvent(eventId) {
  const now = Date.now();

  // Opportunistic cleanup of expired entries.
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }

  if (seenEvents.has(eventId)) {
    return true;
  }
  seenEvents.set(eventId, now + EVENT_TTL_MS);
  return false;
}

app.post(
  "/webhooks/provider",
  express.raw({ type: "*/*", limit: "1mb" }),
  verifyWebhookSignature,
  (req, res) => {
    const event = JSON.parse(req.body.toString("utf8"));

    // Dedup AFTER signature verification (eventId is now trustworthy).
    const eventId = event.id;
    if (typeof eventId === "string" && eventId.length > 0) {
      if (isDuplicateEvent(eventId)) {
        return res.status(200).json({ received: true, duplicate: true });
      }
    }

    // ... handle event
    res.status(200).json({ received: true });
  }
);

function verifyWebhookSignature(req, res, next) {
  // Header format: t=<unix_seconds>,v1=<hex_hmac>
  const header = req.get("X-Provider-Signature");
  if (!header) {
    return res.status(401).end();
  }

  const parts = Object.fromEntries(
    header.split(",").map((kv) => kv.split("=", 2))
  );
  const timestamp = parts["t"];
  const providedSig = parts["v1"];

  if (!timestamp || !providedSig || !/^\d+$/.test(timestamp)) {
    return res.status(401).end();
  }

  // Replay protection: reject timestamps outside the tolerance window.
  const tsSeconds = Number(timestamp);
  const nowSeconds = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSeconds - tsSeconds) > TOLERANCE_SECONDS) {
    return res.status(401).end();
  }

  // Signed payload = timestamp + '.' + raw_body.
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + ".", "utf8"),
    req.body,
  ]);

  // Try each known secret; accept if any verifies. Constant-time compare
  // per candidate; iterating 2 secrets does not leak which one matched.
  const provided = Buffer.from(providedSig, "utf8");
  let verified = false;
  for (const secret of WEBHOOK_SECRETS) {
    const expected = crypto
      .createHmac("sha256", secret)
      .update(signedPayload)
      .digest("hex");
    const expectedBuf = Buffer.from(expected, "utf8");
    if (
      provided.length === expectedBuf.length &&
      crypto.timingSafeEqual(provided, expectedBuf)
    ) {
      verified = true;
      break;
    }
  }

  if (!verified) {
    return res.status(401).end();
  }

  next();
}
```

Notes on the changes:

1. **Secret rotation** — `WEBHOOK_SECRETS` holds the current and previous secrets; a signature matching either is accepted. Each candidate is compared with `crypto.timingSafeEqual`, so no timing oracle distinguishes a valid from invalid secret. Once the rotation window closes, drop the previous secret from config.
2. **Dedup ordering matters** — the event ID is only checked *after* signature verification. Before verification, a body-supplied ID is attacker-controlled and could be used to poison the cache (e.g., replaying a legitimate event's ID to suppress processing of a new one).
3. **Duplicates return 200** — replying success to a duplicate prevents provider-side retry storms; the event is simply not reprocessed.
4. **Cache scope caveat** — the in-process `Map` only dedups within one process. If you run multiple instances, replace it with a shared store (Redis `SET key value EX 600 NX` is a natural fit) so dedup is global.
5. **Retained guarantees** — raw-body HMAC over `timestamp + '.' + raw_body`, five-minute timestamp window, constant-time comparison, strict timestamp parsing, and fail-closed behavior are all unchanged.

Final TypeScript-style pseudocode:

```ts
import crypto from "crypto";
import express, { Request, Response, NextFunction } from "express";

// ---------- Configuration ----------

const TOLERANCE_SECONDS = 5 * 60; // reject timestamps older than 5 minutes
const EVENT_TTL_MS = 10 * 60 * 1000; // event ID dedup window

// Current secret first, previous second (both valid during rotation).
const WEBHOOK_SECRETS: string[] = [
  process.env.WEBHOOK_SIGNING_SECRET_CURRENT,
  process.env.WEBHOOK_SIGNING_SECRET_PREVIOUS,
].filter((s): s is string => Boolean(s));

if (WEBHOOK_SECRETS.length === 0) {
  throw new Error("No webhook signing secrets configured");
}

// ---------- Event dedup cache ----------
// In-process for illustration; use a shared store (e.g., Redis SET NX EX 600)
// for multi-instance deployments.

const seenEvents = new Map<string, number>(); // eventId -> expiry (ms)

function isDuplicateEvent(eventId: string): boolean {
  const now = Date.now();
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_TTL_MS);
  return false;
}

// ---------- Types ----------

interface WebhookEvent {
  id: string;
  [key: string]: unknown;
}

interface SignatureHeaderParts {
  t: string;
  v1: string;
}

// ---------- Signature parsing ----------

function parseSignatureHeader(header: string): SignatureHeaderParts | null {
  const parts = new Map<string, string>();
  for (const kv of header.split(",")) {
    const [key, value] = kv.split("=", 2);
    if (key === undefined || value === undefined) return null;
    parts.set(key, value);
  }
  const t = parts.get("t");
  const v1 = parts.get("v1");
  if (!t || !v1 || !/^\d+$/.test(t)) return null;
  return { t, v1 };
}

// ---------- HMAC verification ----------

function verifySignature(
  signedPayload: Buffer,
  providedSigHex: string,
  secrets: string[]
): boolean {
  const provided = Buffer.from(providedSigHex, "utf8");
  for (const secret of secrets) {
    const expected = crypto
      .createHmac("sha256", secret)
      .update(signedPayload)
      .digest("hex");
    const expectedBuf = Buffer.from(expected, "utf8");
    // Length check first (timingSafeEqual throws on mismatch), then
    // constant-time comparison.
    if (
      provided.length === expectedBuf.length &&
      crypto.timingSafeEqual(provided, expectedBuf)
    ) {
      return true;
    }
  }
  return false;
}

// ---------- Middleware ----------

function verifyWebhookSignature(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  const header = req.get("X-Provider-Signature");
  if (!header) {
    res.status(401).end();
    return;
  }

  const parsed = parseSignatureHeader(header);
  if (!parsed) {
    res.status(401).end();
    return;
  }

  const { t: timestamp, v1: providedSig } = parsed;

  // Replay window: reject timestamps outside the 5-minute tolerance.
  const tsSeconds = Number(timestamp);
  const nowSeconds = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSeconds - tsSeconds) > TOLERANCE_SECONDS) {
    res.status(401).end(); // stale timestamp
    return;
  }

  // Signed payload = timestamp + '.' + raw_body (raw bytes, never re-serialized).
  const signedPayload = Buffer.concat([
    Buffer.from(timestamp + ".", "utf8"),
    req.body as Buffer,
  ]);

  // Accept signature from current OR previous secret.
  if (!verifySignature(signedPayload, providedSig, WEBHOOK_SECRETS)) {
    res.status(401).end(); // bad signature
    return;
  }

  next();
}

// ---------- Routes ----------

const app = express();

app.post(
  "/webhooks/provider",
  express.raw({ type: "*/*", limit: "1mb" }), // raw body BEFORE any parsing
  verifyWebhookSignature,
  (req: Request, res: Response) => {
    let event: WebhookEvent;
    try {
      event = JSON.parse((req.body as Buffer).toString("utf8"));
    } catch {
      res.status(400).end();
      return;
    }

    // Dedup AFTER signature verification — the event ID is now trustworthy.
    // Before verification it is attacker-controlled and could poison the cache.
    if (typeof event.id === "string" && event.id.length > 0) {
      if (isDuplicateEvent(event.id)) {
        res.status(409).json({ error: "duplicate event" }); // replay
        return;
      }
    }

    // ... handle event
    res.status(200).json({ received: true });
  }
);
```

Status code summary:

| Condition | Response |
|---|---|
| Missing/malformed signature header | 401 |
| Stale timestamp (> 5 min off) | 401 |
| Signature fails against all configured secrets | 401 |
| Valid signature, repeated event ID within 10 min | 409 |
| Valid, fresh, unseen event | 200 |

Security invariants preserved:

1. **Raw body HMAC** — signature computed over `timestamp + '.' + raw_body` using the exact bytes received (`express.raw()` runs before any parsing).
2. **Timestamp from header, not body** — attackers can't refresh a stale signature by editing the body.
3. **Constant-time comparison** — `crypto.timingSafeEqual` with a prior length check, applied per candidate secret; iterating current/previous secrets leaks nothing.
4. **Dedup after verification** — event IDs are only cached once the signature is trusted, preventing cache poisoning.
5. **Fail closed** — any missing config, malformed input, or verification failure rejects the request without processing.

Here's a sketch (Node.js/Express) with the key security details baked in:

```js
import crypto from "node:crypto";

// Store the secret in config/env — never hardcode, never commit.
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
if (!WEBHOOK_SECRET) throw new Error("WEBHOOK_SECRET not configured");

const WEBHOOK_TOLERANCE_SECONDS = 300; // replay window

export function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get("X-Signature-256");
  if (!signatureHeader) {
    return res.status(401).json({ error: "missing signature" });
  }

  // Parse "t=<timestamp>,v1=<hex>" style header (adjust to your provider's format)
  const parts = Object.fromEntries(
    signatureHeader.split(",").map((p) => p.split("="))
  );
  const timestamp = parts.t;
  const receivedSig = parts.v1;

  if (!timestamp || !receivedSig) {
    return res.status(401).json({ error: "malformed signature" });
  }

  // Replay protection: reject stale timestamps
  const age = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (!Number.isFinite(age) || age > WEBHOOK_TOLERANCE_SECONDS) {
    return res.status(401).json({ error: "stale timestamp" });
  }

  // Sign over timestamp + raw body (per provider spec)
  const signedPayload = `${timestamp}.${req.rawBody}`;
  const expected = crypto
    .createHmac("sha256", WEBHOOK_SECRET)
    .update(signedPayload)
    .digest("hex");

  const expectedBuf = Buffer.from(expected, "utf8");
  const receivedBuf = Buffer.from(receivedSig, "utf8");

  // Length check first: timingSafeEqual throws on mismatched lengths
  if (
    expectedBuf.length !== receivedBuf.length ||
    !crypto.timingSafeEqual(expectedBuf, receivedBuf)
  ) {
    return res.status(401).json({ error: "invalid signature" });
  }

  next();
}
```

And the raw-body capture, which must run **before** any JSON parsing:

```js
app.use(
  express.json({
    verify: (req, _res, buf) => {
      req.rawBody = buf; // keep the exact bytes the sender signed
    },
  })
);

app.post("/webhooks/provider", verifyWebhookSignature, handler);
```

Key points to preserve:

1. **Raw body, not re-serialized JSON** — `JSON.parse` → `JSON.stringify` can reorder keys or change whitespace, breaking the signature. Capture bytes in `verify`.
2. **Constant-time comparison** — `crypto.timingSafeEqual`, never `===` on the hex strings.
3. **Timestamp in the signed payload + tolerance window** — prevents captured requests from being replayed indefinitely.
4. **Fail closed** — missing/malformed headers are 401, and never log the secret or full signature material in error paths.
5. **Secret rotation** — if the provider supports multiple active secrets, try each and accept on any valid match, so rotation doesn't drop in-flight webhooks.

The exact header name, signed-payload format, and tolerance depend on the provider's spec — adjust those three lines accordingly.

That matches the sketch — here's the tightened version with those exact requirements locked in:

```js
import crypto from "node:crypto";

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
if (!WEBHOOK_SECRET) throw new Error("WEBHOOK_SECRET not configured");

const MAX_AGE_SECONDS = 300; // five minutes, hard limit

export function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.get("X-Signature-256");
  if (!signatureHeader) {
    return res.status(401).json({ error: "missing signature" });
  }

  // Header format: "t=<unix_seconds>,v1=<hex>"
  const parts = Object.fromEntries(
    signatureHeader.split(",").map((p) => p.split("="))
  );
  const timestamp = parts.t;
  const receivedSig = parts.v1;

  if (!timestamp || !receivedSig) {
    return res.status(401).json({ error: "malformed signature" });
  }

  const ts = Number(timestamp);
  if (!Number.isInteger(ts)) {
    return res.status(401).json({ error: "malformed timestamp" });
  }

  // Reject anything older than five minutes.
  // (Using Math.abs also rejects timestamps in the future — prevents
  // an attacker setting a far-future timestamp to bypass the age check.)
  const age = Math.floor(Date.now() / 1000) - ts;
  if (Math.abs(age) > MAX_AGE_SECONDS) {
    return res.status(401).json({ error: "stale timestamp" });
  }

  // Signed payload is exactly: timestamp + '.' + raw_body
  const signedPayload = `${timestamp}.${req.rawBody}`;
  const expected = crypto
    .createHmac("sha256", WEBHOOK_SECRET)
    .update(signedPayload)
    .digest("hex");

  const expectedBuf = Buffer.from(expected, "utf8");
  const receivedBuf = Buffer.from(receivedSig, "utf8");

  // timingSafeEqual throws on length mismatch, so check length first.
  // Length itself leaks nothing useful to an attacker here.
  if (
    expectedBuf.length !== receivedBuf.length ||
    !crypto.timingSafeEqual(expectedBuf, receivedBuf)
  ) {
    return res.status(401).json({ error: "invalid signature" });
  }

  next();
}
```

