  // (adjust names to match your provider).
  const timestamp = req.get('X-Webhook-Timestamp');
  const signature = (req.get('X-Webhook-Signature') || '').replace(/^sha256=/, '');

  // 1. Validate timestamp format and reject stale timestamps (replay protection).
  const ts = Number(timestamp);
  if (!Number.isInteger(ts) || ts <= 0) {
    return res.status(401).json({ error: 'Invalid timestamp' });
  }
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - ts) > REPLAY_WINDOW_SECONDS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // 2. Validate signature format before comparison.
  if (!signature || !/^[a-f0-9]{64}$/i.test(signature)) {
    return res.status(401).json({ error: 'Invalid signature format' });
  }

  // 3. Compute HMAC over timestamp + '.' + raw body (raw bytes, not parsed JSON).
  const computed = crypto.createHmac('sha256', WEBHOOK_SECRET)
    .update(`${timestamp}.${rawBody}`)
    .digest('hex');

  // 4. Constant-time comparison.
  const a = Buffer.from(computed, 'utf8');
  const b = Buffer.from(signature, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: 'Signature verification failed' });
  }

  next();
}

// router.post('/webhooks/provider', verifyWebhookSignature, handler);
```

Notes on the changes:

- **Signed payload construction** — the HMAC now covers `timestamp + '.' + raw_body`, so the timestamp itself is authenticated. An attacker can't strip or alter the timestamp without invalidating the signature.
- **Replay window** — timestamps older (or further in the future) than five minutes are rejected. Using `Math.abs` also blocks far-future timestamps, which prevents an attacker from obtaining a signature now and replaying it much later.
- **Order of checks** — timestamp is validated before the HMAC so stale requests are rejected cheaply, but the timestamp is still verified as part of the signed payload, so the check can't be bypassed by tampering.
- **Clock skew** — if your server's clock drifts, legitimate webhooks will fail. Sync via NTP; don't widen the window to compensate.
- **Constant-time comparison** — unchanged: length check, then `crypto.timingSafeEqual`.

Updated sketch with secret rotation and event ID deduplication:

```js
const crypto = require('crypto');

// Current and previous secrets, both from config. Never hardcode or log.
// Order matters: try current first so it's the one used for new signatures.
const WEBHOOK_SECRETS = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter(Boolean);

if (WEBHOOK_SECRETS.length === 0) {
  throw new Error('No webhook secrets configured');
}

const REPLAY_WINDOW_SECONDS = 5 * 60;   // timestamp freshness
const EVENT_ID_TTL_MS = 10 * 60 * 1000; // event ID dedup window

// In-memory seen-event cache. Use Redis or similar in multi-instance
// deployments — a per-process Map won't dedupe across replicas.
const seenEvents = new Map(); // eventId -> expiry timestamp

function isDuplicateEvent(eventId) {
  const now = Date.now();

  // Opportunistic cleanup of expired entries.
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }

  const expiry = seenEvents.get(eventId);
  if (expiry !== undefined) return true;

  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

function verifyWebhookSignature(req, res, next) {
  const rawBody = req.rawBody;
  if (!rawBody) {
    return res.status(500).json({ error: 'Raw body not captured' });
  }

  const timestamp = req.get('X-Webhook-Timestamp');
  const eventId = req.get('X-Webhook-Event-Id');
  const signature = (req.get('X-Webhook-Signature') || '').replace(/^sha256=/, '');

  // 1. Timestamp freshness (replay window).
  const ts = Number(timestamp);
  if (!Number.isInteger(ts) || ts <= 0) {
    return res.status(401).json({ error: 'Invalid timestamp' });
  }
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - ts) > REPLAY_WINDOW_SECONDS) {
    return res.status(401).json({ error: 'Timestamp outside allowed window' });
  }

  // 2. Signature format check.
  if (!signature || !/^[a-f0-9]{64}$/i.test(signature)) {
    return res.status(401).json({ error: 'Invalid signature format' });
  }

  // 3. Try each configured secret; accept if any verifies.
  //    Constant-time comparison is used for every candidate.
  const provided = Buffer.from(signature, 'utf8');
  let verified = false;
  for (const secret of WEBHOOK_SECRETS) {
    const computed = crypto.createHmac('sha256', secret)
      .update(`${timestamp}.${rawBody}`)
      .digest('hex');
    const expected = Buffer.from(computed, 'utf8');
    if (expected.length === provided.length && crypto.timingSafeEqual(expected, provided)) {
      verified = true;
      break;
    }
  }
  if (!verified) {
    return res.status(401).json({ error: 'Signature verification failed' });
  }

  // 4. Event ID dedup — only AFTER signature verification, so an attacker
  //    can't poison the cache with forged event IDs.
  if (!eventId || typeof eventId !== 'string' || eventId.length > 256) {
    return res.status(401).json({ error: 'Missing or invalid event ID' });
  }
  if (isDuplicateEvent(eventId)) {
    return res.status(409).json({ error: 'Duplicate event ID' });
  }

  next();
}

// router.post('/webhooks/provider', verifyWebhookSignature, handler);
```

Notes on the changes:

- **Secret rotation** — both current and previous secrets are tried; a signature from either is accepted. This gives you a zero-downtime rotation window: deploy the new secret as "current," let the provider switch over, then drop the old one. Keep the list short (two) — every additional secret is another key to verify against and another to protect.
- **Constant-time per candidate** — each secret's HMAC is compared with `timingSafeEqual`. The loop structure doesn't leak which secret matched, since the response is identical either way.
- **Event ID check placement** — dedup happens *after* signature verification. Checking first would let unauthenticated attackers burn arbitrary event IDs into the cache, causing you to silently drop legitimate deliveries that happen to reuse an ID.
- **Dedup semantics** — a duplicate returns 409 rather than 401: the request authenticated fine, it's just a repeat. If your provider retries on non-2xx, you may prefer returning 200 and skipping the handler instead, so retries don't loop.
- **Cache scope** — the in-memory `Map` is fine for a single process; use Redis with a 10-minute TTL (`SET key value EX 600 NX`) for multi-instance deployments, otherwise each replica keeps its own view and duplicates slip through.

```ts
// webhookVerification.ts
import { createHmac, timingSafeEqual } from 'crypto';

// ---------- Configuration ----------

// Current and previous secrets, from config only. Never hardcode or log.
const WEBHOOK_SECRETS: readonly string[] = [
  process.env.WEBHOOK_SECRET_CURRENT,
  process.env.WEBHOOK_SECRET_PREVIOUS,
].filter((s): s is string => typeof s === 'string' && s.length > 0);

if (WEBHOOK_SECRETS.length === 0) {
  throw new Error('No webhook secrets configured');
}

const REPLAY_WINDOW_SECONDS = 5 * 60;    // timestamp freshness
const EVENT_ID_TTL_MS = 10 * 60 * 1000;  // event ID dedup window

// ---------- Types ----------

interface WebhookRequest {
  method: string;
  rawBody: Buffer;                 // captured BEFORE any JSON parsing
  headers: Record<string, string | undefined>;
}

interface WebhookResponse {
  status(code: number): WebhookResponse;
  json(body: object): void;
}

type NextFn = () => void;

// ---------- Event ID dedup store ----------

// In-memory for a single process. Use Redis (SET key val EX 600 NX)
// in multi-instance deployments.
const seenEvents = new Map<string, number>(); // eventId -> expiry (ms)

function isDuplicateEvent(eventId: string): boolean {
  const now = Date.now();
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
  if (seenEvents.has(eventId)) return true;
  seenEvents.set(eventId, now + EVENT_ID_TTL_MS);
  return false;
}

// ---------- Helpers ----------

function constantTimeHexEqual(a: string, b: string): boolean {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  return bufA.length === bufB.length && timingSafeEqual(bufA, bufB);
}

function signatureIsValid(
  secrets: readonly string[],
  signedPayload: string,
  providedSignature: string,
): boolean {
  for (const secret of secrets) {
    const computed = createHmac('sha256', secret)
      .update(signedPayload)
      .digest('hex');
    if (constantTimeHexEqual(computed, providedSignature)) {
      return true;
    }
  }
  return false;
}

// ---------- Middleware ----------

export function verifyWebhookSignature(
  req: WebhookRequest,
  res: WebhookResponse,
  next: NextFn,
): void {
  // 0. Raw body must have been captured pre-parse.
  if (!req.rawBody || req.rawBody.length === 0) {
    res.status(500).json({ error: 'Raw body not captured' });
    return;
  }

  const timestampHeader = req.headers['x-webhook-timestamp'];
  const eventId = req.headers['x-webhook-event-id'];
  const signature = (req.headers['x-webhook-signature'] ?? '')
    .replace(/^sha256=/, '');

  // 1. Timestamp freshness — 401 on stale/invalid.
  const ts = Number(timestampHeader);
  if (!Number.isInteger(ts) || ts <= 0) {
    res.status(401).json({ error: 'Invalid timestamp' });
    return;
  }
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - ts) > REPLAY_WINDOW_SECONDS) {
    res.status(401).json({ error: 'Timestamp outside allowed window' });
    return;
  }

  // 2. Signature format check — 401 on malformed.
  if (!/^[a-f0-9]{64}$/i.test(signature)) {
    res.status(401).json({ error: 'Invalid signature format' });
    return;
  }

  // 3. HMAC over timestamp + '.' + raw body, tried against current
  //    and previous secrets. Constant-time comparison throughout.
  const signedPayload = `${timestampHeader}.${req.rawBody.toString('latin1')}`;
  if (!signatureIsValid(WEBHOOK_SECRETS, signedPayload, signature)) {
    res.status(401).json({ error: 'Signature verification failed' });
    return;
  }

  // 4. Event ID dedup — only after authentication, so attackers can't
  //    poison the cache. 409 on replay.
  if (!eventId || eventId.length === 0 || eventId.length > 256) {
    res.status(401).json({ error: 'Missing or invalid event ID' });
    return;
  }
  if (isDuplicateEvent(eventId)) {
    res.status(409).json({ error: 'Duplicate event ID' });
    return;
  }

  next();
}

// Mount: router.post('/webhooks/provider', verifyWebhookSignature, handler);
// Body parsing must preserve raw bytes, e.g.:
//   app.use(express.json({
//     verify: (req, _res, buf) => { (req as any).rawBody = buf; },
//   }));
```

Summary of the final behavior:

| Condition | Status |
|---|---|
| Raw body missing (server misconfiguration) | 500 |
| Invalid/stale timestamp | 401 |
| Malformed signature | 401 |
| Signature fails against all configured secrets | 401 |
| Missing/oversized event ID | 401 |
| Repeated event ID within 10 minutes | 409 |

Security properties preserved from earlier turns:

- HMAC computed over `timestamp + '.' + raw_body` using the exact raw bytes, never re-serialized JSON.
- Constant-time comparison (`timingSafeEqual`) with a length pre-check for every candidate secret.
- Timestamp freshness window of five minutes, enforced with `Math.abs` to also block far-future timestamps; the timestamp is itself covered by the signature, so the check can't be bypassed by tampering.
- Secret rotation: current and previous secrets both accepted; identical error responses regardless of which matched, so the loop doesn't leak which key verified.
- Event ID dedup runs only after signature verification, preventing unauthenticated cache poisoning; the in-memory store should be replaced with Redis (10-minute TTL) for multi-instance deployments.

# Webhook HMAC-SHA256 Verification Middleware

Here's a sketch using Express/Node.js, with the security requirements that matter most:

```javascript
const crypto = require("crypto");
const express = require("express");

const app = express();

// CRITICAL: capture the raw body BEFORE any parsing middleware mutates it.
// JSON parsers re-serialize and would break the signature.
app.use(
  express.json({
    verify: (req, res, buf, encoding) => {
      req.rawBody = buf; // Buffer of the exact bytes received
    },
  })
);

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.headers["x-signature-256"]; // e.g. "sha256=<hex>"

  // 1. Fail closed: missing header or raw body => reject
  if (!signatureHeader || !req.rawBody) {
    return res.status(401).json({ error: "Missing signature" });
  }

  // 2. Parse expected format ("sha256=<hexdigest>")
  const parts = signatureHeader.split("=");
  if (parts.length !== 2 || parts[0] !== "sha256") {
    return res.status(401).json({ error: "Malformed signature header" });
  }
  const received = parts[1];

  // 3. Compute HMAC over the raw bytes with the shared secret
  const expected = crypto
    .createHmac("sha256", process.env.WEBHOOK_SECRET)
    .update(req.rawBody)
    .digest("hex");

  // 4. Constant-time comparison — never use === (timing attacks)
  const a = Buffer.from(received, "utf8");
  const b = Buffer.from(expected, "utf8");
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  next();
}

// Apply to webhook routes only
app.post("/webhooks/events", verifyWebhookSignature, (req, res) => {
  // Signature verified; req.body is now safe to use
  res.status(202).json({ received: true });
});
```

## Key security requirements baked in

1. **Raw body, not parsed body** — HMAC must be computed over the exact bytes received. Use the `verify` hook (or `express.raw()`) to stash the raw buffer before JSON parsing.
2. **Constant-time comparison** — `crypto.timingSafeEqual` prevents timing side channels. Never compare digests with `===`.
3. **Fail closed** — missing/malformed headers or raw body → 401, never fall through to the handler.
4. **Secret from environment** — never hardcode the webhook secret; never log it.
5. **Length check before `timingSafeEqual`** — it throws on mismatched lengths, so guard it.
6. **Return 202/200 on success** — acknowledge quickly and process asynchronously so slow handlers don't cause provider retries or DoS your endpoint.

## Optional hardening (recommended)

- **Timestamp/replay protection**: require an `x-timestamp` header, include it in the signed payload, and reject requests outside a ~5 minute window.
- **Raw-body route isolation**: mount `express.raw({ type: "*/*" })` only on the webhook path so other routes aren't affected.
- **Rate limiting** on the webhook route to blunt brute-force attempts against the secret.
- **Distinct secrets per provider** if you accept webhooks from multiple sources.

