# Updated Middleware: Secret Rotation + Event-ID Dedup

Two new requirements layered on top: accept signatures from **either the current or previous secret**, and **reject repeated event IDs for 10 minutes**.

```javascript
const crypto = require("crypto");
const express = require("express");

const app = express();

// Raw body capture — unchanged, still critical
app.use(
  express.json({
    verify: (req, res, buf) => {
      req.rawBody = buf;
    },
  })
);

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;   // timestamp freshness window
const DEDUP_TTL_MS = 10 * 60 * 1000;       // event-ID dedup window

// --- In-memory dedup cache (swap for Redis in multi-instance deployments) ---
const seenEventIds = new Map(); // eventId -> expiry (ms)

function isDuplicate(eventId) {
  const now = Date.now();

  // Lazy cleanup: purge expired entries occasionally
  if (seenEventIds.size > 10_000) {
    for (const [id, expiry] of seenEventIds) {
      if (expiry <= now) seenEventIds.delete(id);
    }
  }

  if (seenEventIds.has(eventId)) return true;
  seenEventIds.set(eventId, now + DEDUP_TTL_MS);
  return false;
}

// --- Secret management: current + previous ---
function getActiveSecrets() {
  return [process.env.WEBHOOK_SECRET, process.env.WEBHOOK_SECRET_PREV]
    .filter(Boolean); // tolerate a brief window with no previous secret
}

function computeExpectedSignature(secret, timestampHeader, rawBody) {
  const hmac = crypto.createHmac("sha256", secret);
  hmac.update(timestampHeader.trim());
  hmac.update(".");
  hmac.update(rawBody);
  return hmac.digest("hex");
}

function verifyWebhookSignature(req, res, next) {
  const signatureHeader = req.headers["x-signature-256"]; // "sha256=<hex>"
  const timestampHeader = req.headers["x-timestamp"];
  const eventIdHeader = req.headers["x-event-id"];

  // 1. Fail closed on anything missing or malformed
  if (!signatureHeader || !timestampHeader || !req.rawBody || !eventIdHeader) {
    return res.status(401).json({ error: "Missing required headers or body" });
  }

  const parts = signatureHeader.split("=");
  if (parts.length !== 2 || parts[0] !== "sha256") {
    return res.status(401).json({ error: "Malformed signature header" });
  }
  const received = parts[1];

  // 2. Timestamp validation (strict parse, 5-minute window, both directions)
  const timestamp = parseInt(timestampHeader, 10);
  if (!Number.isInteger(timestamp) || String(timestamp) !== timestampHeader.trim()) {
    return res.status(401).json({ error: "Malformed timestamp" });
  }
  const age = Date.now() - timestamp * 1000;
  if (age > MAX_CLOCK_SKEW_MS || age < -MAX_CLOCK_SKEW_MS) {
    return res.status(401).json({ error: "Timestamp outside allowed window" });
  }

  // 3. Try each active secret; constant-time compare against each
  let signatureValid = false;
  for (const secret of getActiveSecrets()) {
    const expected = computeExpectedSignature(secret, timestampHeader, req.rawBody);
    const a = Buffer.from(received, "utf8");
    const b = Buffer.from(expected, "utf8");
    if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
      signatureValid = true;
      break;
    }
  }
  if (!signatureValid) {
    return res.status(401).json({ error: "Invalid signature" });
  }

  // 4. Replay protection: reject repeated event IDs for 10 minutes.
  //    IMPORTANT: only after signature verification, so attackers can't
  //    poison the dedup cache with bogus IDs.
  if (isDuplicate(eventIdHeader)) {
    return res.status(200).json({ received: true, duplicate: true });
    // 200 (not 401/409) so the provider doesn't retry a legitimate
    // duplicate delivery. Log it for observability.
  }

  next();
}

app.post("/webhooks/events", verifyWebhookSignature, (req, res) => {
  res.status(202).json({ received: true });
});
```

## Security requirements carried forward (all still enforced)

1. **Raw body** — HMAC over exact bytes; parse only after verification.
2. **Constant-time comparison** — `crypto.timingSafeEqual` with length guard, never `===`.
3. **Fail closed** — missing/malformed inputs → 401 before the handler runs.
4. **Secrets from environment** — never hardcoded or logged.
5. **Signed payload = `timestamp + "." + raw_body`** — timestamp string signed exactly as transmitted.
6. **Five-minute freshness window** — stale and far-future timestamps rejected; strict integer parsing.

## New requirements in this version

7. **Dual-secret acceptance** — the signature is checked against the current secret, then the previous one. This makes rotation zero-downtime: rotate the provider's configured secret, then demote the old secret to `WEBHOOK_SECRET_PREV`, then remove it entirely once all in-flight signed requests have expired (the 5-minute timestamp window bounds this — wait at least one full window plus retry latency before dropping the old secret).
8. **Event-ID dedup, 10-minute window** — repeated IDs are rejected. Two deliberate design choices:
   - **Dedup check runs *after* signature verification.** If it ran first, an attacker could spray random event IDs to evict or pre-fill cache entries, poisoning dedup state for legitimate deliveries.
   - **Duplicates return 200, not an error.** Providers often retry on non-2xx; a legitimate duplicate delivery shouldn't trigger a retry loop. Log it and move on.

## Operational caveats

- **Multi-instance deployments**: this in-memory `Map` only dedups per-process. Behind a load balancer, use Redis (or similar) with `SET eventId NX EX 600` so the 10-minute window is shared across instances.
- **Memory bound**: the lazy purge keeps the map from growing unbounded; a periodic timer or Redis TTL handles this more cleanly in production.
- **Rotation runbook**: keep the previous secret loaded for at least one timestamp window (5 min) plus the provider's max retry backoff before deleting it, or in-flight deliveries signed with the old secret will start failing.

