# Final TypeScript Pseudocode: Webhook Signature Verification

Consolidated version with all accumulated requirements. Status codes: **401** for bad signature or stale timestamp, **409** for replay.

```typescript
import { createHmac, timingSafeEqual } from "crypto";
import type { Request, Response, NextFunction } from "express";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;   // timestamp freshness window
const DEDUP_TTL_MS      = 10 * 60 * 1000;  // event-ID dedup window

// Current + previous secret (rotation). Never hardcode; never log.
function getActiveSecrets(): string[] {
  return [process.env.WEBHOOK_SECRET, process.env.WEBHOOK_SECRET_PREV]
    .filter((s): s is string => Boolean(s));
}

// ---------------------------------------------------------------------------
// Raw body capture — must run BEFORE JSON parsing.
// HMAC covers the exact bytes received; a parsed/re-serialized body breaks it.
// ---------------------------------------------------------------------------
function captureRawBody(req: Request, _res: Response, buf: Buffer): void {
  req.rawBody = buf;
}

// app.use(express.json({ verify: captureRawBody }));

// ---------------------------------------------------------------------------
// Event-ID dedup cache (in-memory sketch; use Redis SET NX EX 600
// for multi-instance deployments)
// ---------------------------------------------------------------------------
const seenEventIds = new Map<string, number>(); // eventId -> expiry (ms)

function isDuplicate(eventId: string): boolean {
  const now = Date.now();

  // Lazy purge to bound memory
  if (seenEventIds.size > 10_000) {
    for (const [id, expiry] of seenEventIds) {
      if (expiry <= now) seenEventIds.delete(id);
    }
  }

  if (seenEventIds.has(eventId)) return true;
  seenEventIds.set(eventId, now + DEDUP_TTL_MS);
  return false;
}

// ---------------------------------------------------------------------------
// Signature helpers
// ---------------------------------------------------------------------------
function computeExpectedSignature(
  secret: string,
  timestampHeader: string,
  rawBody: Buffer
): string {
  // Signed payload = timestamp + "." + raw_body, exact bytes as transmitted
  const hmac = createHmac("sha256", secret);
  hmac.update(timestampHeader.trim());
  hmac.update(".");
  hmac.update(rawBody);
  return hmac.digest("hex");
}

function constantTimeHexEqual(received: string, expected: string): boolean {
  const a = Buffer.from(received, "utf8");
  const b = Buffer.from(expected, "utf8");
  // Length guard: timingSafeEqual throws on length mismatch
  return a.length === b.length && timingSafeEqual(a, b);
}

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------
function verifyWebhookSignature(req: Request, res: Response, next: NextFunction): void {
  const signatureHeader = req.headers["x-signature-256"] as string | undefined; // "sha256=<hex>"
  const timestampHeader = req.headers["x-timestamp"] as string | undefined;
  const eventIdHeader   = req.headers["x-event-id"] as string | undefined;

  // --- 1. Fail closed: anything missing or malformed => 401 ---
  if (!signatureHeader || !timestampHeader || !eventIdHeader || !req.rawBody) {
    res.status(401).json({ error: "Missing required headers or body" });
    return;
  }

  const parts = signatureHeader.split("=");
  if (parts.length !== 2 || parts[0] !== "sha256") {
    res.status(401).json({ error: "Malformed signature header" });
    return;
  }
  const received = parts[1];

  // --- 2. Timestamp: strict parse + 5-minute window (both directions) => 401 ---
  const timestamp = parseInt(timestampHeader, 10);
  if (!Number.isInteger(timestamp) || String(timestamp) !== timestampHeader.trim()) {
    res.status(401).json({ error: "Malformed timestamp" });
    return;
  }
  const age = Date.now() - timestamp * 1000;
  if (age > MAX_CLOCK_SKEW_MS || age < -MAX_CLOCK_SKEW_MS) {
    res.status(401).json({ error: "Timestamp outside allowed window" });
    return;
  }

  // --- 3. Signature: try current then previous secret, constant-time compare ---
  let signatureValid = false;
  for (const secret of getActiveSecrets()) {
    const expected = computeExpectedSignature(secret, timestampHeader, req.rawBody);
    if (constantTimeHexEqual(received, expected)) {
      signatureValid = true;
      break;
    }
  }
  if (!signatureValid) {
    res.status(401).json({ error: "Invalid signature" });
    return;
  }

  // --- 4. Replay check: AFTER signature verification (prevents cache
  //        poisoning via bogus IDs). Duplicate => 409. ---
  if (isDuplicate(eventIdHeader)) {
    res.status(409).json({ error: "Duplicate event" });
    return;
  }

  next();
}

// app.post("/webhooks/events", verifyWebhookSignature, handler);
```

## Complete security requirements enforced

| # | Requirement | Enforcement |
|---|---|---|
| 1 | HMAC-SHA256 over **raw request body** | Raw buffer captured pre-parse via `verify` hook; signed payload is `timestamp + "." + rawBody` |
| 2 | **Constant-time comparison** | `timingSafeEqual` with length guard; never `===` |
| 3 | **Fail closed** | Any missing/malformed header or body → 401 before handler runs |
| 4 | Secrets from **environment only** | `WEBHOOK_SECRET` / `WEBHOOK_SECRET_PREV`; never hardcoded or logged |
| 5 | **5-minute timestamp window** | Stale *and* far-future timestamps rejected with 401; strict integer parsing (`"123abc"`, `"1e3"` rejected) |
| 6 | **Secret rotation** | Signature checked against current, then previous secret — zero-downtime rotation |
| 7 | **10-minute event-ID dedup** | Repeated event IDs rejected with **409**; check runs *after* signature verification so attackers can't poison the dedup cache |
| 8 | **Status codes** | 401: bad signature, stale timestamp, missing/malformed inputs. 409: verified-but-replayed event ID. 202: accepted (handler) |

## Operational notes

- **409 on replay**: since the request is signature-verified, a 409 signals a genuine duplicate delivery. If your provider retries aggressively on non-2xx, consider returning 200 with a `duplicate: true` flag instead — but per the stated requirement, this version returns 409.
- **Multi-instance**: replace the in-memory `Map` with Redis `SET eventId NX EX 600` so the 10-minute window is shared across all instances.
- **Rotation runbook**: keep `WEBHOOK_SECRET_PREV` loaded for at least one timestamp window (5 min) plus the provider's max retry backoff before deleting it.
- **Handler hygiene**: return 202 and process asynchronously so slow handlers don't trigger provider retries or DoS the endpoint.

# HMAC-SHA256 Webhook Signature Verification Middleware

Here's a sketch using Express/Node.js:

```javascript
const crypto = require('crypto');

/**
 * Middleware factory: verifies HMAC-SHA256 webhook signature.
 *
 * @param {string} secret - shared secret (from env/config, never hardcoded)
 * @param {object} opts
 * @param {string} opts.header        - header containing the signature (default: x-signature)
 * @param {string} [opts.timestampHeader] - if set, also enforce timestamp freshness
 * @param {number} [opts.toleranceSeconds=300] - max age of timestamp
 */
function verifyWebhookHmac(secret, opts = {}) {
  const {
    header = 'x-signature',
    timestampHeader,
    toleranceSeconds = 300,
  } = opts;

  if (!secret || typeof secret !== 'string') {
    throw new Error('Webhook secret must be a non-empty string');
  }

  return function webhookVerifier(req, res, next) {
    // 1. Capture the RAW body — must be captured before any parsing
    //    (e.g., via a body-parser verify hook, see note below)
    const rawBody = req.rawBody;

    if (!Buffer.isBuffer(rawBody)) {
      return res.status(400).json({ error: 'Raw body unavailable' });
    }

    // 2. Extract signature from header
    const provided = req.get(header);
    if (!provided) {
      return res.status(401).json({ error: 'Missing signature' });
    }

    // 3. Optional: replay protection via timestamp
    if (timestampHeader) {
      const ts = Number(req.get(timestampHeader));
      if (!Number.isFinite(ts)) {
        return res.status(401).json({ error: 'Invalid timestamp' });
      }
      const age = Math.abs(Math.floor(Date.now() / 1000) - ts);
      if (age > toleranceSeconds) {
        return res.status(401).json({ error: 'Timestamp outside tolerance' });
      }
    }

    // 4. Compute expected HMAC over the raw bytes
    const expected = crypto
      .createHmac('sha256', secret)
      .update(rawBody)
      .digest('hex');

    // 5. Constant-time comparison — never use === on signatures
    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(provided, 'utf8');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

module.exports = { verifyWebhookHmac };
```

## Capturing the raw body

The critical prerequisite — signature verification must happen on the *exact bytes* the sender signed, so you need the raw body before JSON parsing mutates it:

```javascript
app.use(
  express.json({
    verify: (req, res, buf) => {
      req.rawBody = buf; // preserve untouched bytes
    },
  })
);

app.post('/webhooks/stripe', verifyWebhookHmac(process.env.WEBHOOK_SECRET), (req, res) => {
  // req.body is parsed AND verified
  res.status(200).json({ received: true });
});
```

## Key security points

1. **Raw body, not parsed body** — re-serializing JSON changes byte order/whitespace and breaks the signature.
2. **`crypto.timingSafeEqual`** — prevents timing side-channel attacks; plain `===` comparison leaks match length.
3. **Length check before `timingSafeEqual`** — the Node API throws on length mismatch, so guard it explicitly.
4. **Secret from environment/config** — never commit it; reject startup if missing.
5. **Optional timestamp + tolerance** — mitigates replay attacks; include the timestamp in the signed payload if the provider's scheme requires it.
6. **Fail closed** — any missing header, missing raw body, or malformed input returns 401/400, never falls through to the handler.
7. **Provider-specific formats** — some providers prefix signatures (e.g., Stripe uses `t=...,v1=...` scheme signing timestamp+body); adapt the digest input accordingly.

