# Updated: HMAC over `timestamp + '.' + raw_body`

```javascript
const crypto = require('crypto');

/**
 * Verifies HMAC-SHA256 where the signed payload is:
 *   `${timestamp}.${rawBody}`
 *
 * - Timestamp must be within 5 minutes of server time (replay protection).
 * - Comparison uses crypto.timingSafeEqual (constant-time).
 */
function verifyWebhookHmac(secret, opts = {}) {
  const {
    signatureHeader = 'x-signature',
    timestampHeader = 'x-timestamp',
    toleranceSeconds = 300, // 5 minutes
  } = opts;

  if (!secret || typeof secret !== 'string') {
    throw new Error('Webhook secret must be a non-empty string');
  }

  return function webhookVerifier(req, res, next) {
    // 1. Raw body must have been captured before parsing
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(400).json({ error: 'Raw body unavailable' });
    }

    // 2. Required headers
    const providedSig = req.get(signatureHeader);
    const timestamp = req.get(timestampHeader);
    if (!providedSig || !timestamp) {
      return res.status(401).json({ error: 'Missing signature or timestamp' });
    }

    // 3. Timestamp freshness — reject anything older than 5 minutes
    const ts = Number(timestamp);
    if (!Number.isFinite(ts)) {
      return res.status(401).json({ error: 'Invalid timestamp' });
    }
    const now = Math.floor(Date.now() / 1000);
    if (Math.abs(now - ts) > toleranceSeconds) {
      return res.status(401).json({ error: 'Timestamp outside tolerance window' });
    }

    // 4. Build the exact signed payload: timestamp + '.' + raw body
    const signedPayload = Buffer.concat([
      Buffer.from(`${ts}.`, 'utf8'),
      rawBody,
    ]);

    // 5. Compute expected HMAC-SHA256
    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest('hex');

    // 6. Constant-time comparison (with explicit length guard,
    //    since timingSafeEqual throws on length mismatch)
    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(providedSig, 'utf8');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

module.exports = { verifyWebhookHmac };
```

## Usage

```javascript
app.use(
  express.json({
    verify: (req, res, buf) => { req.rawBody = buf; },
  })
);

app.post(
  '/webhooks',
  verifyWebhookHmac(process.env.WEBHOOK_SECRET),
  (req, res) => res.status(200).json({ received: true })
);
```

## Security notes carried forward

1. **Exact signed bytes** — the HMAC input is `timestamp + '.' + rawBody` with the raw, unparsed body buffer; re-serialized JSON would break the signature.
2. **5-minute window** — `Math.abs(now - ts) > 300` rejects both stale (replayed) and future-dated timestamps; fail closed on non-numeric timestamps.
3. **Constant-time compare** — `crypto.timingSafeEqual` with an explicit length check; never `===` on secrets.
4. **Fail closed** — missing headers, missing raw body, bad timestamp, or bad signature all return 401/400 before the handler runs.
5. **Secret hygiene** — loaded from environment, validated at startup, never logged.
6. **Order of checks** — timestamp is validated *before* computing the HMAC, so expired requests are rejected cheaply without revealing anything about signature validity.

# Updated: Secret Rotation + Event ID Replay Protection

```javascript
const crypto = require('crypto');

/**
 * Verifies HMAC-SHA256 webhooks where the signed payload is:
 *   `${timestamp}.${rawBody}`
 *
 * Security requirements:
 *  - Raw body (unparsed bytes) is the HMAC input.
 *  - Timestamp must be within 5 minutes of server time.
 *  - Constant-time signature comparison (crypto.timingSafeEqual).
 *  - Accepts EITHER the current or previous secret (rotation support).
 *  - Rejects repeated event IDs within a 10-minute window.
 */
function verifyWebhookHmac({ currentSecret, previousSecret }, opts = {}) {
  const {
    signatureHeader = 'x-signature',
    timestampHeader = 'x-timestamp',
    eventIdHeader = 'x-event-id',
    toleranceSeconds = 300,   // 5 minutes
    replayWindowMs = 10 * 60 * 1000, // 10 minutes
  } = opts;

  // Fail closed at startup if the current secret is missing
  if (!currentSecret || typeof currentSecret !== 'string') {
    throw new Error('Current webhook secret must be a non-empty string');
  }
  // previousSecret is optional (no rotation in flight), but must be a string if present
  if (previousSecret !== undefined && typeof previousSecret !== 'string') {
    throw new Error('Previous webhook secret must be a string');
  }

  // Secrets to try, in preference order (current first)
  const secrets = previousSecret ? [currentSecret, previousSecret] : [currentSecret];

  // Replay cache: eventId -> expiry (ms epoch)
  const seenEvents = new Map();

  // Periodic sweep so the cache doesn't grow unboundedly
  const sweepInterval = setInterval(() => {
    const now = Date.now();
    for (const [id, expiresAt] of seenEvents) {
      if (expiresAt <= now) seenEvents.delete(id);
    }
  }, 60 * 1000);
  sweepInterval.unref?.();

  return function webhookVerifier(req, res, next) {
    // 1. Raw body must have been captured before parsing
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(400).json({ error: 'Raw body unavailable' });
    }

    // 2. Required headers
    const providedSig = req.get(signatureHeader);
    const timestamp = req.get(timestampHeader);
    const eventId = req.get(eventIdHeader);
    if (!providedSig || !timestamp || !eventId) {
      return res.status(401).json({ error: 'Missing signature, timestamp, or event ID' });
    }

    // 3. Timestamp freshness — reject anything older than 5 minutes
    //    (also rejects future-dated timestamps)
    const ts = Number(timestamp);
    if (!Number.isFinite(ts)) {
      return res.status(401).json({ error: 'Invalid timestamp' });
    }
    const nowSec = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSec - ts) > toleranceSeconds) {
      return res.status(401).json({ error: 'Timestamp outside tolerance window' });
    }

    // 4. Build the exact signed payload: timestamp + '.' + raw body
    const signedPayload = Buffer.concat([
      Buffer.from(`${ts}.`, 'utf8'),
      rawBody,
    ]);

    // 5. Try each secret (current first). Constant-time comparison per attempt.
    const providedBuf = Buffer.from(providedSig, 'utf8');
    let signatureValid = false;

    for (const secret of secrets) {
      const expected = crypto
        .createHmac('sha256', secret)
        .update(signedPayload)
        .digest('hex');
      const expectedBuf = Buffer.from(expected, 'utf8');

      // Length guard: timingSafeEqual throws on mismatched lengths
      if (expectedBuf.length === providedBuf.length &&
          crypto.timingSafeEqual(expectedBuf, providedBuf)) {
        signatureValid = true;
        break;
      }
    }

    if (!signatureValid) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // 6. Replay protection — reject a repeated event ID within 10 minutes.
    //    Checked AFTER signature verification so attackers can't poison the
    //    cache with arbitrary IDs.
    const nowMs = Date.now();
    const existing = seenEvents.get(eventId);
    if (existing !== undefined && existing > nowMs) {
      return res.status(409).json({ error: 'Duplicate event ID' });
    }
    seenEvents.set(eventId, nowMs + replayWindowMs);

    next();
  };
}

module.exports = { verifyWebhookHmac };
```

## Usage

```javascript
app.use(
  express.json({
    verify: (req, res, buf) => { req.rawBody = buf; },
  })
);

app.post(
  '/webhooks',
  verifyWebhookHmac({
    currentSecret: process.env.WEBHOOK_SECRET,
    previousSecret: process.env.WEBHOOK_SECRET_PREV, // optional during rotation
  }),
  (req, res) => res.status(200).json({ received: true })
);
```

## Security notes (all prior requirements preserved)

1. **Raw body** — HMAC input is `timestamp + '.' + rawBody` using the untouched byte buffer; re-serialized JSON breaks the signature.
2. **5-minute timestamp window** — `Math.abs(now - ts) > 300` rejects stale and future-dated timestamps; fail closed on non-numeric values.
3. **Constant-time comparison** — `crypto.timingSafeEqual` with an explicit length guard on every secret attempt; never `===`.
4. **Rotation** — current secret is tried first, then previous; startup fails if the current secret is missing. Once rotation completes, unset the previous secret so old signatures stop validating.
5. **Replay cache ordering** — event IDs are recorded *only after* the signature verifies, so an attacker can't flood the cache and cause denial-of-service on legitimate events. Duplicates within 10 minutes get `409`.
6. **In-memory cache caveat** — the `Map` is per-process. For multi-instance deployments, back it with Redis (e.g., `SET eventId NX EX 600`) so replay protection is global. The sweep interval is `unref`'d so it doesn't block shutdown.
7. **Fail closed** — missing headers, missing raw body, bad timestamp, bad signature, or duplicate ID all reject before the handler runs.
8. **Secret hygiene** — secrets come from the environment, are validated at construction, and are never logged.

# Final: TypeScript Webhook Verification Middleware

```typescript
import { createHmac, timingSafeEqual } from 'crypto';

interface WebhookVerifierOptions {
  signatureHeader?: string;      // default: 'x-signature'
  timestampHeader?: string;      // default: 'x-timestamp'
  eventIdHeader?: string;        // default: 'x-event-id'
  toleranceSeconds?: number;     // default: 300 (5 minutes)
  replayWindowMs?: number;       // default: 10 minutes
}

interface WebhookSecrets {
  currentSecret: string;         // required, non-empty
  previousSecret?: string;       // optional, present only during rotation
}

/**
 * Middleware verifying HMAC-SHA256 webhooks.
 *
 * Signed payload: `${timestamp}.${rawBody}` (raw, unparsed bytes).
 *
 * Response contract:
 *   401 — missing headers, missing raw body, invalid/stale timestamp, bad signature
 *   409 — valid signature but repeated event ID within the replay window
 */
function verifyWebhookHmac(
  secrets: WebhookSecrets,
  opts: WebhookVerifierOptions = {}
): (req: Request, res: Response, next: NextFunction) => void {

  const {
    signatureHeader = 'x-signature',
    timestampHeader = 'x-timestamp',
    eventIdHeader = 'x-event-id',
    toleranceSeconds = 300,
    replayWindowMs = 10 * 60 * 1000,
  } = opts;

  // --- Startup validation: fail closed if secrets are unusable ---
  if (!secrets.currentSecret || typeof secrets.currentSecret !== 'string') {
    throw new Error('Current webhook secret must be a non-empty string');
  }
  if (secrets.previousSecret !== undefined && typeof secrets.previousSecret !== 'string') {
    throw new Error('Previous webhook secret must be a string');
  }

  // Secrets to try, current first (rotation support)
  const candidateSecrets: readonly string[] =
    secrets.previousSecret
      ? [secrets.currentSecret, secrets.previousSecret]
      : [secrets.currentSecret];

  // --- Replay cache: eventId -> expiry (ms epoch) ---
  const seenEvents = new Map<string, number>();

  // Periodic sweep to bound memory; unref'd so it never blocks shutdown
  const sweep = setInterval(() => {
    const now = Date.now();
    for (const [id, expiresAt] of seenEvents) {
      if (expiresAt <= now) seenEvents.delete(id);
    }
  }, 60_000);
  sweep.unref?.();

  return function webhookVerifier(req, res, next): void {
    // 1. Raw body must have been captured before any parsing
    const rawBody: Buffer | undefined = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      res.status(400).json({ error: 'Raw body unavailable' });
      return;
    }

    // 2. Required headers
    const providedSig: string | undefined = req.get(signatureHeader);
    const timestamp: string | undefined = req.get(timestampHeader);
    const eventId: string | undefined = req.get(eventIdHeader);
    if (!providedSig || !timestamp || !eventId) {
      res.status(401).json({ error: 'Missing signature, timestamp, or event ID' });
      return;
    }

    // 3. Timestamp freshness — reject stale or future-dated (401)
    const ts = Number(timestamp);
    if (!Number.isFinite(ts)) {
      res.status(401).json({ error: 'Invalid timestamp' });
      return;
    }
    const nowSec = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSec - ts) > toleranceSeconds) {
      res.status(401).json({ error: 'Timestamp outside tolerance window' });
      return;
    }

    // 4. Build the exact signed payload: timestamp + '.' + raw body
    const signedPayload: Buffer = Buffer.concat([
      Buffer.from(`${ts}.`, 'utf8'),
      rawBody,
    ]);

    // 5. Verify against current secret, then previous (rotation).
    //    Constant-time comparison on every attempt.
    const providedBuf: Buffer = Buffer.from(providedSig, 'utf8');
    let signatureValid = false;

    for (const secret of candidateSecrets) {
      const expected: string = createHmac('sha256', secret)
        .update(signedPayload)
        .digest('hex');
      const expectedBuf: Buffer = Buffer.from(expected, 'utf8');

      // Length guard: timingSafeEqual throws on length mismatch
      if (expectedBuf.length === providedBuf.length &&
          timingSafeEqual(expectedBuf, providedBuf)) {
        signatureValid = true;
        break;
      }
    }

    if (!signatureValid) {
      res.status(401).json({ error: 'Invalid signature' });
      return;
    }

    // 6. Replay protection — checked AFTER signature verification so
    //    attackers cannot poison the cache with arbitrary event IDs.
    //    Repeated event ID within the window -> 409.
    const nowMs = Date.now();
    const existingExpiry: number | undefined = seenEvents.get(eventId);
    if (existingExpiry !== undefined && existingExpiry > nowMs) {
      res.status(409).json({ error: 'Duplicate event ID' });
      return;
    }
    seenEvents.set(eventId, nowMs + replayWindowMs);

    next();
  };
}
```

## Wiring (raw body capture is mandatory)

```typescript
app.use(
  express.json({
    verify: (req, _res, buf) => { req.rawBody = buf; }, // preserve exact bytes
  })
);

app.post(
  '/webhooks',
  verifyWebhookHmac({
    currentSecret: process.env.WEBHOOK_SECRET!,        // validated at startup
    previousSecret: process.env.WEBHOOK_SECRET_PREV,   // unset after rotation completes
  }),
  (req, res) => res.status(200).json({ received: true })
);
```

## Consolidated security requirements

| # | Requirement | Enforcement |
|---|---|---|
| 1 | HMAC-SHA256 over raw request body | `req.rawBody` buffer, captured pre-parse; never re-serialized JSON |
| 2 | Signed payload = `timestamp + '.' + rawBody` | `Buffer.concat` of UTF-8 timestamp, `.`, raw bytes |
| 3 | Reject timestamps older than 5 minutes | `Math.abs(now - ts) > 300` → **401** (also rejects future-dated) |
| 4 | Constant-time comparison | `timingSafeEqual` with explicit length guard, every secret attempt |
| 5 | Accept current or previous secret | Try current first, then previous; drop previous after rotation |
| 6 | Reject repeated event ID for 10 minutes | Post-signature cache check → **409**; sweep bounds memory |
| 7 | Fail closed | Missing headers/raw body, bad timestamp, bad signature all reject before handler |
| 8 | Secret hygiene | Env-sourced, validated at construction, never logged |

**Deployment note:** the replay `Map` is per-process. For multi-instance deployments, replace it with a shared store (e.g., Redis `SET eventId NX EX 600`) so the 10-minute replay window is enforced globally.

# normalize(value)

```javascript
function normalize(value) {
  if (typeof value === 'string') {
    return value.trim();
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (value !== null && typeof value === 'object') {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }

  return value;
}
```

## How it works

- **Strings** are trimmed.
- **Arrays** are mapped through `normalize` recursively, producing a new array.
- **Plain objects** (and other non-null objects) are copied key-by-key with normalized values. Using `Object.keys` only copies own enumerable properties, dropping inherited ones.
- **Everything else** (numbers, booleans, `null`, `undefined`, functions, etc.) is returned as-is.

## Example

```javascript
normalize({
  name: '  Alice  ',
  tags: [' a ', ' b '],
  nested: { city: ' Paris ' },
  count: 42
});
// { name: 'Alice', tags: ['a', 'b'], nested: { city: 'Paris' }, count: 42 }
```

Note: this treats all non-array objects as plain objects. If you need to strictly handle *only* plain objects (rejecting `Date`, `RegExp`, class instances, etc.), let me know and I can add a `Object.getPrototypeOf(obj) === Object.prototype` check.

# normalize(value) — updated

```javascript
function normalize(value) {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? null : trimmed;
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (value !== null && typeof value === 'object') {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }

  return value;
}
```

## What changed

- Strings are trimmed first; if the result is an empty string, it becomes `null`.
- `0` and `false` are untouched — they fall through to the final `return value`, since the only early-return checks are for `typeof 'string'`, arrays, and non-null objects. No truthiness checks are used anywhere, so falsy-but-meaningful primitives are preserved.

## Examples

```javascript
normalize({ a: '  ', b: ' x ', c: 0, d: false, e: null });
// { a: null, b: 'x', c: 0, d: false, e: null }

normalize(['  ', '', ' keep ', 0, false]);
// [null, null, 'keep', 0, false]

normalize({ deep: { inner: '   ' } });
// { deep: { inner: null } }
```

Note: strings that are only whitespace (e.g. `'   '`) also become `null`, since trimming them yields `''`. If you want *only literally empty* strings converted and whitespace-only strings kept as `''`, let me know.

# normalize(value) — updated

```javascript
function normalize(value) {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? null : trimmed;
  }

  if (Array.isArray(value)) {
    return value.map(normalize); // null entries preserved
  }

  if (value !== null && typeof value === 'object') {
    const result = {};
    for (const key of Object.keys(value)) {
      if (value[key] === undefined) {
        continue; // omit undefined properties
      }
      result[key] = normalize(value[key]);
    }
    return result;
  }

  return value;
}
```

## What changed

- **Objects:** properties whose value is `undefined` are omitted entirely (the key doesn't appear in the output). Note the check happens *before* recursion — an explicitly-`undefined` property is dropped, and since `normalize(undefined)` would return `undefined` anyway, this also prevents re-introducing it.
- **Arrays:** unchanged — `map` keeps every index, so `null` entries (whether original or produced by empty-string normalization) stay in place. Array `undefined` entries are also preserved, since the omission rule applies only to object properties.

## Examples

```javascript
normalize({ a: undefined, b: ' x ', c: 0 });
// { b: 'x', c: 0 }   — 'a' omitted

normalize({ a: null, b: '  ' });
// { a: null, b: null }  — null properties kept, only undefined dropped

normalize(['  ', null, ' k ', undefined, 0]);
// [null, null, 'k', undefined, 0]  — all 5 entries preserved

normalize({ list: ['  ', null], skip: undefined });
// { list: [null, null] }
```

## Summary of rules so far

| Input | Output |
|---|---|
| String | trimmed; `''` (incl. whitespace-only) → `null` |
| `0`, `false`, `null`, other primitives | unchanged |
| Array | recursed per element, length/indexes preserved |
| Object | recursed per own key; `undefined`-valued keys omitted |

