# Assertions

```javascript
const assert = require('assert');

// 1. Empty/whitespace strings become null; 0 and false are preserved
assert.deepStrictEqual(
  normalize({ a: '   ', b: ' x ', c: 0, d: false }),
  { a: null, b: 'x', c: 0, d: false }
);

// 2. Undefined properties are omitted from objects
assert.deepStrictEqual(
  normalize({ keep: ' y ', drop: undefined, also: null }),
  { keep: 'y', also: null }
);

// 3. Null entries are not removed from arrays (length and positions kept)
assert.deepStrictEqual(
  normalize(['  ', null, ' k ', undefined, 0]),
  [null, null, 'k', undefined, 0]
);

console.log('All assertions passed.');
```

Each assertion maps to one correction: (1) empty-string→`null` with falsy primitives intact, (2) `undefined` property omission, (3) array `null`/`undefined` entry preservation.

```js
function normalize(value) {
  if (typeof value === "string") {
    return value.trim();
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (isPlainObject(value)) {
    const out = {};
    for (const [key, val] of Object.entries(value)) {
      out[key] = normalize(val);
    }
    return out;
  }

  return value;
}

function isPlainObject(value) {
  if (value === null || typeof value !== "object") return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}
