  name: "  Ada  ",
  empty: "   ",
  count: 0,
  active: false,
  tags: [" x ", ""]
});
// {
//   name: "Ada",
//   empty: null,
//   count: 0,        // preserved
//   active: false,   // preserved
//   tags: ["x", null]
// }
```

The empty-string check only applies to strings, so `0` and `false` pass through untouched.

